// Сгенерировано kb.py — не править руками
export const KB = [{"d":"Устав ВС и ФСВНГ","t":"Статья 1.1. Соблюдение Устава","x":"Каждый военнослужащий обязан знать и соблюдать положения настоящего Устава. Незнание Устава не освобождает от ответственности.","r":"ВУ ст. 1.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.2. Воинский долг","x":"Каждый военнослужащий обязан честно и качественно исполнять воинский долг, защищать национальные интересы, суверенитет и целостность территории Российской Федерации.","r":"ВУ ст. 1.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.3. Исполнение приказов","x":"Военнослужащий обязан исполнить законный приказ начальника. При получении заведомо незаконного приказа военнослужащий не исполняет его и незамедлительно докладывает непосредственному либо вышестоящему начальнику.","r":"ВУ ст. 1.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.4. Репутация Армии","x":"Запрещены действия, способные нанести ущерб репутации Армии или подорвать доверие к ней.","r":"ВУ ст. 1.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.5. Обращение по служебным вопросам","x":"При возникновении служебных вопросов военнослужащий обращается к командиру своего подразделения.","r":"ВУ ст. 1.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.6. Единоначалие","x":"Командир наделен распорядительной властью и несет персональную ответственность за подразделение.","r":"ВУ ст. 1.6"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.7. Построения","x":"Во время объявленного построения военнослужащие обязаны явиться в назначенное место точно и в срок, кроме лиц, несущих службу на посту.","r":"ВУ ст. 1.7"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.8. Набор","x":"Набор в ряды Армии осуществляется посредством агитационных мероприятий и призывов по утвержденному графику.","r":"ВУ ст. 1.8"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.9. КМБ и Военная академия","x":"Курс молодого бойца проходит не более чем за 5 дней, Военная академия - не более чем за 10 дней. После провала Военной академии военнослужащий заносится в черный список на срок от 14 до 90 дней по решению командования.","r":"ВУ ст. 1.9"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.10. Основания для увольнения","x":"Основаниями для увольнения являются: собственное желание; грубое нарушение Устава; нарушение законодательства; решение суда или предписание Прокуратуры; непрохождение КМБ или Военной академии; отсутствие в подразделении более 48 часов; нахождение в части без формы; самовольное оставление части; иные прямо предусмотренные настоящим Уставом основания. Наличие дисциплинарных взысканий влечет последствия в порядке, установленном Дисциплинарным уставом.","r":"ВУ ст. 1.10"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.11. Военная присяга","x":"Каждый военнослужащий, прибывший в часть и проходящий КМБ или Военную академию, обязан принять Военную присягу. Отказ от ее принятия или грубое нарушение присяги является основанием для увольнения.","r":"ВУ ст. 1.11"},{"d":"Устав ВС и ФСВНГ","t":"Статья 1.12. Сбережение имущества","x":"Военнослужащий обязан бережно относиться к вооружению, технике, обмундированию и иному государственному имуществу. Запрещены умышленная порча, неаккуратное использование служебного транспорта, утрата или небрежное хранение оружия и спецсредств, использование казенного имущества в личных целях.","r":"ВУ ст. 1.12"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.1. Служебный день","x":"Рабочий день для личного состава ВС и ФСВНГ устанавливается ежедневно с 11:00 до 21:30.","r":"ВУ ст. 2.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.2. Перерыв","x":"Обеденное время устанавливается ежедневно с 18:00 до 19:00 и предоставляется без оформления увольнительной.","r":"ВУ ст. 2.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.3. Вызов на службу","x":"Служебная деятельность не прекращается после завершения рабочего дня. Военнослужащий может быть вызван из отгула, кроме отпуска в мирное время.","r":"ВУ ст. 2.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.4. Вечерняя проверка","x":"Ежедневно в 21:00 проводится вечерняя проверка. Во время вечерней проверки постовые не покидают пост. Их присутствие подтверждается докладом по рации, через начальника караула либо после смены поста.","r":"ВУ ст. 2.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.5. Изменение графика","x":"Командир части вправе временно корректировать график приказом.","r":"ВУ ст. 2.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.6. Увольнительное время и выход из части","x":"Рядовой и ефрейтор могут покидать часть только по увольнительной, при наличии необходимых и непереносимых для увольнительной причин. Начиная со звания младший сержант, военнослужащий вправе запросить и получить увольнительное время продолжительностью 60 минут в день (можно разбить на два промежутка длительностью 30 минут). Младший сержант и выше могут покидать часть после окончания службы при отсутствии ограничений, наряда, тревоги или дисциплинарного запрета.","r":"ВУ ст. 2.6"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.7. Отпуск","x":"Младший сержант и выше имеют право на отпуск до 7 дней раз в месяц. По семейным обстоятельствам отпуск может быть предоставлен в ином объеме по решению вышестоящего командования.","r":"ВУ ст. 2.7"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.8. Отдых в части","x":"Для отдыха на территории части используются казарма, раздевалка и медицинский блок. Продолжительность отдыха не должна препятствовать службе.","r":"ВУ ст. 2.8"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.9. Повышенная готовность","x":"При переходе в режим повышенной боевой готовности (Код-4) часть переходит в круглосуточный режим, весь состав находится в расположении части.","r":"ВУ ст. 2.9"},{"d":"Устав ВС и ФСВНГ","t":"Статья 2.10. Плановый медицинский осмотр","x":"Плановый медицинский осмотр проводится до вечерней проверки либо после замены военнослужащего на посту. Он проводится в независимое от вечерней проверки время и назначается сотрудниками медицинской роты.","r":"ВУ ст. 2.10"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.1. Военная форма","x":"В расположении части и на официальных мероприятиях обязательна военная форма. Форма должна соответствовать подразделению и воинскому званию.","r":"ВУ ст. 3.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.2. Внешний вид и форма одежды","x":"Запрещаются спортивная и пляжная одежда, неопрятная одежда, яркие аксессуары, неустановленные знаки различия, криминальная или аморальная символика. Требования к прическе, бороде и усам устанавливаются настоящим Уставом и приказами командования.","r":"ВУ ст. 3.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.3. Требования к внешнему виду военнослужащих","x":"Новобранцы до присвоения звания младшего сержанта обязаны иметь полностью выбритую голову и не допускаются к службе при наличии растительности на лице. Начиная со звания младшего сержанта, прическа военнослужащего должна быть аккуратной, соответствовать требованиям гигиены и не препятствовать ношению головных уборов, средств индивидуальной защиты, включая каску и противогаз.","r":"ВУ ст. 3.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4. Обращение с оружием","x":"Военнослужащий обязан относиться к оружию как к заряженному, не направлять его на людей без непосредственной необходимости, не держать палец на спусковом крючке до принятия решения о выстреле и быть уверенным в цели и обстановке за ней.","r":"ВУ ст. 3.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4.1. Право на ношение табельного оружия","x":"Постоянное ношение табельного оружия при исполнении служебных обязанностей допускается всеми военнослужащими, наличие такого обязательно на период фактического несения караульно-постовой службы, патрулирования, учений, тренировок, специальных операций либо иной служебной деятельности.","r":"ВУ ст. 3.4.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.4.2. Сдача вооружения при выходе из части","x":"Военнослужащие в звании от рядового до подполковника включительно, покидающие территорию воинской части в гражданской форме, обязаны до выхода через контрольно-пропускной пункт сдать закрепленные за ними оружие, боеприпасы и специальные средства на склад вооружения. Запрещается оставлять табельное оружие, боеприпасы и специальные средства в личном транспортном средстве либо передавать их другому лицу без законных оснований. Исключение: ношение вооружения по гражданской форме допускается для военнослужащих ССО, ГРУ и Военной полиции при выполнении служебной или оперативной задачи, прямо предполагающей ношение оружия за пределами воинской части.","r":"ВУ ст. 3.4.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 3.5. Бодикамеры","x":"Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему и фиксирует обстоятельства в журнале.","r":"ВУ ст. 3.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.1. Иерархия","x":"Иерархическая структура Армии: Лидер Армии; Заместитель Лидера Армии; Начальник ВС и его заместители; Начальник ФСВНГ и его заместители; командиры подразделений.","r":"ВУ ст. 4.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.2. Должностные лица","x":"Лидер Армии осуществляет общее руководство. Заместитель Лидера действует в пределах порученных полномочий. Начальники ВС и ФСВНГ организуют работу подчиненных структур. Командиры подразделений обеспечивают службу и дисциплину личного состава.","r":"ВУ ст. 4.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.3. Подразделения","x":"Военная полиция обеспечивает правопорядок и дисциплину. Медицинская рота оказывает медицинскую помощь. ГРУ, ССО, МСК, ОСБ, РВО, ОМОН, Военная академия и Военный комиссариат выполняют задачи в пределах своей компетенции и приказов командования.","r":"ВУ ст. 4.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.4. Зоны ответственности","x":"Армия охраняет территорию воинской части, военный комиссариат, полигон “Алабино” и иные объекты, закрепленные приказами командования. Охрана не предоставляет военнослужащим право самостоятельно назначать гражданским лицам наказание. Приложение: полномочия по взысканиям: Командир подразделения вправе объявить устное предупреждение или выговор. Начальник ВС, Начальник ФСВНГ и их заместители вправе объявить строгий выговор и инициировать служебную проверку. Понижение в должности и увольнение рассматриваются Лидером Армии или уполномоченным им должностным лицом по результатам проверки. Полный перечень мер и порядок их применения определяются Дисциплинарным уставом.","r":"ВУ ст. 4.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 4.4.1. Военный полигон “Алабино”","x":"Военный полигон “Алабино” является учебно-тренировочной и режимной территорией Армии, предназначенной для проведения тактических занятий, учений, тренировок подразделений, отработки действий личного состава, эксплуатации военной техники и иных мероприятий боевой подготовки. На территории полигона “Алабино” допускаются тренировки военнослужащих, передвижение и эксплуатация служебной военной техники, патрулирование и проведение учебных мероприятий при соблюдении требований безопасности, режима объекта и распоряжений командования. Самовольный выезд военной техники за пределы полигона “Алабино”, использование техники не по назначению, создание помех учебным мероприятиям, повреждение имущества или инфраструктуры полигона “Алабино” запрещаются. Порядок охраны полигона “Алабино”, перечень постов и правила патрулирования устанавливаются Уставом караульно-постовой службы.","r":"ВУ ст. 4.4.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.1. Субординация","x":"Субординация является системой иерархических отношений, уважения дисциплины и исполнения законных приказов.","r":"ВУ ст. 5.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.2. Воинское приветствие","x":"Военнослужащие обязаны соблюдать правила воинского приветствия, доклада и обращения к старшим по званию.","r":"ВУ ст. 5.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.3. Действия в отношении граждан","x":"Военнослужащие вправе пресекать незаконное проникновение на территорию режимного объекта, ограничивать доступ, задерживать лицо при законных основаниях и передавать его ВП, МВД либо иному компетентному органу. Самостоятельное назначение наказания гражданским лицам не допускается.","r":"ВУ ст. 5.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 5.4. Применение силы","x":"Сила допускается только при нападении, непосредственной угрозе жизни, попытке незаконного проникновения или законном задержании. После применения силы обязательно: медицинская помощь при необходимости, доклад, фиксация на камеру и рапорт.","r":"ВУ ст. 5.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 6.1. Теги подразделений","x":"В служебной связи используются утвержденные теги подразделений: ВП, МР, ГРУ, ССО, МСК, ВК, ОСБ, РВО, ОМОН и КС. Полковники и выше могут использовать связь без тэга в порядке, установленном командованием.","r":"ВУ ст. 6.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 6.2. Коды обстановки","x":"Код-1 означает спокойную обстановку; Код-2 - скопление подозрительных лиц или нарушение порядка; Код-3 - проникновение, вооруженное нападение или массовое нарушение; Код-4 - боевую тревогу.","r":"ВУ ст. 6.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.1.1. Специальные операции","x":"Основная задача при поставках и специальных операциях - загрузка и доставка груза без утрат и задержек. Запрещены действия, препятствующие безопасности операции.","r":"ВУ ст. 7.1.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.1.2. Реакция на стрельбу","x":"ССО, ГРУ и ОМОН являются основными подразделениями реагирования. При непосредственной угрозе жизни, нападении на пост или проникновении любой военнослужащий действует в пределах необходимой обороны, докладывает по рации и вызывает группу реагирования.","r":"ВУ ст. 7.1.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.2. Военное положение","x":"При объявлении военного положения весь состав действует по распоряжениям Лидера Армии и командования, использует боевую форму и занимает назначенные позиции.","r":"ВУ ст. 7.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.3. Код-3","x":"При объявлении Кода-3 военнослужащий получает обмундирование, докладывает местоположение, направление и приметы нарушителя, а при наличии транспорта - марку, модель, цвет и номер. Подразделения действуют в пределах компетенции и приказов старшего.","r":"ВУ ст. 7.3"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.4. Обязанности постового","x":"Постовой обязан бдительно нести службу, требовать документы, не покидать пост до прибытия смены, немедленно докладывать о нештатной ситуации и применять оружие только в предусмотренных случаях.","r":"ВУ ст. 7.4"},{"d":"Устав ВС и ФСВНГ","t":"Статья 7.5. Единый порядок инцидента","x":"При обнаружении нарушения военнослужащий докладывает по рации, фиксирует обстоятельства на бодикамеру, ограничивает доступ или пресекает угрозу в пределах полномочий, вызывает ВП или дежурного, передает лицо уполномоченному сотруднику и оформляет рапорт.","r":"ВУ ст. 7.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.1. Отчеты","x":"Отчеты подаются по утвержденной форме. При обнаружении ошибки создается новый отчет в порядке, установленном командованием.","r":"ВУ ст. 8.1"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.2. Повышения","x":"Для повышения не должно быть активных дисциплинарных взысканий. Повышение проводится по системе подразделения и по представлению командира, согласованному с вышестоящим командованием.","r":"ВУ ст. 8.2"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.2.5. Повышение военнослужащего на посту","x":"Военнослужащий, несущий службу на посту, проходит процедуру повышения после сдачи поста либо через представителя подразделения.","r":"ВУ ст. 8.2.5"},{"d":"Устав ВС и ФСВНГ","t":"Статья 8.3. Повторный инструктаж","x":"После нарушения правил оружия, КПП, связи или постовой службы военнослужащий до повторного допуска проходит инструктаж или проверку знаний. Инструктаж не заменяет дисциплинарное взыскание, если оно подлежит применению. Приложения:","r":"ВУ ст. 8.3"},{"d":"Дисциплинарный устав","t":"Статья 1. Сфера действия и иерархия норм","x":"Настоящий Устав устанавливает основы воинской дисциплины, порядок применения дисциплинарных мер и меры поощрения военнослужащих Вооружённых Сил и сотрудников ФСВНГ.","r":"ДУ ст. 1"},{"d":"Дисциплинарный устав","t":"Статья 2. Воинская дисциплина","x":"Воинская дисциплина основывается на сознательном исполнении обязанностей, соблюдении субординации, уважении к службе и достоинству других лиц, бережном отношении к имуществу и готовности действовать в интересах подразделения. Военнослужащий обязан соблюдать законодательство и уставы, исполнять законные приказы, поддерживать порядок, не допускать действий, подрывающих безопасность службы или авторитет ведомства.","r":"ДУ ст. 2"},{"d":"Дисциплинарный устав","t":"Статья 3. Ответственность командования","x":"Командир организует службу, поддерживает дисциплину, рассматривает сведения о нарушениях в пределах компетенции и принимает меры, соразмерные тяжести проступка. Командиру запрещается унижать подчинённых, применять неуставное физическое или психологическое воздействие, скрывать сведения о серьёзном нарушении либо преследовать военнослужащего за добросовестное обращение.","r":"ДУ ст. 3"},{"d":"Дисциплинарный устав","t":"Статья 4. Полномочия Военной полиции и ОСБ","x":"Военная полиция выявляет нарушения, самостоятельно рассматривает \\ выносит \\ решает вопросы по привлечению к ответственности военнослужащих, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, обеспечивает порядок на военных объектах и передаёт информацию о нарушениях уполномоченным должностным лицам. Военная полиция действует в рамках законодательства и уставов. При выявлении нарушения сотрудником ФСВНГ, включая РВО, Кадровую службу и ОМОН, Военная полиция передаёт материалы и сведения в ОСБ. Самостоятельно дисциплинарные взыскания сотрудникам ФСВНГ Военная полиция не назначает. При выявлении нарушения сотрудником ВС, ОСБ передаёт материалы и сведения в военную полицию. Самостоятельно дисциплинарные взыскания сотрудникам ВС ОСБ не назначает. ОСБ рассматривает полученную информацию, самостоятельно рассматривает \\ выносит \\ решает вопросы по привлечению к ответственности ФСВНГ, в том числе по вопросам административной, дисциплинарной, уголовной в соответствие с процессуальным законодательством, и действует в пределах своей компетенции. Решение о дисциплинарной ответственности принимается уполномоченным должностным лицом после проверки обстоятельств. ОСБ работает по нарушениям только внутри подразделений ФСВНГ.","r":"ДУ ст. 4"},{"d":"Дисциплинарный устав","t":"Статья 5. Принципы дисциплинарной ответственности","x":"Взыскание применяется за виновное нарушение и должно быть справедливым, соразмерным его характеру, последствиям, роли лица и обстоятельствам совершения. При назначении взыскания учитываются признание вины, содействие проверке, повторность, степень опасности нарушения и прежнее отношение военнослужащего к службе. За один проступок не может назначаться более одного дисциплинарного взыскания. Дисциплинарное взыскание не заменяет ответственность, установленную законодательством. При выборе меры учитываются тяжесть нарушения, последствия, степень вины, повторность и поведение военнослужащего. Взыскание должно быть адекватным и соразмерным проступку. Если статья предусматривает несколько возможных мер, уполномоченное лицо выбирает одну из них с учётом обстоятельств нарушения.","r":"ДУ ст. 5"},{"d":"Дисциплинарный устав","t":"Статья 6. Виды дисциплинарных взысканий","x":"К военнослужащему или сотруднику, признанному виновным в дисциплинарном проступке, в пределах компетенции могут применяться следующие меры: - беседа (устное предупреждение) - применяется за малозначительное нарушение и не вносится в планшет; - устный выговор - применяется за нарушение средней тяжести и учитывается в планшете как один активный выговор; - строгий выговор - применяется за грубое, повторное либо создавшее угрозу нарушение и учитывается в планшете как два активных выговора; - понижение в должности или звании - только уполномоченным руководителем в порядке, установленном внутренними актами; - увольнение со службы - применяется за наиболее тяжкие нарушения, грубую повторность либо накопление активных выговоров; оформляется уполномоченным руководителем после рассмотрения материалов проверки.","r":"ДУ ст. 6"},{"d":"Дисциплинарный устав","t":"Статья 6.1. Учёт и отработка активных выговоров","x":"Устный выговор учитывается в планшете как один активный выговор. Строгий выговор учитывается в планшете как два активных выговора. Беседа в планшет не вносится. Военнослужащий обязан отработать активный выговор в течение 48 часов с момента его выдачи в порядке, установленном командованием или руководителем подразделения. Если активный выговор не отработан в течение 48 часов, военнослужащему выдаётся дополнительный устный выговор. Если выговор не отработан в течение 96 часов с момента первоначальной выдачи, выдаётся ещё один устный выговор. Накопление трёх активных выговоров в планшете влечёт увольнение со службы. Решение об увольнении оформляется уполномоченным руководителем после проверки актуальности выговоров и обстоятельств их выдачи. Отработанный, снятый либо признанный необоснованным выговор не учитывается при подсчёте активных выговоров. Если медицинское освобождение объективно препятствует установленной форме отработки выговора, военнослужащему предоставляется возможность отработки способом, совместимым с медицинскими ограничениями. При отсутствии доступного совместимого способа течение сроков отработки, включая сроки 48 и 96 часов, приостанавливается на период подтверждённой невозможности отработки. После окончания указанного периода течение оставшегося срока возобновляется. Приостановление и возобновление срока фиксируются уполномоченным должностным лицом. За период приостановления дополнительные взыскания за просрочку не применяются.","r":"ДУ ст. 6.1"},{"d":"Дисциплинарный устав","t":"Статья 7. Порядок рассмотрения нарушения","x":"До применения взыскания уполномоченное лицо устанавливает обстоятельства нарушения, проверяет доступные доказательства и, когда это возможно, получает объяснение лица, в отношении которого ведётся проверка. Решение должно содержать существо нарушения, применённую норму и вид взыскания. Лицо вправе обжаловать решение командованию либо в иной предусмотренный проектом орган. Неустранимые сомнения в обстоятельствах проступка толкуются в пользу военнослужащего или сотрудника.","r":"ДУ ст. 7"},{"d":"Дисциплинарный устав","t":"Статья 8. Нарушение субординации","x":"Неисполнение законного приказа, неуважительное обращение к командиру или иному старшему по должности, а равно действия, препятствующие исполнению приказа, являются нарушением субординации. Оскорбление, угроза, насилие либо иное грубое воздействие в отношении командира или старшего по должности рассматриваются как грубое нарушение субординации. Возможные меры: устный выговор, строгий выговор или увольнение при угрозе, насилии либо грубой повторности.","r":"ДУ ст. 8"},{"d":"Дисциплинарный устав","t":"Статья 9. Самовольное оставление места службы","x":"Самовольное оставление части, подразделения, места несения службы или самовольное прекращение исполнения служебной задачи без уважительной причины является дисциплинарным проступком. Тяжесть проступка определяется с учётом продолжительности отсутствия, последствий и статуса военнослужащего. Обстоятельства, объективно исключавшие возможность прибыть или продолжить службу, подлежат учёту. Подтверждённая невозможность продолжения службы по состоянию здоровья, экстренное обращение за медицинской помощью или эвакуация подлежат обязательному учёту при рассмотрении обстоятельств отсутствия. Невозможность своевременно доложить о состоянии здоровья сама по себе не образует нарушение, если она была объективно обусловлена состоянием военнослужащего. При первой возможности военнослужащий либо медицинский работник уведомляет командование. Возможные меры: устный выговор, строгий выговор или увольнение при оставлении поста, существенных последствиях либо повторном нарушении.","r":"ДУ ст. 9"},{"d":"Дисциплинарный устав","t":"Статья 10. Уклонение от службы и обязательных мероприятий","x":"Неявка без уважительной причины на обязательное построение, занятие, медицинский осмотр, инструктаж, служебное мероприятие или иной обязательный формат службы является дисциплинарным проступком. Уклонением от службы также является намеренное прекращение уже принятого военнослужащим наряда, патруля либо иной служебной задачи без передачи её в установленном порядке. Действующее медицинское освобождение является уважительной причиной неисполнения тех обязанностей и неявки на те мероприятия, на которые распространяются установленные ограничения. Ответственность за неявку на медицинский осмотр применяется при условии, что осмотр назначен уполномоченным лицом, требование доведено до военнослужащего и у него имелась возможность явиться. Несение постовой службы до прибытия смены, получение экстренной помощи и иные подтверждённые обстоятельства, объективно препятствующие явке, учитываются при установлении вины. Возможные меры: беседа, устный выговор, строгий выговор; при грубой повторности или срыве служебной задачи - увольнение.","r":"ДУ ст. 10"},{"d":"Дисциплинарный устав","t":"Статья 11. Нарушение порядка несения службы","x":"Ненадлежащее несение караульной, патрульной, внутренней или иной служебной обязанности, если оно создало угрозу безопасности, порядку или имуществу, является дисциплинарным проступком. Самостоятельное заступление на пост или патруль допускается в рамках действующих уставов. Отсутствие индивидуального назначения либо журнала поста не освобождает лицо от ответственности за нарушение фактически принятой им службы. Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенном вреде либо грубой повторности - увольнение.","r":"ДУ ст. 11"},{"d":"Дисциплинарный устав","t":"Статья 12. Нарушение порядка и общественной безопасности","x":"Действия или бездействие военнослужащего, нарушающие общественный порядок, безопасность военного объекта, установленный режим либо создающие угрозу гражданам, военнослужащим или имуществу, являются дисциплинарным проступком. Возможные меры: беседа, устный выговор или строгий выговор; при серьёзной угрозе безопасности, значимых последствиях либо грубой повторности - увольнение.","r":"ДУ ст. 12"},{"d":"Дисциплинарный устав","t":"Статья 12.1. Нарушение требований пожарной безопасности","x":"Нарушение требований пожарной безопасности, неосторожное обращение с огнём, создание пожароопасной ситуации, использование источников огня в запрещённой зоне либо игнорирование требований безопасности на складе, в казарме, гараже, технике или ином объекте Армии является дисциплинарным проступком. За нарушение может применяться беседа, устный выговор или строгий выговор. Если нарушение создало реальную угрозу жизни, повлекло ущерб имуществу либо совершено повторно, применяется строгий выговор или увольнение. Курение, использование электронных устройств для курения, кальянов и иных аналогичных средств в помещениях, на посту, на складе, вблизи техники, вооружения, горюче-смазочных материалов либо в иной запрещённой зоне является нарушением требований пожарной безопасности. Возможные меры: беседа, устный выговор или строгий выговор; при реальной угрозе жизни, ущербе имуществу либо повторном нарушении - строгий выговор или увольнение.","r":"ДУ ст. 12.1"},{"d":"Дисциплинарный устав","t":"Статья 13. Повреждение, утрата и незаконное использование имущества","x":"Умышленные либо небрежные действия, повлекшие утрату, порчу, повреждение или неправомерное использование государственного, ведомственного либо чужого имущества, являются дисциплинарным проступком. Нарушение, содержащее признаки преступления или административного правонарушения, передаётся для рассмотрения в порядке, установленном законодательством. Хищение, присвоение, незаконное удержание либо передача государственного, ведомственного или чужого имущества без законных оснований является грубым дисциплинарным проступком. За такое нарушение применяется строгий выговор или увольнение в зависимости от стоимости имущества, обстоятельств и последствий; при наличии признаков нарушения законодательства материалы передаются уполномоченному органу. Положения настоящей статьи распространяются на медицинские препараты, медицинское имущество и расходные материалы. Нарушение порядка учёта без установленных фактов утраты, присвоения, незаконной передачи или использования имущества не признаётся автоматически хищением либо утратой и оценивается по фактическим обстоятельствам. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера вины, стоимости имущества и наступивших последствий.","r":"ДУ ст. 13"},{"d":"Дисциплинарный устав","t":"Статья 14. Оружие, боеприпасы и специальные средства","x":"Нарушение правил хранения, учёта, переноски, передачи или применения оружия, боеприпасов и специальных средств является дисциплинарным проступком. Утеря, порча, оставление без присмотра либо небрежное хранение указанных предметов рассматриваются с учётом создаваемой опасности и наступивших последствий. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности нарушения, последствий и повторности.","r":"ДУ ст. 14"},{"d":"Дисциплинарный устав","t":"Статья 15. Состояние опьянения и запрещённые вещества","x":"Появление на службе в состоянии алкогольного, наркотического или иного опьянения, употребление запрещённых веществ во время службы, а равно необоснованный отказ от освидетельствования в случаях, предусмотренных законодательством, являются дисциплинарными проступками. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 15"},{"d":"Дисциплинарный устав","t":"Статья 16. Бездействие командира и незаконное привлечение к ответственности","x":"Умышленное бездействие командира при наличии сведений о существенном нарушении, сокрытие такого нарушения или воспрепятствование его проверке является дисциплинарным проступком. Привлечение военнослужащего к ответственности без оснований, вне компетенции либо с нарушением установленного порядка также является дисциплинарным проступком. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 16"},{"d":"Дисциплинарный устав","t":"Статья 17. Военная форма и внешний вид","x":"Нарушение правил ношения военной формы, знаков различия, средств индивидуальной защиты и иных обязательных элементов внешнего вида является дисциплинарным проступком, если оно не обусловлено служебной необходимостью. Требования к причёске, растительности на лице и гигиене устанавливаются общим уставом и обязательны в пределах, прямо предусмотренных таким уставом. Возможные меры: беседа, устный выговор или строгий выговор при повторном либо демонстративном нарушении.","r":"ДУ ст. 17"},{"d":"Дисциплинарный устав","t":"Статья 18. Честь ведомства и дискредитация","x":"Публичные действия, высказывания или материалы, содержащие оскорбление ведомства, его символики либо необоснованно подрывающие авторитет Вооружённых Сил или ФСВНГ, являются дисциплинарным проступком. Критика, обращение с жалобой или сообщение о нарушении не образуют проступка, если они сделаны добросовестно и в законной форме. Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.","r":"ДУ ст. 18"},{"d":"Дисциплинарный устав","t":"Статья 19. Служебная информация и документы","x":"Разглашение охраняемой служебной информации, несанкционированный доступ к ней, подделка, уничтожение или неправомерное использование служебных документов являются дисциплинарными проступками. Предоставление заведомо ложных сведений в рапорте, объяснении, отчёте или ином служебном документе рассматривается как самостоятельный проступок. К служебным документам относятся приказы и приказания, директивы, рапорты и доклады, акты и протоколы, справки и удостоверения, медицинские карточки, заключения, направления и документы учёта медицинских препаратов и имущества. Подделка таких документов, оформление фиктивного осмотра или освобождения, внесение заведомо ложных сведений, несанкционированное изменение записей либо разглашение охраняемых медицинских сведений рассматриваются по настоящей статье. Добросовестная техническая ошибка, исправленная в установленном порядке, сама по себе не признаётся подделкой или предоставлением заведомо ложных сведений. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от характера информации, последствий и повторности.","r":"ДУ ст. 19"},{"d":"Дисциплинарный устав","t":"Статья 20. Злоупотребление полномочиями и конфликт интересов","x":"Использование служебных полномочий, имущества, доступа, транспорта либо специального статуса в личных интересах, а также принятие решения при неурегулированном конфликте интересов являются дисциплинарными проступками. Служебные полномочия не могут использоваться для личной выгоды, давления на граждан или военнослужащих либо обхода установленной процедуры. Использование медицинского осмотра, заключения, освобождения или направления на обследование для личной выгоды, давления, мести либо вмешательства в кадровые решения вне предоставленных полномочий является злоупотреблением. Медицинское освобождение не допускается использовать в качестве дисциплинарного наказания. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 20"},{"d":"Дисциплинарный устав","t":"Статья 21. Поведение в строю и на территории части","x":"Военнослужащий обязан соблюдать порядок на построениях, плацу, в казармах и на территории части, не мешать проведению служебных мероприятий и не создавать опасность другим лицам. Самовольное передвижение бегом по плацу во время проведения построения при наличии сформированного строя запрещается. Исключение составляют случаи исполнения команды или распоряжения командования. Возможные меры: беседа, устный выговор или строгий выговор при повторном нарушении, срыве мероприятия либо создании опасности.","r":"ДУ ст. 21"},{"d":"Дисциплинарный устав","t":"Статья 22. Символика, ритуалы и азартные игры","x":"Надругательство над государственными или ведомственными символами, срыв установленного воинского ритуала, а также организация или участие в азартных играх в служебное время либо на служебной территории являются дисциплинарными проступками. Возможные меры: устный выговор, строгий выговор или увольнение при грубом, публичном либо повторном нарушении.","r":"ДУ ст. 22"},{"d":"Дисциплинарный устав","t":"Статья 23. Самоуправство и неуставные взаимоотношения","x":"Принуждение военнослужащего к действиям, не предусмотренным законодательством, уставом или законным приказом, самовольное применение взысканий, а равно унижение, травля или неуставное воздействие на подчинённого являются дисциплинарными проступками. Возможные меры: строгий выговор или увольнение. При наличии признаков нарушения законодательства материалы передаются уполномоченному органу.","r":"ДУ ст. 23"},{"d":"Дисциплинарный устав","t":"Статья 24. Оказание помощи","x":"Неоказание посильной помощи раненому, пострадавшему, военнослужащему, гражданину либо сотруднику, находящемуся в опасном состоянии, когда помощь могла быть оказана без неоправданного риска, является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение в зависимости от опасности ситуации и последствий неоказания помощи.","r":"ДУ ст. 24"},{"d":"Дисциплинарный устав","t":"Статья 25. Заведомо ложное сообщение и клевета","x":"Заведомо ложное сообщение о нарушении, преступлении или происшествии, а равно распространение заведомо недостоверных сведений, порочащих честь и достоинство другого лица, является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение при тяжких последствиях, грубой клевете либо повторном нарушении.","r":"ДУ ст. 25"},{"d":"Дисциплинарный устав","t":"Статья 26. Воспрепятствование законной деятельности","x":"Неповиновение законным требованиям уполномоченного сотрудника, создание препятствий проверке, служебному мероприятию либо законной деятельности государственного органа является дисциплинарным проступком. Возможные меры: устный выговор, строгий выговор или увольнение при умышленном срыве законной деятельности, угрозе либо грубой повторности.","r":"ДУ ст. 26"},{"d":"Дисциплинарный устав","t":"Статья 27. Халатность","x":"Неисполнение либо ненадлежащее исполнение обязанностей вследствие недобросовестного отношения к службе, если это повлекло или могло повлечь вред безопасности, порядку, имуществу или интересам службы, является дисциплинарным проступком. При оценке исполнения медицинских обязанностей учитываются подготовка работника, предоставленные полномочия, доступность необходимых средств и фактическая возможность оказать помощь. Неблагоприятный результат оказания помощи сам по себе не доказывает халатность. Необходимо установить конкретное нарушение обязанности, вину и предусмотренные настоящей статьёй обстоятельства. Неисполнение командиром доведённых до него действующих медицинских ограничений при наличии возможности обеспечить их соблюдение оценивается по настоящей статье либо иной применимой специальной норме с учётом характера вины и последствий. Возможные меры: беседа, устный выговор, строгий выговор или увольнение в зависимости от возможного либо наступившего вреда.","r":"ДУ ст. 27"},{"d":"Дисциплинарный устав","t":"Статья 28. Связи с преступной деятельностью","x":"Сокрытие достоверно известных сведений о подготовке либо совершении преступления, а также использование служебного положения в интересах преступной деятельности является дисциплинарным проступком и подлежит передаче для рассмотрения по законодательству. Возможные меры: строгий выговор или увольнение. Материалы подлежат передаче для рассмотрения по законодательству.","r":"ДУ ст. 28"},{"d":"Дисциплинарный устав","t":"Статья 29. Режим объекта, связь и транспорт","x":"Нарушение пропускного и внутриобъектового режима, правил служебной связи или использования служебного транспорта является дисциплинарным проступком. Ведение отдельного журнала поста или назначение военнослужащего на пост не являются обязательными условиями для признания нарушения. Значимые инциденты фиксируются служебным сообщением, рапортом либо иным установленным способом. Использование личного транспорта на территории воинской части допускается только по маршрутам и через пункты пропуска, прямо определённые действующим караульным уставом или распоряжением командования. Возможные меры: беседа, устный выговор или строгий выговор; при создании угрозы безопасности, существенных последствиях либо грубой повторности - увольнение.","r":"ДУ ст. 29"},{"d":"Дисциплинарный устав","t":"Статья 30. Иные нарушения","x":"Нарушение обязанностей, прямо установленных законодательством, настоящим Уставом, иными уставами или законным приказом, может являться дисциплинарным проступком при наличии вины и доказанных обстоятельств. Общая формулировка настоящей статьи не применяется для обхода специальных норм Устава или назначения взыскания за поведение, которое не было заранее запрещено либо не нарушило законную обязанность. Возможные меры: беседа, устный выговор или строгий выговор в пределах нарушенной конкретной нормы. Увольнение не может назначаться только на основании настоящей статьи.","r":"ДУ ст. 30"},{"d":"Дисциплинарный устав","t":"Статья 31. Основания для поощрения","x":"Поощрение применяется за добросовестную службу, инициативу, образцовое исполнение обязанностей, успешное выполнение сложной задачи, помощь подразделению, дисциплинированность и иные заслуги перед ведомством.","r":"ДУ ст. 31"},{"d":"Дисциплинарный устав","t":"Статья 32. Виды поощрений","x":"В пределах компетенции могут применяться следующие меры поощрения: - снятие ранее наложенного дисциплинарного взыскания; - объявление благодарности; - награждение ценным подарком либо денежной премией в порядке, установленном проектом; - досрочное присвоение очередного звания или представление к повышению; - занесение в книгу почёта либо иную форму публичного признания заслуг.","r":"ДУ ст. 32"},{"d":"Дисциплинарный устав","t":"Статья 33. Порядок применения поощрений","x":"Поощрение объявляется уполномоченным должностным лицом и должно быть обосновано конкретными заслугами военнослужащего или сотрудника. Поощрение не освобождает от ответственности за совершённые нарушения.","r":"ДУ ст. 33"},{"d":"Дисциплинарный устав","t":"Статья 34. Применение Устава","x":"Настоящий Устав применяется совместно с общим уставом Вооружённых Сил, уставом караульно-постовой службы и действующим законодательством проекта. Положения Устава подлежат периодическому пересмотру командованием при изменении законодательства, структуры ведомств или игровых механик. Изменения не могут ухудшать положение лица задним числом.","r":"ДУ ст. 34"},{"d":"Дисциплинарный устав","t":"Статья 35. Толкование","x":"Официальное толкование положений настоящего Устава осуществляется уполномоченным руководством проекта в соответствии с законодательством. При наличии пробела применяется наиболее близкая по смыслу норма с соблюдением принципов справедливости, соразмерности и презумпции добросовестности.","r":"ДУ ст. 35"},{"d":"Устав караульно-постовой службы","t":"Статья 1","x":"Настоящий Устав определяет предназначение, порядок организации и несения караульной службы, права и обязанности военнослужащих, несущих караульную службу, а также для регламентирует порядок несения постовой службы военнослужащих ВС РФ, а так же ФСВНГ.","r":"УКПС ст. 1"},{"d":"Устав караульно-постовой службы","t":"Статья 2","x":"Настоящим Уставом руководствуются все военнослужащие органов военного управления, воинских частей, органов военной полиции,федеральной службы войск национальной гвардии и лица гражданского персонала Вооруженных Сил Российской Федерации, замещающие воинские должности.","r":"УКПС ст. 2"},{"d":"Устав караульно-постовой службы","t":"Статья 3","x":"Караульная служба предназначена для надежной охраны и обороны боевых знамен, хранилищ (складов) с вооружением, военной техникой, другим военным имуществом, объектов Вооруженных Сил Российской Федерации и иных военных и государственных объектов, а также для охраны военнослужащих, содержащихся на гауптвахте и в дисциплинарной части.","r":"УКПС ст. 3"},{"d":"Устав караульно-постовой службы","t":"Статья 4","x":"Руководство караульной службой внутренних караулов воинский частей осуществляют командиры этих частей и их прямые начальники.","r":"УКПС ст. 4"},{"d":"Устав караульно-постовой службы","t":"Статья 5","x":"Приказы и распоряжения Министра обороны командующих территориальными воинскими формированиями по организации и несению караульной службы обязательным для выполнения подведомственными воинскими формированиями, их военнослужащими и иными должностными лицами, входящими в состав конкретного субъекта.","r":"УКПС ст. 5"},{"d":"Устав караульно-постовой службы","t":"Статья 6","x":"Командующие воинскими формированиями обязаны периодически проверять качество несения караульной службы на подведомственных субъектах.","r":"УКПС ст. 6"},{"d":"Устав караульно-постовой службы","t":"Статья 7","x":"При расположении войск в полевых условиях мероприятия по поддержанию воинской дисциплины, охране субъектов воинских частей и военных объектов проводятся в соответствии с Уставами воинских формирований Вооруженных Сил Российской Федерации и настоящим Уставом.","r":"УКПС ст. 7"},{"d":"Устав караульно-постовой службы","t":"Статья 8","x":"Непосредственное выполнение задач караульной службы осуществляется подразделениями воинских частей, отделом собственной безопасности а также военной комендатурой в пределах компетенции, определенной настоящим Уставом и Уставами конкретных воинских формирований.","r":"УКПС ст. 8"},{"d":"Устав караульно-постовой службы","t":"Статья 9","x":"Каждый военнослужащий обязан оказывать требуемую помощь лицам, несущим караульную службу.","r":"УКПС ст. 9"},{"d":"Устав караульно-постовой службы","t":"Статья 10","x":"Каждый военнослужащий обязан знать в лицо своего командира или зам командира","r":"УКПС ст. 10"},{"d":"Устав караульно-постовой службы","t":"Статья 11","x":"Военнослужащий, заметив нарушение правил несения службы кем-либо из состава наряда, караула, обязан немедленно сообщить об этом дежурному по части, в орган военной полиции или отдел собственной безопасности и доложить непосредственному командиру (начальнику).","r":"УКПС ст. 11"},{"d":"Устав караульно-постовой службы","t":"Статья 12","x":"Начальником караульной службы является командир части либо назначенное приказом должностное лицо.","r":"УКПС ст. 12"},{"d":"Устав караульно-постовой службы","t":"Статья 13","x":"К постоянным караулам относятся караулы, перечень которых определяется настоящим Уставом и караульная служба на которых осуществляется непрерывно без необходимости оформления сопроводительных документов или письменных и(или) устных распоряжений на организацию и осуществление караулов.","r":"УКПС ст. 13"},{"d":"Устав караульно-постовой службы","t":"Статья 14","x":"Временные караулы создаются приказами командиров воинских частей (формирований) либо приказом (указом) Министра обороны Российской Федерации, Премьер-министра и иными должностными лицами, которым предоставлено такое право в соответствии с действующим законодательством Российской Федерации.","r":"УКПС ст. 14"},{"d":"Устав караульно-постовой службы","t":"Статья 15","x":"Перечень постоянных караулов на территории Московской области: воинская часть ; территориальные военные объекты материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения; военный комиссариат Московской области, пункты отборы; государственные объекты материального снабжения.","r":"УКПС ст. 15"},{"d":"Устав караульно-постовой службы","t":"Статья 16","x":"Порядок несения караульной службы, перечень постов в караулах и порядок посещения указанных в статье 13 территорий, определяется настоящим Уставом.","r":"УКПС ст. 16"},{"d":"Устав караульно-постовой службы","t":"Статья 17","x":"Порядок несения караульной службы и перечень постов в караулах на объектах материального снабжения и объекта стратегического значения защищен Федеральным законом \"О государственной тайне\" и устанавливается исключительно приказами командиров (начальников) воинских формирований в соответствии с подведомственностью.","r":"УКПС ст. 17"},{"d":"Устав караульно-постовой службы","t":"Статья 18","x":"Каждый из перечисленных в статье 13 настоящего Устава объект охраняется Вооруженными Силами Российской Федерации. 18.1 Военные склады материального снабжения, склады с вооружением, стоянки военной техники, объекты стратегического (военного) значения, территории воинских частей являются закрытыми для свободного посещения и нахождения. Порядок прохода и пребывания на указанных территориях определяется Федеральным законом \"О государственной собственности, закрытых и охраняемых территориях\" и Федеральным законом \"О Вооруженных Силах Российской Федерации\" . 18.2 Нахождение на иных территориях, не перечисленных в части 1 статьи 16 настоящего Устава, не ограничивается при соблюдении установленных правил поведения, за исключением обстоятельств, определяемых действующим законодательством. Раздел 3. Постовая служба в караулах","r":"УКПС ст. 18"},{"d":"Устав караульно-постовой службы","t":"Статья 19","x":"Заступить на постовую службу в караулах может любой военнослужащих со звания Рядовой","r":"УКПС ст. 19"},{"d":"Устав караульно-постовой службы","t":"Статья 20","x":"Перечень постов в каждом из постоянных караулов определяется настоящим Уставом, может дополняться и корректироваться в связи с определенными обстоятельствами приказами командиров воинских частей (формирований), Министра обороны Российской Федерации.","r":"УКПС ст. 20"},{"d":"Устав караульно-постовой службы","t":"Статья 21","x":"Перечень постов во временно организуемых караулах определяется соответствующим приказом (указом) командиров (начальников), Министра обороны Российской Федерации, Премьер-министра, иных должностных лиц в пределах компетенции.","r":"УКПС ст. 21"},{"d":"Устав караульно-постовой службы","t":"Статья 22","x":"Перечень постов в карауле на территории воинской части: контрольно-пропускной пункт №1 (главный КПП); контрольно-пропускной пункт №2 (запасной КПП); вышки №1 - №8 по периметру воинской части; главный склад; военный полигон.","r":"УКПС ст. 22"},{"d":"Устав караульно-постовой службы","t":"Статья 22.1","x":"На территории военного полигона “Алабино” устанавливаются три постоянных поста: - контрольно-пропускной пункт №1; - контрольно-пропускной пункт №2; - наблюдательная вышка. Оба КПП являются основными пунктами прохода, въезда и выезда на и с территории полигона. Наблюдательная вышка предназначена для визуального контроля территории, выявления нарушений режима, незаконного проникновения, происшествий и своевременного доклада по средствам связи. Дежурство на постах несут военнослужащие мотострелкового корпуса и роты вневедомственной охраны","r":"УКПС ст. 22.1"},{"d":"Устав караульно-постовой службы","t":"Статья 22.2","x":"На территории военного полигона “Алабино” допускается пешее и автомобильное патрулирование. Патрулирование может осуществляться военнослужащими, самостоятельно заступившими на патрульную службу, либо военнослужащими, действующими по распоряжению командования. Отдельное назначение на патруль не является обязательным условием его несения. Патруль обязан контролировать режим территории, выявлять незаконное проникновение, обеспечивать безопасность вблизи зон проведения учений и тренировок, не препятствовать учебным мероприятиям и докладывать о выявленных нарушениях по рации.","r":"УКПС ст. 22.2"},{"d":"Устав караульно-постовой службы","t":"Статья 23","x":"Перечень постов в карауле на территории военного комиссариата, пунктов отбора: главный вход; призывной кабинет; дежурный пост.","r":"УКПС ст. 23"},{"d":"Устав караульно-постовой службы","t":"Статья 24","x":"Численность военнослужащих одновременно несущих караульно-постовую службу на территории воинской части устанавливается внутренними актами и должностными регламентами","r":"УКПС ст. 24"},{"d":"Устав караульно-постовой службы","t":"Статья 25","x":"Старший наряда назначается приказом. Старшинство по званию применяется только при отсутствии назначенного старшего наряда.","r":"УКПС ст. 25"},{"d":"Устав караульно-постовой службы","t":"Статья 26","x":"При приеме и сдаче поста проверяются оружие, средства связи, состояние охраняемого объекта, наличие происшествий и замечаний. Смена фиксируется докладом в рацию.","r":"УКПС ст. 26"},{"d":"Устав караульно-постовой службы","t":"Статья 26.1. Ухудшение состояния здоровья постового","x":"При ухудшении состояния здоровья постовой незамедлительно докладывает дежурному либо старшему наряда и запрашивает медицинскую помощь. Для прохождения планового медицинского осмотра постовой сдаёт пост сменяющему военнослужащему в порядке статьи 26 настоящего Устава. Самостоятельный уход с поста для планового осмотра до сдачи поста не допускается. Если состояние здоровья исключает безопасное продолжение службы либо требуется экстренная помощь, медицинская помощь оказывается безотлагательно. Дежурный либо старший наряда организует замену и обеспечивает непрерывность охраны объекта. При невозможности постового самостоятельно доложить о своём состоянии доклад осуществляет обнаруживший его военнослужащий либо медицинский работник. Военнослужащий с действующими медицинскими ограничениями не допускается к постовой службе, если её условия несовместимы с указанными ограничениями. Доклад и передача поста осуществляются по служебной связи. Ведение отдельного журнала поста для этого не требуется.","r":"УКПС ст. 26.1"},{"d":"Устав караульно-постовой службы","t":"Статья 27","x":"Бодикамера обязательна для сотрудников ВП, ОСБ, военнослужащих на КПП, патрулей и лиц, проводящих задержание. При неисправности камеры военнослужащий докладывает старшему.","r":"УКПС ст. 27"},{"d":"Устав караульно-постовой службы","t":"Статья 28","x":"При заступлении на пост, каждый военнослужащий обязан предварительно провести проверку табельного оружия и средств радиосвязи на предмет их исправности. При обнаружении неисправности в работе, принять меры по устранению поломки либо заменить на исправные. Постовой или патрульный не вправе использовать полученное для службы оружие в личных целях, передавать его другим лицам либо покидать с ним территорию части без служебной необходимости.","r":"УКПС ст. 28"},{"d":"Устав караульно-постовой службы","t":"Статья 29","x":"При несении постовой службы запрещается: терять концентрацию, отвлекаться на телефон и иные электронные средства, на разговоры; оставлять вооружение без контроля, снимать его с плеча без необходимости привести его в боевую готовность; нарушать действующее законодательство, особенно в области этики; игнорировать запросы о состоянии поста в рацию; своевременно не докладывать о состоянии поста; нарушать требования настоящего Устава в области организации пропуска на территорию и с территории объекта; бездействовать при совершении преступлений и(или) правонарушений на подведомственных территориях; бездействовать при просьбе оказания помощи гражданам и сотрудникам в пределах компетенции. Военнослужащим во время несения постовой службы на любом посту запрещается танцевать и совершать иные действия, не связанные с исполнением служебных обязанностей. Разрешено совершать действия, непосредственно необходимые для выполнения уставных предписаний, применения разрешённого снаряжения или оказания медицинской помощи.","r":"УКПС ст. 29"},{"d":"Устав караульно-постовой службы","t":"Статья 30","x":"Обязанности военнослужащих, несущих постовую службу на КПП №1: постовой проверяет документы водителя, номер автомобиля, цель въезда и наличие записи в журнале транспортных средств. При отказе от предусмотренной проверки въезд не допускается. Постовой также проверяет документы прибывающих лиц, докладывает о нарушениях, пресекает незаконное проникновение в пределах полномочий и своевременно докладывает о состоянии поста. Полковники и выше проходят без оформления увольнительной, но предъявляют служебное удостоверение. При покидании воинской части на личном транспорте или без установленной формы одежды, независимо от занимаемой должности, военнослужащий обязан предъявить удостоверение постовому и не препятствовать осмотру багажника транспортного средства (( постовой вправе через отыгровку типа “/do Есть ли в машине @dynamicID запрещенные или нелегальные средства?”, игнорирование вопроса или заведомо ложный ответ наказывается по 5.9 ОПП )). Постовой вправе проводить досмотр военнослужащих, гражданских лиц, ручной клади и транспортных средств при въезде или выезде с территории воинской части в целях соблюдения пропускного режима, выявления запрещенных предметов и проверки законности ношения оружия, боеприпасов и специальных средств. Военнослужащий, покидающий часть в гражданской форме, обязан по требованию постового подтвердить сдачу оружия, боеприпасов и специальных средств в порядке, установленном внутренним уставом (статья 3.4.2 ВУ). При выявлении оружия, боеприпасов или специальных средств у лица, которое обязано было их сдать, постовой не допускает дальнейший выход с…","r":"УКПС ст. 30"},{"d":"Устав караульно-постовой службы","t":"Статья 31","x":"Военнослужащие со звания генерал-лейтенант включительно освобождаются от проверок при пересечении любого из КПП, постовые обязаны знать их в лицо.","r":"УКПС ст. 31"},{"d":"Устав караульно-постовой службы","t":"Статья 32","x":"КПП №2 является резервно-служебным. Он используется для колонн снабжения, призывных колонн, служебного транспорта, патрулей и правительственных кортежей только при закрытии КПП №1 либо по отдельному приказу командования.","r":"УКПС ст. 32"},{"d":"Устав караульно-постовой службы","t":"Статья 33","x":"Обязанности военнослужащих на КПП №2 аналогичны обязанностям на КПП №1 и выполняются только в период законного использования КПП №2.","r":"УКПС ст. 33"},{"d":"Устав караульно-постовой службы","t":"Статья 34","x":"На территорию воинской части запрещается въезд на личных транспортных средствах, не зарегистрированных в установленном порядке в журнале транспортных средств. Регистрацию автомобиля санкционируют командиры ВП и ОСБ в пределах полномочий.","r":"УКПС ст. 34"},{"d":"Устав караульно-постовой службы","t":"Статья 34.2","x":"Въезд личного транспорта военнослужащих и гражданских лиц допускается исключительно через КПП №1. КПП №2 не используется для въезда личного транспорта.","r":"УКПС ст. 34.2"},{"d":"Устав караульно-постовой службы","t":"Статья 34.3","x":"Личный транспорт допускается при наличии записи в журнале транспортных средств и подтвержденной цели въезда.","r":"УКПС ст. 34.3"},{"d":"Устав караульно-постовой службы","t":"Статья 34.4","x":"После въезда личный транспорт следует по утвержденному маршруту на выделенную парковочную зону. Сквозной проезд по территории части, остановка у штаба, складов, казарм, автопарка, постов и иных режимных объектов запрещены.","r":"УКПС ст. 34.4"},{"d":"Устав караульно-постовой службы","t":"Статья 34.5","x":"Выезд личного транспорта производится через КПП №1. Допуск автомобиля может быть приостановлен или отменен при отсутствии транспортного средства в журнале.","r":"УКПС ст. 34.5"},{"d":"Устав караульно-постовой службы","t":"Статья 35","x":"Разовые пропуска на территорию части уполномочены оформлять командиры военной полиции и руководство вооруженных сил.","r":"УКПС ст. 35"},{"d":"Устав караульно-постовой службы","t":"Статья 36","x":"Военнослужащим несущим постовую службу на контрольно-пропускном пункте №1 и контрольно-пропускном пункте № 2 запрещается : 1. Спать, сидеть и прислоняться к чему-либо. 2. Читать, писать, петь. 3. Есть, пить и курить. 4. Принимать от кого-либо или передавать кому-либо предметы, не связанные с исполнением служебных обязанностей. Запрет не распространяется на установленную передачу служебного имущества, получение разрешённых средств первой помощи и действия, необходимые для оказания медицинской помощи. 5. Справлять естественные надобности на посту. 6. Досылать патрон в патронник без необходимости, как и доставать оружие без необходимости. 7. Использовать средства личной связи. 8. Танцевать или совершать иные действия, не связанные с несением постовой службы.","r":"УКПС ст. 36"},{"d":"Устав караульно-постовой службы","t":"Статья 37","x":"Режимным объектом является территория внутри периметра части, доступ к которой осуществляется через КПП №1 и КПП №2. Территория с внешней стороны КПП режимным объектом не является. За пределами режимного объекта военнослужащие действуют в пределах закона и при необходимости вызывают компетентные органы.","r":"УКПС ст. 37"},{"d":"Уголовный кодекс РО","t":"Статья 1. Уголовное законодательство РО","x":"1. Уголовное законодательство РО состоит из настоящего Кодекса. Новые законы, предусматривающие уголовную ответственность, подлежат включению в настоящий Кодекс. 2. Настоящий кодекс основывается на Конституции РО и общепризнанных принципах и нормах международного права.","r":"УК ст. 1"},{"d":"Уголовный кодекс РО","t":"Статья 2. Задачи Уголовного кодекса РО","x":"1. Задачами настоящего Кодекса являются: охрана прав и свобод человека и гражданина, собственности, общественного порядка и общественной безопасности, окружающей среды, конституционного строя РО от преступных посягательств, обеспечение мира и безопасности человечества, а также предупреждение преступлений. 2. Для осуществления этих задач настоящий Кодекс устанавливает основание и принципы уголовной ответственности, определяет, какие опасные для личности, общества или государства деяния признаются преступлениями, и устанавливает виды наказаний и иные меры уголовно-правового характера за совершение преступлений.","r":"УК ст. 2"},{"d":"Уголовный кодекс РО","t":"Статья 3. Принцип законности","x":"1. Преступность деяния, а также его наказуемость и иные уголовно-правовые последствия определяются только настоящим Кодексом. 2. Применение уголовного закона по аналогии не допускается.","r":"УК ст. 3"},{"d":"Уголовный кодекс РО","t":"Статья 4. Принцип равенства граждан перед законом","x":"Лица, совершившие преступления, равны перед законом и подлежат уголовной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств.","r":"УК ст. 4"},{"d":"Уголовный кодекс РО","t":"Статья 5. Принцип вины","x":"1. Лицо подлежит уголовной ответственности только за те общественно опасные действия (бездействие) и наступившие общественно опасные последствия, в отношении которых установлена его вина. 2. Объективное вменение, то есть уголовная ответственность за невиновное причинение вреда, не допускается.","r":"УК ст. 5"},{"d":"Уголовный кодекс РО","t":"Статья 6. Принцип справедливости","x":"1. Наказание и иные меры уголовно-правового характера, применяемые к лицу, совершившему преступление, должны быть справедливыми, то есть соответствовать характеру и степени общественной опасности преступления, обстоятельствам его совершения и личности виновного. 2. Никто не может нести уголовную ответственность дважды за одно и то же преступление.","r":"УК ст. 6"},{"d":"Уголовный кодекс РО","t":"Статья 7. Принцип гуманизма","x":"1. Уголовное законодательство РО обеспечивает безопасность человека. 2. Наказание и иные меры уголовно-правового характера, применяемые к лицу, совершившему преступление, не могут иметь своей целью причинение физических страданий или унижение человеческого достоинства.","r":"УК ст. 7"},{"d":"Уголовный кодекс РО","t":"Статья 8. Основание уголовной ответственности","x":"Основанием уголовной ответственности является совершение деяния, содержащего все признаки состава преступления, предусмотренного настоящим Кодексом.","r":"УК ст. 8"},{"d":"Уголовный кодекс РО","t":"Статья 9. Действие уголовного закона во времени","x":"1. Преступность и наказуемость деяния определяются уголовным законом, действовавшим во время совершения этого деяния. 2. Временем совершения преступления признается время совершения общественно опасного действия (бездействия) независимо от времени наступления последствий. 3. Уголовный закон, устраняющий преступность деяния, смягчающий наказание или иным образом улучшающий положение лица, совершившего преступление, имеет обратную силу, то есть распространяется на лиц, совершивших соответствующие деяния до вступления такого закона в силу, в том числе на лиц, отбывающих наказание или отбывших наказание, но имеющих судимость. Уголовный закон, устанавливающий преступность деяния, усиливающий наказание или иным образом ухудшающий положение лица, обратной силы не имеет.","r":"УК ст. 9"},{"d":"Уголовный кодекс РО","t":"Статья 10. Понятие преступления","x":"1. Преступлением признается виновно совершенное общественно опасное деяние, запрещенное настоящим Кодексом под угрозой наказания. 2. Не является преступлением деяние, хотя формально и содержащее признаки какого-либо деяния, предусмотренного настоящим Кодексом, но в силу малозначительности не представляющее общественной опасности.","r":"УК ст. 10"},{"d":"Уголовный кодекс РО","t":"Статья 11. Категории преступлений","x":"1. В зависимости от характера и степени общественной опасности деяния, предусмотренные настоящим Кодексом, подразделяются на преступления небольшой тяжести, преступления средней тяжести, тяжкие преступления и особо тяжкие преступления. 2. Преступлениями небольшой тяжести признаются умышленные и неосторожные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 20 месяцев лишения свободы. 3. Преступлениями средней тяжести признаются умышленные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 30 месяцев лишения свободы, и неосторожные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 35 месяцев лишения свободы. 4. Тяжкими преступлениями признаются умышленные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 40 месяцев лишения свободы, и неосторожные деяния, за совершение которых максимальное наказание, предусмотренное настоящим Кодексом, не превышает 45 месяцев лишения свободы. 5. Особо тяжкими преступлениями признаются умышленные деяния, за совершение которых настоящим Кодексом предусмотрено наказание в виде лишения свободы на срок свыше 40 месяцев или более строгое наказание.","r":"УК ст. 11"},{"d":"Уголовный кодекс РО","t":"Статья 12. Совокупность преступлений","x":"1. Совокупностью преступлений признается совершение двух или более преступлений, ни за одно из которых лицо не было осуждено, за исключением случаев, когда совершение двух или более преступлений предусмотрено статьями Особенной части настоящего Кодекса в качестве обстоятельства, влекущего более строгое наказание. При совокупности преступлений лицо несет уголовную ответственность за каждое совершенное преступление по соответствующей статье или части статьи настоящего Кодекса. 2. Совокупностью преступлений признается и одно действие (бездействие), содержащее признаки преступлений, предусмотренных двумя или более статьями настоящего Кодекса. 3. Если преступление предусмотрено общей и специальной нормами, совокупность преступлений отсутствует и уголовная ответственность наступает по специальной норме.","r":"УК ст. 12"},{"d":"Уголовный кодекс РО","t":"Статья 13. Рецидив преступлений","x":"Рецидивом преступлений признается совершение умышленного преступления лицом, имеющим судимость за ранее совершенное умышленное преступление.","r":"УК ст. 13"},{"d":"Уголовный кодекс РО","t":"Статья 14. Формы вины","x":"1. Виновным в преступлении признается лицо, совершившее деяние умышленно или по неосторожности. 2. Деяние, совершенное только по неосторожности, признается преступлением лишь в случае, когда это специально предусмотрено соответствующей статьей Особенной части настоящего Кодекса.","r":"УК ст. 14"},{"d":"Уголовный кодекс РО","t":"Статья 15. Преступление, совершенное умышленно","x":"1. Преступлением, совершенным умышленно, признается деяние, совершенное с прямым или косвенным умыслом. 2. Преступление признается совершенным с прямым умыслом, если лицо осознавало общественную опасность своих действий (бездействия), предвидело возможность или неизбежность наступления общественно опасных последствий и желало их наступления. 3. Преступление признается совершенным с косвенным умыслом, если лицо осознавало общественную опасность своих действий (бездействия), предвидело возможность наступления общественно опасных последствий, не желало, но сознательно допускало эти последствия либо относилось к ним безразлично.","r":"УК ст. 15"},{"d":"Уголовный кодекс РО","t":"Статья 16. Преступление, совершенное по неосторожности","x":"1. Преступлением, совершенным по неосторожности, признается деяние, совершенное по легкомыслию или небрежности. 2. Преступление признается совершенным по легкомыслию, если лицо предвидело возможность наступления общественно опасных последствий своих действий (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение этих последствий. 3. Преступление признается совершенным по небрежности, если лицо не предвидело возможности наступления общественно опасных последствий своих действий (бездействия), хотя при необходимой внимательности и предусмотрительности должно было и могло предвидеть эти последствия.","r":"УК ст. 16"},{"d":"Уголовный кодекс РО","t":"Статья 17. Ответственность за преступление, совершенное с двумя формами вины","x":"Если в результате совершения умышленного преступления причиняются тяжкие последствия, которые по закону влекут более строгое наказание и которые не охватывались умыслом лица, уголовная ответственность за такие последствия наступает только в случае, если лицо предвидело возможность их наступления, но без достаточных к тому оснований самонадеянно рассчитывало на их предотвращение, или в случае, если лицо не предвидело, но должно было и могло предвидеть возможность наступления этих последствий. В целом такое преступление признается совершенным умышленно.","r":"УК ст. 17"},{"d":"Уголовный кодекс РО","t":"Статья 18. Невиновное причинение вреда","x":"1. Деяние признается совершенным невиновно, если лицо, его совершившее, не осознавало и по обстоятельствам дела не могло осознавать общественной опасности своих действий (бездействия) либо не предвидело возможности наступления общественно опасных последствий и по обстоятельствам дела не должно было или не могло их предвидеть. 2. Деяние признается также совершенным невиновно, если лицо, его совершившее, хотя и предвидело возможность наступления общественно опасных последствий своих действий (бездействия), но не могло предотвратить эти последствия в силу несоответствия своих психофизиологических качеств требованиям экстремальных условий или нервно-психическим перегрузкам.","r":"УК ст. 18"},{"d":"Уголовный кодекс РО","t":"Статья 19. Оконченное и неоконченное преступления","x":"1. Преступление признается оконченным, если в совершенном лицом деянии содержатся все признаки состава преступления, предусмотренного настоящим Кодексом. 2. Неоконченным преступлением признаются приготовление к преступлению и покушение на преступление. 3. Уголовная ответственность за неоконченное преступление наступает по статье настоящего Кодекса, предусматривающей ответственность за оконченное преступление, со ссылкой на статью 20 настоящего Кодекса.","r":"УК ст. 19"},{"d":"Уголовный кодекс РО","t":"Статья 20. Приготовление к преступлению и покушение на преступление","x":"1. Приготовлением к преступлению признаются приискание, изготовление или приспособление лицом средств или орудий совершения преступления, приискание соучастников преступления, сговор на совершение преступления либо иное умышленное создание условий для совершения преступления, если при этом преступление не было доведено до конца по независящим от этого лица обстоятельствам. 2. Покушением на преступление признаются умышленные действия (бездействие) лица, непосредственно направленные на совершение преступления, если при этом преступление не было доведено до конца по независящим от этого лица обстоятельствам.","r":"УК ст. 20"},{"d":"Уголовный кодекс РО","t":"Статья 21. Добровольный отказ от преступления","x":"1. Добровольным отказом от преступления признается прекращение лицом приготовления к преступлению либо прекращение действий (бездействия), непосредственно направленных на совершение преступления, если лицо осознавало возможность доведения преступления до конца. 2. Лицо не подлежит уголовной ответственности за преступление, если оно добровольно и окончательно отказалось от доведения этого преступления до конца. 3. Лицо, добровольно отказавшееся от доведения преступления до конца, подлежит уголовной ответственности в том случае, если фактически совершенное им деяние содержит иной состав преступления. 4. Организатор преступления и подстрекатель к преступлению не подлежат уголовной ответственности, если эти лица своевременным сообщением органам власти или иными предпринятыми мерами предотвратили доведение преступления исполнителем до конца. Пособник преступления не подлежит уголовной ответственности, если он предпринял все зависящие от него меры, чтобы предотвратить совершение преступления. 5. Если действия организатора или подстрекателя, предусмотренные частью четвертой настоящей статьи, не привели к предотвращению совершения преступления исполнителем, то предпринятые ими меры могут быть признаны смягчающими обстоятельствами при назначении наказания.","r":"УК ст. 21"},{"d":"Уголовный кодекс РО","t":"Статья 22. Понятие соучастия в преступлении","x":"Соучастием в преступлении признается умышленное совместное участие двух или более лиц в совершении умышленного преступления.","r":"УК ст. 22"},{"d":"Уголовный кодекс РО","t":"Статья 23. Виды соучастников преступления","x":"1. Соучастниками преступления наряду с исполнителем признаются организатор, подстрекатель и пособник. 2. Исполнителем признается лицо, непосредственно совершившее преступление либо непосредственно участвовавшее в его совершении совместно с другими лицами (соисполнителями), а также лицо, совершившее преступление посредством использования других лиц, не подлежащих уголовной ответственности в силу возраста, невменяемости или других обстоятельств, предусмотренных настоящим Кодексом. 3. Организатором признается лицо, организовавшее совершение преступления или руководившее его исполнением, а равно лицо, создавшее организованную группу или преступное сообщество (преступную организацию) либо руководившее ими. 4. Подстрекателем признается лицо, склонившее другое лицо к совершению преступления путем уговора, подкупа, угрозы или другим способом. 5. Пособником признается лицо, содействовавшее совершению преступления советами, указаниями, предоставлением информации, средств или орудий совершения преступления либо устранением препятствий, а также лицо, заранее обещавшее скрыть преступника, средства или орудия совершения преступления, следы преступления либо предметы, добытые преступным путем, а равно лицо, заранее обещавшее приобрести или сбыть такие предметы.","r":"УК ст. 23"},{"d":"Уголовный кодекс РО","t":"Статья 24. Совершение преступления группой лиц, группой лиц по предварительному сговору, организованной группой или преступным сообществом (преступной организацией)","x":"1. Преступление признается совершенным группой лиц, если в его совершении совместно участвовали два или более исполнителя без предварительного сговора. 2. Преступление признается совершенным группой лиц по предварительному сговору, если в нем участвовали лица, заранее договорившиеся о совместном совершении преступления. 3. Преступление признается совершенным организованной группой, если оно совершено устойчивой группой лиц, заранее объединившихся для совершения одного или нескольких преступлений. 4. Преступление признается совершенным преступным сообществом (преступной организацией), если оно совершено структурированной организованной группой или объединением организованных групп, действующих под единым руководством, члены которых объединены в целях совместного совершения одного или нескольких тяжких либо особо тяжких преступлений для получения прямо или косвенно финансовой или иной материальной выгоды. 5. Создание организованной группы в случаях, не предусмотренных статьями Особенной части настоящего Кодекса, влечет уголовную ответственность за приготовление к тем преступлениям, для совершения которых она создана. 6. Совершение преступления группой лиц, группой лиц по предварительному сговору, организованной группой или преступным сообществом (преступной организацией) влечет более строгое наказание на основании и в пределах, предусмотренных настоящим Кодексом.","r":"УК ст. 24"},{"d":"Уголовный кодекс РО","t":"Статья 25. Эксцесс исполнителя преступления","x":"Эксцессом исполнителя признается совершение исполнителем преступления, не охватывающегося умыслом других соучастников. За эксцесс исполнителя другие соучастники преступления уголовной ответственности не подлежат.","r":"УК ст. 25"},{"d":"Уголовный кодекс РО","t":"Статья 26. Необходимая оборона","x":"1. Не является преступлением причинение вреда посягающему лицу в состоянии необходимой обороны, то есть при защите личности и прав обороняющегося или других лиц, охраняемых законом интересов общества или государства от общественно опасного посягательства, если это посягательство было сопряжено с насилием, опасным для жизни обороняющегося или другого лица, либо с непосредственной угрозой применения такого насилия. 2. Защита от посягательства, не сопряженного с насилием, опасным для жизни обороняющегося или другого лица, либо с непосредственной угрозой применения такого насилия, является правомерной, если при этом не было допущено превышения пределов необходимой обороны, то есть умышленных действий, явно не соответствующих характеру и опасности посягательства. 3. Не являются превышением пределов необходимой обороны действия обороняющегося лица, если это лицо вследствие неожиданности посягательства не могло объективно оценить степень и характер опасности нападения. 4. Не являются превышением пределов необходимой обороны действия лица, направленные на защиту себя и своей семьи от насилия или угрозы применения насилия либо на защиту своего имущества против лица, незаконно проникшего в его жилище. 5. Положения настоящей статьи в равной мере распространяются на всех лиц независимо от их профессиональной или иной специальной подготовки и служебного положения, а также независимо от возможности избежать общественно опасного посягательства или обратиться за помощью к другим лицам или органам власти.","r":"УК ст. 26"},{"d":"Уголовный кодекс РО","t":"Статья 27. Причинение вреда при задержании лица, совершившего преступление","x":"1. Не является преступлением причинение вреда лицу, совершившему преступление, при его задержании для доставления органам власти и пресечения возможности совершения им новых преступлений, если иными средствами задержать такое лицо не представлялось возможным и при этом не было допущено превышения необходимых для этого мер. 2. Превышением мер, необходимых для задержания лица, совершившего преступление, признается их явное несоответствие характеру и степени общественной опасности совершенного задерживаемым лицом преступления и обстоятельствам задержания, когда лицу без необходимости причиняется явно чрезмерный, не вызываемый обстановкой вред. Такое превышение влечет за собой уголовную ответственность только в случаях умышленного причинения вреда.","r":"УК ст. 27"},{"d":"Уголовный кодекс РО","t":"Статья 28. Крайняя необходимость","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам в состоянии крайней необходимости, то есть для устранения опасности, непосредственно угрожающей личности и правам данного лица или иных лиц, охраняемым законом интересам общества или государства, если эта опасность не могла быть устранена иными средствами и при этом не было допущено превышения пределов крайней необходимости. 2. Превышением пределов крайней необходимости признается причинение вреда, явно не соответствующего характеру и степени угрожавшей опасности и обстоятельствам, при которых опасность устранялась, когда указанным интересам был причинен вред равный или более значительный, чем предотвращенный. Такое превышение влечет за собой уголовную ответственность только в случаях умышленного причинения вреда.","r":"УК ст. 28"},{"d":"Уголовный кодекс РО","t":"Статья 29. Обоснованный риск","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам при обоснованном риске для достижения общественно полезной цели. 2. Риск признается обоснованным, если указанная цель не могла быть достигнута не связанными с риском действиями (бездействием) и лицо, допустившее риск, предприняло достаточные меры для предотвращения вреда охраняемым уголовным законом интересам. 3. Риск не признается обоснованным, если он заведомо был сопряжен с угрозой для жизни многих людей, с угрозой экологической катастрофы или общественного бедствия.","r":"УК ст. 29"},{"d":"Уголовный кодекс РО","t":"Статья 30. Исполнение приказа или распоряжения","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам лицом, действующим во исполнение обязательных для него приказа или распоряжения. Уголовную ответственность за причинение такого вреда несет лицо, отдавшее незаконные приказ или распоряжение. 2. Лицо, совершившее умышленное преступление во исполнение заведомо незаконных приказа или распоряжения, несет уголовную ответственность на общих основаниях. Неисполнение заведомо незаконных приказа или распоряжения исключает уголовную ответственность.","r":"УК ст. 30"},{"d":"Уголовный кодекс РО","t":"Статья 31. Физическое или психическое принуждение","x":"1. Не является преступлением причинение вреда охраняемым уголовным законом интересам в результате физического принуждения, если вследствие такого принуждения лицо не могло руководить своими действиями (бездействием). 2. Вопрос об уголовной ответственности за причинение вреда охраняемым уголовным законом интересам в результате психического принуждения, а также в результате физического принуждения, вследствие которого лицо сохранило возможность руководить своими действиями, решается с учетом положений настоящего Кодекса.","r":"УК ст. 31"},{"d":"Уголовный кодекс РО","t":"Статья 32. Понятие и цели наказания","x":"1. Наказание есть мера государственного принуждения, назначаемая по решению уполномоченного лица. Наказание применяется к лицу, признанному виновным в совершении преступления, и заключается в предусмотренных настоящим Кодексом лишении или ограничении прав и свобод этого лица. 2. Наказание применяется в целях восстановления социальной справедливости, а также в целях исправления осужденного и предупреждения совершения новых преступлений.","r":"УК ст. 32"},{"d":"Уголовный кодекс РО","t":"Статья 33. Виды наказаний","x":"1. Видами наказаний являются: а) штраф; б) лишение права занимать определенные должности или заниматься определенной деятельностью; в) увольнение с государственной или военной службы, в том числе с лишением всех званий (военного билета), наград и привилегий; г) исправительные работы; д) принудительные работы; е) лишение свободы на определенный срок. 2. Исправительные работы, принудительные работы, лишение свободы на определенный срок могут определяться только в качестве основного вида наказания. 3. Уголовный штраф, лишение права занимать определенные должности или заниматься определенной деятельностью могут определяться как в качестве дополнительного, так и в качестве основного вида наказания. 4. Увольнение с государственной или военной службы, в том числе с лишением всех званий, наград и привилегий может определяться только в качестве дополнительного вида наказания. 5. Суд при назначении наказания за преступление может назначить в качестве дополнительного вида наказания увольнение с государственной или военной службы, в том числе с лишением всех званий, наград и привилегий и лишение права занимать определенные должности или заниматься определенной деятельностью даже если такое наказание не предусмотрено санкцией соответствующей статьи.","r":"УК ст. 33"},{"d":"Уголовный кодекс РО","t":"Статья 34. Лица, уполномоченные на привлечение лица к уголовной ответственности и назначение наказания за совершение преступления","x":"1. Органы внутренних дел (полиция), Федеральной Службы Безопасности РО, военной полиции Вооруженных Сил РО, органы прокуратуры и Следственного комитета РО правомочны признавать лицо виновным в совершении преступления и назначить ему за совершенное преступление наказание в виде штрафа или лишения свободы на определенный срок. 2. Суд правомочен признать лицо виновным в совершении преступления и назначить ему за совершенное преступление любого наказания, предусмотренного ч. 1 ст. 33 настоящего Кодекса, с учетом правил назначения наказания, предусмотренных законом. 3. Дополнительные виды наказания могут быть назначены только судом.","r":"УК ст. 34"},{"d":"Уголовный кодекс РО","t":"Статья 35. Штраф","x":"1. Штраф есть денежное взыскание, назначаемое в пределах, предусмотренных настоящим Кодексом. 2. Штраф устанавливается в размере санкции соответствующей статьи. Суд при назначении штрафа в качестве основного вида наказания может выходить за рамки санкции соответствующей статьи и назначить штраф в размере не более 300.000 рублей.","r":"УК ст. 35"},{"d":"Уголовный кодекс РО","t":"Статья 36. Лишение права занимать определенные должности или заниматься определенной деятельностью","x":"1. Лишение права занимать определенные должности или заниматься определенной деятельностью состоит в запрещении занимать должности на государственной службе, в органах местного самоуправления либо заниматься определенной профессиональной или иной деятельностью. 2. В случае если санкцией соответствующей статьи не предусмотрено иное, лишение права занимать определенные должности или заниматься определенной деятельностью устанавливается на срок от 1 до 7 лет.","r":"УК ст. 36"},{"d":"Уголовный кодекс РО","t":"Статья 37. Исправительные работы","x":"1. Исправительные работы назначаются осужденному, имеющему основное место работы, а равно не имеющему его. Осужденный, имеющий основное место работы, отбывает исправительные работы по основному месту работы. Осужденный, не имеющий основного места работы, отбывает исправительные работы в местах, определяемых судом. 2. Из заработной платы осужденного к исправительным работам производятся удержания в доход государства в размере, установленном приговором суда, в пределах от пяти до двадцати процентов. 3. Если суд придет к выводу о том, что исправление подсудимого возможно без назначения наказания в виде реального лишения свободы за совершение преступления небольшой или средней тяжести, если такое наказание предусмотрено санкцией соответствующей статьи, суд может назначить вместо реального лишения свободы в качестве основного вида наказания назначить подсудимому наказание в виде исправительных работ на срок до 20 месяцев. 4. В случае злостного уклонения осужденного от отбывания исправительных работ суд может заменить неотбытое наказание принудительными работами или лишением свободы.","r":"УК ст. 37"},{"d":"Уголовный кодекс РО","t":"Статья 38. Принудительные работы","x":"1. Принудительные работы заключаются в привлечении осужденного к труду в местах, определяемых судом. 2. Места, порядок и иные условия отбывания принудительных работ определяется судом. 3. Если суд придет к выводу о том, что исправление подсудимого возможно без назначения наказания в виде реального лишения свободы за совершение преступления небольшой или средней тяжести или тяжкого преступления, если такое наказание предусмотрено санкцией соответствующей статьи, суд может назначить вместо реального лишения свободы в качестве основного вида наказания назначить подсудимому наказание в виде принудительных работ на срок до 30 месяцев.","r":"УК ст. 38"},{"d":"Уголовный кодекс РО","t":"Статья 39. Лишение свободы на определенный срок","x":"1. Лишение свободы заключается в изоляции признанного в совершении преступления лица от общества путем направления его в исправительное учреждение. Лишение свободы на определенный срок устанавливается на срок от 5 до 50 месяцев. 2. При частичном или полном сложении сроков лишения свободы при назначении наказаний по совокупности преступлений максимальный срок лишения свободы не может быть более 100 месяцев.","r":"УК ст. 39"},{"d":"Уголовный кодекс РО","t":"Статья 40. Общие начала назначения наказания","x":"1. Лицу, признанному виновным в совершении преступления, назначается справедливое наказание в пределах, предусмотренных соответствующей статьей Особенной части настоящего Кодекса, и с учетом положений Общей части настоящего Кодекса. 2. При назначении наказания учитываются характер и степень общественной опасности преступления и личность виновного, в том числе обстоятельства, смягчающие и отягчающие наказание.","r":"УК ст. 40"},{"d":"Уголовный кодекс РО","t":"Статья 41. Правила назначения наказания по совокупности преступлений","x":"1. При совокупности преступлений наказание назначается отдельно за каждое совершенное преступление. 2. В случае назначения наказания за совершение преступлений по совокупности, окончательное наказание назначается путем поглощения менее строгого наказания более строгим. 3. В случае назначения наказания за совершение преступлений по совокупности судом, окончательное наказание может назначаться как по правилу поглощения менее строгого наказания более строгим, так и путем полного или частичного сложения назначенных наказаний. 4. В случае назначения по совокупности преступлений наказания за совершение преступления, предусмотренного ст. 104 настоящего Кодекса, окончательное наказание может назначаться как по правилу, предусмотренному ч. 2 настоящей статьи, так и путем однократного полного или частичного сложения самого строгого назначенного наказания с наказанием за совершение преступления, предусмотренного ст. 104 настоящего Кодекса.","r":"УК ст. 41"},{"d":"Уголовный кодекс РО","t":"Статья 42. Обстоятельства, смягчающие наказание","x":"Смягчающими обстоятельствами признаются: а) совершение преступления в результате физического или психического принуждения либо в силу материальной, служебной или иной зависимости; б) совершение преступления при нарушении условий правомерности необходимой обороны, задержания лица, совершившего преступление, крайней необходимости, обоснованного риска, исполнения приказа или распоряжения; в) противоправность или аморальность поведения потерпевшего, явившегося поводом для преступления; г) явка с повинной, активное способствование раскрытию и расследованию преступления, изобличению и уголовному преследованию других соучастников преступления; д) оказание медицинской и иной помощи потерпевшему после совершения преступления, добровольное возмещение имущественного ущерба и морального вреда, причиненных в результате преступления, иные действия, направленные на заглаживание вреда, причиненного потерпевшему; е) иные обстоятельства.","r":"УК ст. 42"},{"d":"Уголовный кодекс РО","t":"Статья 43. Обстоятельства, отягчающие наказание","x":"1. Отягчающими обстоятельствами признаются: а) совершение преступления в составе группы лиц, группы лиц по предварительному сговору, организованной группы или преступного сообщества (преступной организации); б) совершение преступления по мотивам политической, идеологической, расовой, национальной или религиозной ненависти, или вражды либо по мотивам ненависти или вражды в отношении какой-либо социальной группы; в) совершение преступления из мести за правомерные действия других лиц, а также с целью скрыть другое преступление или облегчить его совершение; г) совершение преступления в отношении лица или его близких в связи с осуществлением данным лицом служебной деятельности или выполнением общественного долга; д) совершение преступления с особой жестокостью, садизмом, издевательством, а также мучениями для потерпевшего; е) совершение преступления с использованием доверия, оказанного виновному в силу его служебного положения или договора; ё) совершение преступления с использованием форменной одежды или документов представителя власти; ж) совершение преступления в состоянии алкогольного или наркотического опьянения; з) совершение преступления с использованием психического давления на потерпевшего; и) рецидив преступлений; й) совершение преступления в отношении потерпевшего, находящегося в отношении виновного в заведомо беспомощном положении; к) наступление тяжких последствий в результате совершения преступления. 2. Не может признаваться отягчающим наказание такое обстоятельство, которое хотя и предусмотрено частью 1 настоящей статьи, однако является одним из квалифицирующих…","r":"УК ст. 43"},{"d":"Уголовный кодекс РО","t":"Статья 44. Назначение более мягкого наказания, чем предусмотрено за данное преступление","x":"При наличии исключительных обстоятельств, связанных с целями и мотивами преступления, ролью виновного, его поведением во время или после совершения преступления, и других обстоятельств, существенно уменьшающих степень общественной опасности преступления, а равно при активном содействии участника группового преступления раскрытию этого преступления, в том числе в случае заключения подозреваемым или обвиняемым досудебного соглашения о сотрудничестве, наказание может быть назначено ниже низшего предела, предусмотренного статьей Особенной части настоящего Кодекса, суд может назначить более мягкий вид наказания, чем предусмотрен санкцией соответствующей статьи.","r":"УК ст. 44"},{"d":"Уголовный кодекс РО","t":"Статья 45. Назначение наказания за неоконченное преступление","x":"1. При назначении наказания за неоконченное преступление учитываются обстоятельства, в силу которых преступление не было доведено до конца. 2. Срок или размер наказания за приготовление к преступлению не может превышать половины максимального срока или размера наиболее строгого вида наказания, предусмотренного соответствующей статьей Особенной части настоящего Кодекса за оконченное преступление. 3. Срок или размер наказания за покушение на преступление не может превышать трех четвертей максимального срока или размера наиболее строгого вида наказания, предусмотренного соответствующей статьей Особенной части настоящего Кодекса за оконченное преступление.","r":"УК ст. 45"},{"d":"Уголовный кодекс РО","t":"Статья 46. Освобождение от уголовной ответственности в связи с назначением судебного штрафа или исправительных работ","x":"1. Лицо, впервые совершившее преступление небольшой или средней тяжести, может быть освобождено судом от уголовной ответственности, с назначением судебного штрафа. 2. Судебный штраф есть денежное взыскание, назначаемое судом при освобождении лица от уголовной ответственности в случаях, предусмотренных настоящей статьей. 3. В случае неуплаты судебного штрафа в установленный судом срок, судебный штраф отменяется и лицо привлекается к уголовной ответственности по соответствующей статье Особенной части настоящего Кодекса.","r":"УК ст. 46"},{"d":"Уголовный кодекс РО","t":"Статья 47. Освобождение от уголовной ответственности в связи с истечением сроков давности уголовного преследования","x":"1. Лицо освобождается от уголовной ответственности, если со дня совершения преступления истекли следующие сроки: а) пятнадцать лет после совершения преступления небольшой тяжести; б) двадцать лет после совершения преступления средней тяжести; в) двадцать пять лет после совершения тяжкого преступления; г) тридцать пять лет после совершения особо тяжкого преступления.","r":"УК ст. 47"},{"d":"Уголовный кодекс РО","t":"Статья 48. Амнистия","x":"1. Амнистия объявляется Федеральным Собранием РО в отношении индивидуально не определенного круга лиц. 2. Актом об амнистии лица, совершившие преступления, могут быть освобождены от уголовной ответственности. Лица, осужденные за совершение преступлений, могут быть освобождены от наказания, либо назначенное им наказание может быть сокращено или заменено более мягким видом наказания, либо такие лица могут быть освобождены от дополнительного вида наказания. С лиц, отбывших наказание, актом об амнистии может быть снята судимость.","r":"УК ст. 48"},{"d":"Уголовный кодекс РО","t":"Статья 49. Помилование","x":"1. Помилование осуществляется Премьер Министром РО в отношении индивидуально определенного лица. 2. Актом помилования лицо, осужденное за преступление, может быть освобождено от дальнейшего отбывания наказания либо назначенное ему наказание может быть сокращено или заменено более мягким видом наказания. С лица, отбывшего наказание, актом помилования может быть снята судимость.","r":"УК ст. 49"},{"d":"Уголовный кодекс РО","t":"Статья 50. Судимость","x":"1. Лицо, привлеченное к уголовной ответственности за совершение преступления, считается судимым со дня вступления в законную силу соответствующего решения должностного лица до момента погашения или снятия судимости. Судимость в соответствии с настоящим Кодексом учитывается при рецидиве преступлений, назначении наказания и влечет за собой иные правовые последствия в случаях и в порядке, которые установлены законом. 2. Погашение или снятие судимости аннулирует все правовые последствия, предусмотренные настоящим Кодексом, связанные с судимостью. 3. Судимость возникает лишь при назначении за совершение тяжкого или особо-тяжкого преступления наказания в виде лишения свободы на срок 40 месяцев и более. 4. Процедура погашения судимости устанавливается законом и актами Председателя Верховного суда РО. 5. Судимость может быть погашена досрочно путем внесения компенсационного платежа в казну правительства в размере 130.000 рублей через сотрудников Министерства Юстиции, Прокуратуры, Судей всех инстанций, иных лиц установленных законодательством.","r":"УК ст. 50"},{"d":"Уголовный кодекс РО","t":"Статья 50.1. Залог","x":"1. Лицо, которому за совершение небольшого или средней тяжести преступления назначено наказание в виде лишения свободы на определенный срок может быть освобождено от отбывания наказания в связи с внесением залога. 2. Залог вносится либо лицом, привлеченным к уголовной ответственности лично, либо его представителем или законным представителем в учреждение органа государственной власти, где осужденный отбывает наказание. 3. Залог за освобождение от наказания за совершение преступления небольшой тяжести составляет 50.000 рублей, а за совершение преступления средней тяжести - 75.000 рублей. 4. В случае назначения наказания в виде лишения свободы лицу по совокупности преступлений, сумма залога рассчитывается из самого тяжкого совершенного преступления. 5. Лицо не может быть освобождено от наказания в связи с внесением залога за совершение тяжких и особо-тяжких преступлений. ОСОБЕННАЯ ЧАСТЬ","r":"УК ст. 50.1"},{"d":"Уголовный кодекс РО","t":"Статья 51. Убийство","x":"[Р/Ф] [★★★★★] Убийство, то есть умышленное причинение смерти другому человеку, — наказывается лишением свободы на срок 50 месяцев. [★★★★★] Убийство: а) двух или более лиц; б) лица или его близких в связи с осуществлением данным лицом служебной деятельности или выполнением общественного долга; в) лица, заведомо для виновного находящегося в беспомощном состоянии, а равно сопряженное с похищением человека; г) совершенное с особой жестокостью; д) совершенное общественно опасным способом; е) по мотиву кровной мести; ж) совершенное группой лиц, группой лиц по предварительному сговору или организованной группой; з) из хулиганских побуждений, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 51"},{"d":"Уголовный кодекс РО","t":"Статья 52. Убийство, совершенное при превышении пределов необходимой обороны либо при превышении мер, необходимых для задержания лица, совершившего преступление","x":"[Р/Ф] [★★★] Убийство, совершенное при превышении пределов необходимой обороны либо при превышении мер, необходимых для задержания лица, совершившего преступление, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 52"},{"d":"Уголовный кодекс РО","t":"Статья 53. Причинение смерти по неосторожности","x":"[Р/Ф] [★★★] Причинение смерти по неосторожности, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 53"},{"d":"Уголовный кодекс РО","t":"Статья 54. Умышленное причинение тяжкого вреда здоровью","x":"[Р/Ф] [★★★★★] Умышленное причинение тяжкого вреда здоровью, опасного для жизни человека, или повлекшего за собой потерю зрения, речи, слуха либо какого-либо органа или утрату органом его функций, прерывание беременности, психическое расстройство, заболевание наркоманией либо токсикоманией, или выразившегося в неизгладимом обезображивании лица, или вызвавшего значительную стойкую утрату общей трудоспособности не менее чем на одну треть или заведомо для виновного полную утрату профессиональной трудоспособности, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 54"},{"d":"Уголовный кодекс РО","t":"Статья 55. Причинение тяжкого или средней тяжести вреда здоровью при превышении пределов необходимой обороны либо при превышении мер, необходимых для задержания лица, совершившего преступление","x":"[Р/Ф] [★★★] Умышленное причинение тяжкого вреда здоровью, совершенное при превышении пределов необходимой обороны, — наказывается штрафом в размере от 35.000 до 60.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★] Умышленное причинение тяжкого или средней тяжести вреда здоровью, совершенное при превышении мер, необходимых для задержания лица, совершившего преступление, — наказывается штрафом в размере 50.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 55"},{"d":"Уголовный кодекс РО","t":"Статья 56. Истязание","x":"[Р/Ф] [★★] Причинение физических или психических страданий путем систематического нанесения побоев либо иными насильственными действиями, если это не повлекло последствий, указанных в статьях 53 и 54 настоящего Кодекса, — наказывается лишением свободы на срок 20 месяцев. [Р/Ф] [★★★] То же деяние, совершенное с особой жестокостью, издевательством или мучениями для потерпевшего, а равно совершенное группой лиц, группой лиц по предварительному сговору или организованной группой, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 56"},{"d":"Уголовный кодекс РО","t":"Статья 57. Угроза убийством или причинением тяжкого вреда здоровью","x":"[Р] [★★★] Угроза убийством или причинением тяжкого вреда здоровью, если имелись основания опасаться осуществления этой угрозы, — наказывается штрафом в размере от 25.000 до 100.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 57"},{"d":"Уголовный кодекс РО","t":"Статья 58. Похищение человека","x":"[Ф] [★★★★★] Похищение человека, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 58"},{"d":"Уголовный кодекс РО","t":"Статья 59. Незаконное лишение свободы","x":"[Р/Ф] [★★★★] Незаконное лишение человека свободы, не связанное с его похищением, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 59"},{"d":"Уголовный кодекс РО","t":"Статья 60. Клевета","x":"[Р] Клевета, то есть распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, — наказывается штрафом в размере от 5.000 до 30.000 рублей. [Р] [★★] Клевета, совершенная с использованием своего служебного положения, а равно соединенная с обвинением лица в совершении преступления против половой неприкосновенности и половой свободы личности либо в совершении тяжкого или особо-тяжкого преступления, — наказывается штрафом в размере от 20.000 до 100.000 рублей либо лишением свободы на срок 20 месяцев.","r":"УК ст. 60"},{"d":"Уголовный кодекс РО","t":"Статья 61. Изнасилование","x":"[Р/Ф] [★★★★] Изнасилование, то есть половое сношение с применением насилия или с угрозой его применения к потерпевшей или к другим лицам либо с использованием беспомощного состояния потерпевшей, — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Изнасилование: а) совершенное группой лиц, группой лиц по предварительному сговору или организованной группой; б) соединенное с угрозой убийством или причинением тяжкого вреда здоровью, а также совершенное с особой жестокостью по отношению к потерпевшей или к другим лицам; в) повлекшее по неосторожности смерть потерпевшего, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 61"},{"d":"Уголовный кодекс РО","t":"Статья 62. Понуждение к действиям сексуального характера","x":"[Р] [★★★] Понуждение лица к половому сношению, мужеложству, лесбиянству или совершению иных действий сексуального характера путем шантажа, угрозы уничтожением, повреждением или изъятием имущества либо с использованием материальной или иной зависимости потерпевшего (потерпевшей), — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 62"},{"d":"Уголовный кодекс РО","t":"Статья 63. Нарушение равенства прав и свобод человека и гражданина","x":"[Р] [★★] Дискриминация, то есть нарушение прав, свобод и законных интересов человека и гражданина в зависимости от его пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям или каким-либо социальным группам, совершенное лицом с использованием своего служебного положения, — наказывается штрафом в размере от 30.000 до 90.000 рублей, либо лишением свободы на срок 20 месяцев.","r":"УК ст. 63"},{"d":"Уголовный кодекс РО","t":"Статья 64. Нарушение неприкосновенности жилища","x":"[Р/Ф] [★★★] Незаконное проникновение в жилище, совершенное против воли проживающего в нем лица, — наказывается штрафом в размере до 50.000 рублей, либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное с применением насилия или с угрозой его применения, а равно совершенные лицом с использованием своего служебного положения, — наказывается штрафом в размере до 75.000 рублей, либо лишением свободы на срок 40 месяцев.","r":"УК ст. 64"},{"d":"Уголовный кодекс РО","t":"Статья 65. Кража","x":"[Р/Ф] [★★★] Кража, то есть тайное хищение чужого имущества, — наказывается штрафом в размере до 50.000 рублей, либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Кража, совершенная: а) группой лиц по предварительному сговору или организованной группой; б) с незаконным проникновением в жилище, помещение либо иное хранилище, — наказывается штрафом в размере до 90.000 рублей, либо лишением свободы на срок 40 месяцев. Примечания. Под хищением в статьях настоящего Кодекса понимаются совершенные с корыстной целью противоправные безвозмездное изъятие и (или) обращение чужого имущества в пользу виновного или других лиц, причинившие ущерб собственнику или иному владельцу этого имущества. Под помещением в статьях настоящей главы понимаются строения и сооружения независимо от форм собственности, предназначенные для временного нахождения людей или размещения материальных ценностей в производственных или иных служебных целях.","r":"УК ст. 65"},{"d":"Уголовный кодекс РО","t":"Статья 66. Грабеж и разбой","x":"[Р/Ф] [★★★] Грабеж, то есть открытое хищение чужого имущества, — наказывается лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Грабеж, совершенный: а) группой лиц по предварительному сговору; б) с незаконным проникновением в жилище, помещение либо иное хранилище; в) с применением насилия, не опасного для жизни или здоровья, либо с угрозой применения такого насилия, — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] Разбой, то есть нападение в целях хищения чужого имущества, совершенное с применением насилия, опасного для жизни или здоровья, либо с угрозой применения такого насилия, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 66"},{"d":"Уголовный кодекс РО","t":"Статья 67. Неправомерное завладение транспортным средством, угон","x":"[Р/Ф] [★★★] Неправомерное завладение автомобилем или иным транспортным средством вне зависимости от цели такого завладения, — наказывается лишением свободы на срок 30 месяцев. Пояснение: «Неправомерное завладение» означает, что виновный не только получил контроль над транспортом, но и сдвинул его — например, угнал машину с парковки или увел лодку от причала. Цель завладения (кража, временное использование или иная) не влияет на квалификацию. Если человек занял транспортное средство — например, проник в чужую машину, завёл её или использовал как укрытие, но не сдвинул с места, — не считается «завладением». Такие действия квалифицируются как мелкое хулиганство, поскольку не приводят к утрате владельцем фактического доступа к транспорту в полном объёме. Исключение для транспорта государственных служащих. Если транспортное средство принадлежит государственному служащему и используется в служебных целях, то занятие его без перемещения имеет особый статус. В этом случае гражданин обязан покинуть такое транспортное средство по первому требованию госслужащего. Невыполнение требования пресекается в соответствии с законодательством, но само занятие без перемещения остается вне рамок статьи 67. Транспортировка транспортного средства, числящегося в угоне, на ином воздушном/водном/железнодорожным и др. видах транспорта также является неправомерным завладением, в том числе если ТС было сдвинуто посредством косвенного вмешательства обвиняемого лица, либо нахождения в нём без сообщения в компетентные органы.","r":"УК ст. 67"},{"d":"Уголовный кодекс РО","t":"Статья 68. Умышленное уничтожение или повреждение имущества","x":"[Р] [★★★] Умышленные уничтожение или повреждение чужого имущества, если эти деяния повлекли причинение значительного ущерба, — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 68"},{"d":"Уголовный кодекс РО","t":"Статья 69. Незаконное предпринимательство","x":"[Ф] [★★★★] Осуществление предпринимательской деятельности без регистрации или без лицензии, если это деяние причинило крупный ущерб гражданам, организациям или государству, — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 69"},{"d":"Уголовный кодекс РО","t":"Статья 70. Террористический акт","x":"[Ф] [★★★★★] Совершение взрыва, поджога или иных действий, устрашающих население и создающих опасность гибели человека, причинения значительного имущественного ущерба либо наступления иных тяжких последствий, в целях дестабилизации деятельности органов власти или международных организаций либо воздействия на принятие ими решений, а также угроза совершения указанных действий в целях воздействия на принятие решений органами власти или международными организациями, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 70"},{"d":"Уголовный кодекс РО","t":"Статья 71. Публичные призывы к осуществлению террористической деятельности, публичное оправдание терроризма или пропаганда терроризма","x":"[Р/Ф] [★★★] Публичные призывы к осуществлению террористической деятельности, публичное оправдание терроризма или пропаганда терроризма, — наказывается штрафом в размере до 70.000 рублей, либо лишением свободы на срок 30 месяцев.","r":"УК ст. 71"},{"d":"Уголовный кодекс РО","t":"Статья 72. Бандитизм","x":"[Ф] [★★★★★] Создание устойчивой вооруженной группы (банды) в целях нападения на граждан или организации, а равно руководство такой группой (бандой), — наказываются лишением свободы на срок 50 месяцев. [Ф] [★★★★] Участие в устойчивой вооруженной группе (банде) или в совершаемых ею нападениях, — наказываются лишением свободы на срок 40 месяцев.","r":"УК ст. 72"},{"d":"Уголовный кодекс РО","t":"Статья 73. Хулиганство","x":"[Р/Ф] [★★★★] Хулиганство, то есть грубое нарушение общественного порядка, выражающее явное неуважение к обществу, совершенное: а) с применением насилия к гражданам либо угрозой его применения; б) по мотивам политической, идеологической, расовой, национальной или религиозной ненависти или вражды либо по мотивам ненависти или вражды в отношении какой-либо социальной группы; в) на железнодорожном, морском, внутреннем водном или воздушном транспорте, а также на любом ином транспорте общего пользования; г) с применением оружия или предметов, используемых в качестве оружия; д) группой лиц, группой лиц по предварительному сговору или организованной группой; е) связанное с сопротивлением представителю власти либо иному лицу, исполняющему обязанности по охране общественного порядка или пресекающему нарушение общественного порядка; ё) с применением взрывчатых веществ или взрывных устройств, — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 73"},{"d":"Уголовный кодекс РО","t":"Статья 73.1. Незаконное проникновение на режимный объект","x":"[Р/Ф] [★★★★] Незаконное проникновение на режимный объект равно как и нахождение на таковом объекте, — наказывается штрафом в размере от 80.000 до 150.000 рублей, либо лишением свободы на срок 40 месяцев.","r":"УК ст. 73.1"},{"d":"Уголовный кодекс РО","t":"Статья 74. Незаконные приобретение, передача, хранение, перевозка, пересылка, ношение, сбыт или изготовление огнестрельного оружия, его основных частей и боеприпасов к нему, а также специальных средств","x":"[Р/Ф] [★★★★] Незаконные приобретение, передача, хранение, сбыт, перевозка, пересылка, ношение огнестрельного оружия, его основных частей и боеприпасов к нему, а также специальных средств, — наказывается штрафом в размере 50.000 рублей, либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Незаконные изготовление, переделка или ремонт огнестрельного оружия, его основных частей, а равно незаконное изготовление боеприпасов к огнестрельному оружию — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 74"},{"d":"Уголовный кодекс РО","t":"Статья 75. Незаконные приобретение, хранение, перевозка, изготовление, переработка наркотических средств, психотропных веществ или их аналогов, а также незаконные приобретение, хранение, перевозка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества","x":"[Р/Ф] [★★★] Незаконные приобретение, хранение, перевозка, изготовление, переработка без цели сбыта наркотических средств, психотропных веществ или их аналогов в значительном размере, а также незаконные приобретение, хранение, перевозка без цели сбыта растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества, в незначительном размере (до 5 грамм) — наказывается штрафом в размере до 50.000 рублей, либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Те же деяния, совершенные в крупном размере (до 20 грамм), — наказываются лишением свободы на срок 40 месяцев. [Ф] [★★★★★] Те же деяния, совершенные в особо крупном размере (свыше 20 грамм), — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 75"},{"d":"Уголовный кодекс РО","t":"Статья 76. Незаконные производство, сбыт или пересылка наркотических средств, психотропных веществ или их аналогов, а также незаконные сбыт или пересылка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества","x":"[Ф] [★★★★★] Незаконные производство, сбыт или пересылка наркотических средств, психотропных веществ или их аналогов, а также незаконные сбыт или пересылка растений, содержащих наркотические средства или психотропные вещества, либо их частей, содержащих наркотические средства или психотропные вещества, — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 76"},{"d":"Уголовный кодекс РО","t":"Статья 77. Жестокое обращение с животными","x":"[Р] [★★★] Жестокое обращение с животным в целях причинения ему боли и (или) страданий, а равно из хулиганских побуждений или из корыстных побуждений, повлекшее его гибель или увечье, — наказывается штрафом в размере от 50.000 до 75.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 77"},{"d":"Уголовный кодекс РО","t":"Статья 78. Нарушение правил дорожного движения и эксплуатации транспортных средств","x":"[Р] [★★★] Нарушение лицом, управляющим автомобилем, либо другим механическим транспортным средством, правил дорожного движения или эксплуатации транспортных средств, повлекшее по неосторожности причинение тяжкого вреда здоровью человека, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] То же деяние, повлекшее по неосторожности смерть человека, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 78"},{"d":"Уголовный кодекс РО","t":"Статья 79. Государственная измена","x":"[Ф] [★★★★★] Государственная измена, то есть совершенные гражданином РО шпионаж, выдача иностранному государству, международной либо иностранной организации или их представителям сведений, составляющих государственную тайну, доверенную лицу или ставшую известной ему по службе, работе, учебе или в иных случаях, предусмотренных законодательством РО, переход на сторону противника либо оказание финансовой, материально-технической, консультационной или иной помощи иностранному государству, международной либо иностранной организации или их представителям в деятельности, направленной против безопасности РО, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 79"},{"d":"Уголовный кодекс РО","t":"Статья 80. Разглашение государственной тайны","x":"[Ф] [★★★★] Разглашение сведений, составляющих государственную тайну, лицом, которому она была доверена или стала известна по службе, работе, учебе или в иных случаях, предусмотренных законодательством РО, если эти сведения стали достоянием других лиц, при отсутствии признаков преступления, предусмотренного статьей 79 настоящего Кодекса, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 80"},{"d":"Уголовный кодекс РО","t":"Статья 81. Утрата документов, содержащих государственную тайну","x":"[Ф] [★★★] Нарушение лицом, имеющим допуск к государственной тайне, установленных правил обращения с содержащими государственную тайну документами, а равно с предметами, сведения о которых составляют государственную тайну, если это повлекло по неосторожности их утрату или наступление тяжких последствий, — наказывается штрафом в размере от 30.000 до 70.000 рублей либо лишением свободы на срок 30 месяцев.","r":"УК ст. 81"},{"d":"Уголовный кодекс РО","t":"Статья 82. Злоупотребление должностными полномочиями","x":"[Р/Ф] [★★★★] Использование должностным лицом своих служебных полномочий вопреки интересам службы, если это деяние совершено из корыстной или иной личной заинтересованности и повлекло существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом в размере от 50.000 до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное лицом, занимающим государственную должность РО или главой Федерального органа исполнительной власти или его заместителем, — наказывается штрафом в размере от 70.000 до 150.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Деяния, предусмотренные частями первой или второй настоящей статьи, повлекшие тяжкие последствия, — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 82"},{"d":"Уголовный кодекс РО","t":"Статья 83. Нецелевое расходование бюджетных средств","x":"[Ф] [★★★] Расходование бюджетных средств должностным лицом получателя бюджетных средств на цели, не соответствующие условиям их получения, определенным утвержденными бюджетом, бюджетной росписью, уведомлением о бюджетных ассигнованиях, сметой доходов и расходов либо иным документом, являющимся основанием для получения бюджетных средств, совершенное в крупном размере — наказывается штрафом в размере от 40.000 до 70.000 рублей, либо лишением свободы на срок 30 месяцев. [Ф] [★★★★] То же деяние, совершенное: а) группой лиц по предварительному сговору; б) в особо крупном размере, — наказывается лишением свободы на срок 40 месяцев. Примечание. Крупным размером в настоящей статье признается сумма бюджетных средств, превышающая пятьдесят тысяч рублей, а особо крупным размером — сто пятьдесят тысяч рублей.","r":"УК ст. 83"},{"d":"Уголовный кодекс РО","t":"Статья 84. Превышение должностных полномочий","x":"[Р/Ф] [★★★★] Совершение должностным лицом действий, явно выходящих за пределы его полномочий и повлекших существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом в размере от 65.000 до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное лицом, занимающим государственную должность РО или главой Федерального органа исполнительной власти или его заместителем, — наказывается штрафом в размере от 40.000 до 80.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Деяния, предусмотренные частями первой или второй настоящей статьи, если они совершены: а) с применением насилия или с угрозой его применения; б) с применением оружия или специальных средств; в) с причинением тяжких последствий; г) группой лиц, группой лиц по предварительному сговору или организованной группой; д) из корыстной или иной личной заинтересованности, — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 84"},{"d":"Уголовный кодекс РО","t":"Статья 85. Неисполнение сотрудником органа внутренних дел приказа","x":"[Р/Ф] [★★] Умышленное неисполнение сотрудником органа внутренних дел приказа начальника, отданного в установленном порядке и не противоречащего закону, причинившее существенный вред правам и законным интересам граждан или организаций либо охраняемым законом интересам общества или государства, — наказывается штрафом в размере от 20.000 до 40.000 рублей, либо лишением свободы на срок 20 месяцев. [Р/Ф] [★★★] То же деяние, совершенное группой лиц, группой лиц по предварительному сговору или организованной группой, а равно повлекшее тяжкие последствия, — наказывается лишением свободы на срок 30 месяцев.","r":"УК ст. 85"},{"d":"Уголовный кодекс РО","t":"Статья 86. Получение взятки","x":"[Р/Ф] [★★★★] Получение должностным лицом, иностранным должностным лицом либо должностным лицом публичной международной организации лично или через посредника взятки в виде денег, ценных бумаг, иного имущества либо в виде незаконных оказания ему услуг имущественного характера, предоставления иных имущественных прав за совершение действий (бездействие) в пользу взяткодателя или представляемых им лиц, — наказывается штрафом в размере от 50.000 до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, совершенное в значительном размере, — наказывается лишением свободы на срок 50 месяцев. Примечание. Значительным размером взятки в настоящей статье и статье 86 и 87 настоящего Кодекса признаются сумма денег, стоимость ценных бумаг, иного имущества, услуг имущественного характера, иных имущественных прав, превышающие пятьдесят тысяч рублей.","r":"УК ст. 86"},{"d":"Уголовный кодекс РО","t":"Статья 87. Дача взятки","x":"[Р/Ф] [★★★★] Дача взятки должностному лицу, иностранному должностному лицу либо должностным лицом публичной международной организации лично или через посредника, — наказывается штрафом в размере до 70.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, совершенное в значительном размере, — наказывается штрафом в размере до 80.000 рублей либо лишением свободы на срок 50 месяцев. Примечание. Лицо, давшее взятку, освобождается от уголовной ответственности, если оно активно способствовало раскрытию и (или) расследованию преступления и либо в отношении его имело место вымогательство взятки со стороны должностного лица, либо лицо после совершения преступления добровольно сообщило в орган, имеющий право возбудить уголовное дело, о даче взятки.","r":"УК ст. 87"},{"d":"Уголовный кодекс РО","t":"Статья 88. Халатность","x":"[Ф] [★★★★] Халатность, то есть неисполнение или ненадлежащее исполнение должностным лицом своих обязанностей вследствие недобросовестного или небрежного отношения к службе либо обязанностей по должности, если это повлекло причинение крупного ущерба или существенное нарушение прав и законных интересов граждан или организаций либо охраняемых законом интересов общества или государства, — наказывается штрафом в размере от 60.000 до 80.000 рублей либо лишением свободы на срок 40 месяцев. [Ф] [★★★★★] То же деяние, повлекшее по неосторожности причинение тяжкого вреда здоровью или смерти человеку, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 88"},{"d":"Уголовный кодекс РО","t":"Статья 89. Воспрепятствование осуществлению правосудия и производству предварительного расследования","x":"[Р/Ф] [★★★★] Вмешательство в какой бы то ни было форме в деятельность суда в целях воспрепятствования осуществлению правосудия, — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★] Вмешательство в какой бы то ни было форме в деятельность прокурора, следователя или лица, производящего дознание, в целях воспрепятствования всестороннему, полному и объективному расследованию дела, — наказывается штрафом в размере до 80.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Деяния, предусмотренные частями первой или второй настоящей статьи, совершенные лицом с использованием своего служебного положения, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 89"},{"d":"Уголовный кодекс РО","t":"Статья 90. Посягательство на жизнь лица, осуществляющего правосудие или предварительное расследование","x":"[Р/Ф] [★★★★★] Посягательство на жизнь судьи, присяжного заседателя или иного лица, участвующего в отправлении правосудия, прокурора, следователя, лица, производящего дознание, защитника, эксперта, специалиста, сотрудника органов принудительного исполнения РО, а равно их близких в связи с рассмотрением дел или материалов в суде, производством предварительного расследования либо исполнением приговора, решения суда или иного судебного акта, совершенное в целях воспрепятствования законной деятельности указанных лиц либо из мести за такую деятельность, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 90"},{"d":"Уголовный кодекс РО","t":"Статья 91. Неуважение к суду","x":"[Р/Ф] [★★★★] Неуважение к суду, то есть совершение действий (бездействия), свидетельствующих о явном пренебрежении к установленным правилам или порядку проведения судебного заседания, либо неявка участника судебного заседания, вызванного на него надлежащим образом, без уважительной причины или разрешения суда, — наказывается штрафом в размере до 100.000 рублей, либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, выразившееся в оскорблении судьи, присяжного заседателя или иного лица, участвующего в отправлении правосудия, — наказывается штрафом в размере до 80.000 рублей, либо лишением свободы на срок 50 месяцев.","r":"УК ст. 91"},{"d":"Уголовный кодекс РО","t":"Статья 92. Привлечение заведомо невиновного к уголовной ответственности или незаконное возбуждение уголовного дела","x":"[Ф] [★★★★] Привлечение заведомо невиновного к уголовной ответственности — наказывается лишением свободы на срок 40 месяцев. [Ф] [★★★★★] То же деяние, соединенное с обвинением лица в совершении тяжкого или особо тяжкого преступления либо повлекшее причинение крупного ущерба или иные тяжкие последствия, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 92"},{"d":"Уголовный кодекс РО","t":"Статья 93. Незаконное освобождение от уголовной ответственности","x":"[Ф] [★★★★] Незаконное освобождение от уголовной ответственности лица, подозреваемого или обвиняемого в совершении преступления, прокурором, следователем или лицом, производящим дознание, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 93"},{"d":"Уголовный кодекс РО","t":"Статья 94. Незаконные задержание, заключение под стражу или содержание под стражей","x":"[Р/Ф] [★★★★] Заведомо незаконное задержание — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Заведомо незаконные заключение под стражу или содержание под стражей — наказываются лишением свободы на срок 50 месяцев.","r":"УК ст. 94"},{"d":"Уголовный кодекс РО","t":"Статья 95. Принуждение к даче показаний","x":"[Ф] [★★★★] Принуждение подозреваемого, обвиняемого, осужденного, оправданного, потерпевшего или свидетеля к даче показаний либо эксперта или специалиста к даче заключения или показаний путем применения угроз, шантажа или иных незаконных действий со стороны следователя, лица, производящего дознание, или иного сотрудника правоохранительного органа, а равно другого лица с ведома или молчаливого согласия следователя, лица, производящего дознание, или иного сотрудника правоохранительного органа, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 95"},{"d":"Уголовный кодекс РО","t":"Статья 95.1. Разглашение данных предварительного расследования","x":"[Ф] [★★★★] Разглашение данных предварительного расследования лицом, предупрежденным в установленном законом порядке о недопустимости их разглашения, если оно совершено без согласия следователя или лица, производящего дознание, — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 95.1"},{"d":"Уголовный кодекс РО","t":"Статья 96. Вынесение заведомо неправосудных приговора, решения или иного судебного акта","x":"[Ф] [★★★★] Вынесение судьей (судьями) заведомо неправосудных приговора, решения или иного судебного акта — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 40 месяцев. [Ф] [★★★★★] То же деяние, связанное с вынесением незаконного приговора суда к лишению свободы или повлекшее иные тяжкие последствия, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 96"},{"d":"Уголовный кодекс РО","t":"Статья 97. Заведомо ложный донос","x":"[Р/Ф] [★★★★] Заведомо ложный донос о совершении преступления — наказывается штрафом в размере до 50.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, соединенное с обвинением лица в совершении тяжкого или особо тяжкого преступления, — наказывается штрафом в размере до 100.000 рублей либо лишением свободы на срок 50 месяцев.","r":"УК ст. 97"},{"d":"Уголовный кодекс РО","t":"Статья 98. Заведомо ложные показание, заключение эксперта, специалиста","x":"[Ф] [★★★★] Заведомо ложные показание свидетеля, потерпевшего либо заключение или показание эксперта, показание специалиста, в суде либо в ходе досудебного производства, — наказывается штрафом в размере до 45.000 рублей либо лишением свободы на срок 40 месяцев. Примечание. Свидетель, потерпевший, эксперт, специалист или переводчик освобождаются от уголовной ответственности, если они добровольно в ходе досудебного производства или судебного разбирательства до вынесения приговора суда или решения суда заявили о ложности данных ими показаний, заключения или заведомо неправильном переводе.","r":"УК ст. 98"},{"d":"Уголовный кодекс РО","t":"Статья 99. Отказ свидетеля или потерпевшего от дачи показаний","x":"[Р/Ф] [★★★★] Отказ свидетеля или потерпевшего от дачи показаний либо уклонение потерпевшего от прохождения освидетельствования, от производства в отношении его судебной экспертизы в случаях, когда не требуется его согласие, или от предоставления образцов почерка и иных образцов для сравнительного исследования, — наказывается штрафом в размере от 15.000 до 40.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 99"},{"d":"Уголовный кодекс РО","t":"Статья 100. Побег из места лишения свободы, из-под ареста или из-под стражи","x":"[Р/Ф] [★★★★] Побег из места лишения свободы, из-под ареста или из-под стражи, совершенный лицом, отбывающим наказание или находящимся в предварительном заключении, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 100"},{"d":"Уголовный кодекс РО","t":"Статья 100.1. Уклонение от отбывания наказания","x":"[Р/Ф] [от ★ до ★★★★★] Уклонение от отбывания наказания в местах лишения свободы, проявляющееся в неявке лица, объявленного в розыск, в органы правопорядка, — наказывается лишением свободы на срок, предусмотренный приоритетом действующего розыска, где 1 приоритет равняется 10 месяцам лишения свободы. Примечание. Относится к лицам, объявленным в розыск автоматической диспетчерской системой. В данном случае приоритет розыска статичен и не обновляется, наказание следует исходя из фактического приоритета.","r":"УК ст. 100.1"},{"d":"Уголовный кодекс РО","t":"Статья 101. Неисполнение приговора суда, решения суда или иного судебного акта, постановления следователя или прокурора","x":"[Р/Ф] [★★★★] Неисполнение или ненадлежащее исполнение приговора суда, решения суда или иного судебного акта, акта следователя или прокурора, в том числе акта реагирования, запроса или поручения таких лиц, а равно воспрепятствование их исполнению — наказывается лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] То же деяние, совершенное представителем власти, государственным служащим или служащим государственного учреждения, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 101"},{"d":"Уголовный кодекс РО","t":"Статья 102. Посягательство на жизнь сотрудника правоохранительного органа","x":"[Р/Ф] [★★★★★] Посягательство на жизнь сотрудника правоохранительного органа, военнослужащего, а равно их близких в целях воспрепятствования законной деятельности указанных лиц по охране общественного порядка и обеспечению общественной безопасности либо из мести за такую деятельность, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 102"},{"d":"Уголовный кодекс РО","t":"Статья 103. Применение насилия в отношении представителя власти","x":"[Р/Ф] [★★★★] Применение насилия, не опасного для жизни или здоровья, либо угроза применения насилия в отношении представителя власти или его близких в связи с исполнением им своих должностных обязанностей, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 40 месяцев. [Р/Ф] [★★★★★] Применение насилия, опасного для жизни или здоровья, в отношении лиц, указанных в части первой настоящей статьи, — наказывается лишением свободы на срок 50 месяцев.","r":"УК ст. 103"},{"d":"Уголовный кодекс РО","t":"Статья 104. Оскорбление представителя власти","x":"[Р/Ф] [★★★] Публичное оскорбление представителя власти при исполнении им своих должностных обязанностей или в связи с их исполнением — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 30 месяцев. Примечание: Публичным признается оскорбление представителя власти, совершенное в СМИ, либо в группе трех и более человек, которые могли стать свидетелями данного нарушения.","r":"УК ст. 104"},{"d":"Уголовный кодекс РО","t":"Статья 105. Неповиновение законному требованию должностного лица правоохранительного органа","x":"[Р/Ф] [★★★] Неповиновение законному распоряжению или требованию сотрудника полиции, военнослужащего, иного правоохранительного служащего по охране общественного порядка и обеспечению общественной безопасности, а равно воспрепятствование исполнению ими служебных обязанностей, — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] Неповиновение законному распоряжению или требованию прокурора, следователя, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 40 месяцев.","r":"УК ст. 105"},{"d":"Уголовный кодекс РО","t":"Статья 106. Самоуправство","x":"[Р/Ф] [★★★] Самоуправство, то есть самовольное, вопреки установленному законом или иным нормативным правовым актом порядку совершение каких-либо действий, правомерность которых оспаривается организацией или гражданином, если такими действиями причинен существенный вред, — наказывается штрафом в размере до 35.000 рублей либо лишением свободы на срок 30 месяцев. [Р/Ф] [★★★★] То же деяние, совершенное с применением насилия или с угрозой его применения, — наказывается лишением свободы на срок 40 месяцев.","r":"УК ст. 106"},{"d":"Уголовный кодекс РО","t":"Статья 107. Незаконная помеха при задержании, аресте нарушителя, равно как содействие помехе задержанию, аресту нарушителя","x":"[Р/Ф] [★★★] Любые умышленные действия лица, направленные на физическое или иное воспрепятствование законным действиям представителя власти по ограничению свободы подозреваемого или обвиняемого в совершении правонарушения (преступления), — наказываются лишением свободы на срок 30 месяцев. Понятие преступлений против военной службы Преступлениями против военной службы признаются предусмотренные настоящей главой преступления против установленного порядка прохождения военной службы, совершенные военнослужащими, проходящими военную службу по призыву либо по контракту, а также гражданами, пребывающими в запасе, во время прохождения ими военных сборов.","r":"УК ст. 107"},{"d":"Уголовный кодекс РО","t":"Статья 108. Неисполнение приказа","x":"[В] [★★] Неисполнение подчиненным приказа начальника, отданного в установленном порядке, причинившее существенный вред интересам службы, — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 20 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 108"},{"d":"Уголовный кодекс РО","t":"Статья 109. Самовольное оставление части или места службы","x":"[Р/Ф/В] [★★★] Самовольное оставление части или места службы, а равно неявка в срок без уважительных причин на службу при увольнении из части, — наказывается лишением свободы на срок 30 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 109"},{"d":"Уголовный кодекс РО","t":"Статья 110. Дезертирство","x":"[Р/Ф/В] [★★★★] Дезертирство, то есть самовольное оставление части или места службы в целях уклонения от прохождения военной службы, а равно неявка в тех же целях на службу, — наказывается лишением свободы на срок 40 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 110"},{"d":"Уголовный кодекс РО","t":"Статья 111. Умышленные уничтожение или повреждение военного имущества","x":"[В] [★★★★] Умышленные уничтожение или повреждение оружия, боеприпасов или предметов военной техники, — наказывается штрафом в размере до 60.000 рублей либо лишением свободы на срок 40 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 111"},{"d":"Уголовный кодекс РО","t":"Статья 112. Насильственные действия в отношении начальника","x":"[В] [★★★★] Нанесение побоев или применение иного насилия в отношении начальника, совершенные во время исполнения им обязанностей военной службы или в связи с исполнением этих обязанностей, — лишением свободы на срок 40 месяцев с обязательным лишением воинского звания (военного билета).","r":"УК ст. 112"},{"d":"Уголовный кодекс РО","t":"Статья 113. Оскорбление военнослужащего","x":"[В] 1. [★★] Оскорбление одним военнослужащим другого во время исполнения или в связи с исполнением обязанностей военной службы, — наказывается штрафом в размере до 30.000 рублей либо лишением свободы на срок 20 месяцев. [В] 2. [★★★] Умышленные уничтожение или повреждение оружия, боеприпасов или предметов военной техники, — наказывается штрафом в размере до 40.000 рублей либо лишением свободы на срок 30 месяцев. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер Министром РО 21 августа 2026 года [https://docs.google.com/document/d/1bHKw9AgS-x1sD3UFkYfdKtQboHIi7IYxK49aFS8CkXY/edit?tab=t.0](https://docs.google.com/document/d/1bHKw9AgS-x1sD3UFkYfdKtQboHIi7IYxK49aFS8CkXY/edit?tab=t.0) [https://docs.google.com/document/d/187Vzf0Nnv4JthV_EMvDvur8yoguU2UU1zLWyLP0vzJ8/edit?tab=t.0](https://docs.google.com/document/d/187Vzf0Nnv4JthV_EMvDvur8yoguU2UU1zLWyLP0vzJ8/edit?tab=t.0)","r":"УК ст. 113"},{"d":"КоАП РО","t":"Статья 1.1. Законодательство об административных правонарушениях","x":"1. Законодательство об административных правонарушениях состоит из настоящего Кодекса. Законодательство об административных правонарушениях может также дополняться иными законами, устанавливающими перечень административных правонарушений и(или) порядок производства по ним. 2. Основным источником законодательства об административных правонарушениях признается настоящий Кодекс. В случае установления противоречия между законом, дополняющим законодательство об административных правонарушениях, и настоящим Кодексом, суд, прокурор, иное должностное лицо применяет положения настоящего Кодекса.","r":"КоАП ст. 1.1"},{"d":"КоАП РО","t":"Статья 1.2. Задачи законодательства об административных правонарушениях","x":"Задачами законодательства об административных правонарушениях являются защита личности, охрана прав и свобод человека и гражданина, охрана здоровья граждан, санитарно-эпидемиологического благополучия населения, защита общественной нравственности, охрана окружающей среды, установленного порядка осуществления государственной власти, общественного порядка и общественной безопасности, собственности, защита законных экономических интересов физических и юридических лиц, общества и государства от административных правонарушений, а также предупреждение административных правонарушений.","r":"КоАП ст. 1.2"},{"d":"КоАП РО","t":"Статья 1.3. Принцип равенства перед законом","x":"1. Лица, совершившие административные правонарушения, равны перед законом. Физические лица подлежат административной ответственности независимо от пола, расы, национальности, языка, происхождения, имущественного и должностного положения, места жительства, отношения к религии, убеждений, принадлежности к общественным объединениям, а также других обстоятельств. Юридические лица подлежат административной ответственности независимо от места нахождения, организационно-правовых форм, подчиненности, а также других обстоятельств. 2. Особые условия применения мер обеспечения производства по делу об административном правонарушении и привлечения к административной ответственности должностных лиц, выполняющих определенные государственные функции (депутатов, судей, прокуроров, сотрудников Следственного комитета РО и иных лиц), устанавливаются Конституцией РО и федеральными законами.","r":"КоАП ст. 1.3"},{"d":"КоАП РО","t":"Статья 1.4. Презумпция невиновности","x":"1. Лицо подлежит административной ответственности только за те административные правонарушения, в отношении которых установлена его вина. 2. Лицо, в отношении которого ведется производство по делу об административном правонарушении, считается невиновным, пока его вина не будет доказана в порядке, предусмотренном настоящим Кодексом, и установлена вступившим в законную силу постановлением (решением) судьи, органа, должностного лица, рассмотревших дело. 3. Лицо, привлекаемое к административной ответственности, не обязано доказывать свою невиновность, за исключением случаев, предусмотренных примечанием к настоящей статье. 4. Неустранимые сомнения в виновности лица, привлекаемого к административной ответственности, толкуются в пользу этого лица. Примечание. Положения части 3 настоящей статьи не распространяются на должностное лицо, совершившее административное правонарушение.","r":"КоАП ст. 1.4"},{"d":"КоАП РО","t":"Статья 1.5. Обеспечение законности при применении мер административного принуждения в связи с административным правонарушением","x":"1. Лицо, привлекаемое к административной ответственности, не может быть подвергнуто административному наказанию и мерам обеспечения производства по делу об административном правонарушении иначе как на основаниях и в порядке, установленных законом. 2. Применение уполномоченными на то органом или должностным лицом административного наказания и мер обеспечения производства по делу об административном правонарушении в связи с административным правонарушением осуществляется в пределах компетенции указанных органа или должностного лица в соответствии с законом. 3. При применении мер административного принуждения не допускаются решения и действия (бездействие), унижающие человеческое достоинство.","r":"КоАП ст. 1.5"},{"d":"КоАП РО","t":"Статья 1.6. Действие законодательства об административных правонарушениях во времени","x":"1. Лицо, совершившее административное правонарушение, подлежит ответственности на основании закона, действовавшего во время совершения административного правонарушения. 2. Закон, смягчающий или отменяющий административную ответственность за административное правонарушение либо иным образом улучшающий положение лица, совершившего административное правонарушение, имеет обратную силу, то есть распространяется и на лицо, которое совершило административное правонарушение до вступления такого закона в силу и в отношении которого постановление о назначении административного наказания не исполнено. Закон, устанавливающий или отягчающий административную ответственность за административное правонарушение либо иным образом ухудшающий положение лица, обратной силы не имеет. 3. В случае одновременного вступления в силу положений закона, отменяющих административную ответственность за содеянное и устанавливающих за то же деяние уголовную ответственность, лицо подлежит административной ответственности на основании закона, действовавшего во время совершения административного правонарушения. 4. Производство по делу об административном правонарушении осуществляется на основании закона, действующего во время производства по указанному делу.","r":"КоАП ст. 1.6"},{"d":"КоАП РО","t":"Статья 2.1. Административное правонарушение","x":"1. Административным правонарушением признается противоправное, виновное действие (бездействие) физического или юридического лица, за которое настоящим Кодексом или иными Федеральными законами об административных правонарушениях установлена административная ответственность. 2. Юридическое лицо признается виновным в совершении административного правонарушения, если будет установлено, что у него имелась возможность для соблюдения правил и норм, за нарушение которых настоящим Кодексом или Федеральным законом предусмотрена административная ответственность, но данным лицом не были приняты все зависящие от него меры по их соблюдению. 3. Назначение административного наказания юридическому лицу не освобождает от административной ответственности за данное правонарушение виновное физическое лицо, равно как и привлечение к административной или уголовной ответственности физического лица не освобождает от административной ответственности за данное правонарушение юридическое лицо.","r":"КоАП ст. 2.1"},{"d":"КоАП РО","t":"Статья 2.2. Формы вины","x":"1. Административное правонарушение признается совершенным умышленно, если лицо, его совершившее, осознавало противоправный характер своего действия (бездействия), предвидело его вредные последствия и желало наступления таких последствий или сознательно их допускало либо относилось к ним безразлично. 2. Административное правонарушение признается совершенным по неосторожности, если лицо, его совершившее, предвидело возможность наступления вредных последствий своего действия (бездействия), но без достаточных к тому оснований самонадеянно рассчитывало на предотвращение таких последствий либо не предвидело возможности наступления таких последствий, хотя должно было и могло их предвидеть.","r":"КоАП ст. 2.2"},{"d":"КоАП РО","t":"Статья 2.3. Административная ответственность должностных лиц","x":"Административной ответственности подлежит должностное лицо в случае совершения им административного правонарушения в связи с неисполнением либо ненадлежащим исполнением своих служебных обязанностей.","r":"КоАП ст. 2.3"},{"d":"КоАП РО","t":"Статья 2.4. Крайняя необходимость","x":"Не является административным правонарушением причинение лицом вреда охраняемым законом интересам в состоянии крайней необходимости, то есть для устранения опасности, непосредственно угрожающей личности и правам данного лица или других лиц, а также охраняемым законом интересам общества или государства, если эта опасность не могла быть устранена иными средствами и если причиненный вред является менее значительным, чем предотвращенный вред.","r":"КоАП ст. 2.4"},{"d":"КоАП РО","t":"Статья 2.5. Возможность освобождения от административной ответственности при малозначительности административного правонарушения","x":"При малозначительности совершенного административного правонарушения судья, орган, должностное лицо, уполномоченные решить дело об административном правонарушении, могут освободить лицо, совершившее административное правонарушение, от административной ответственности и ограничиться устным замечанием.","r":"КоАП ст. 2.5"},{"d":"КоАП РО","t":"Статья 2.6. Административная ответственность юридических лиц","x":"1. Юридические лица подлежат административной ответственности за совершение административных правонарушений в случаях, предусмотренных статьями раздела II настоящего Кодекса или иными Федеральными законами. 2. В случае, если в статьях разделов настоящего Кодекса не указано, что установленные статьями нормы применяются только к физическому лицу или только к юридическому лицу, данные нормы в равной мере действуют в отношении и физического, и юридического лица, за исключением случаев, если по смыслу данные нормы относятся и могут быть применены только к физическому лицу.","r":"КоАП ст. 2.6"},{"d":"КоАП РО","t":"Статья 3.1. Цели административного наказания","x":"1. Административное наказание является установленной государством мерой ответственности за совершение административного правонарушения и применяется в целях предупреждения совершения новых правонарушений как самим правонарушителем, так и другими лицами. 2. Административное наказание не может иметь своей целью унижение человеческого достоинства физического лица, совершившего административное правонарушение, или причинение ему физических страданий, а также нанесение вреда деловой репутации юридического лица.","r":"КоАП ст. 3.1"},{"d":"КоАП РО","t":"Статья 3.2. Виды административных наказаний","x":"1. За совершение административных правонарушений могут устанавливаться и применяться следующие административные наказания: а) предупреждение; б) административный штраф; в) конфискация орудия совершения или предмета административного правонарушения; г) лишение специального права, предоставленного физическому лицу; д) административный арест; е) административное приостановление деятельности. 2. В отношении юридического лица могут применяться административные наказания, перечисленные в пунктах 1 - 3, 6 части 1 настоящей статьи.","r":"КоАП ст. 3.2"},{"d":"КоАП РО","t":"Статья 3.3. Основные и дополнительные административные наказания","x":"1. Предупреждение, административный штраф, административный арест, административное приостановление деятельности могут устанавливаться и применяться только в качестве основных административных наказаний. 2. Конфискация орудия совершения или предмета административного правонарушения, лишение специального права могут устанавливаться и применяться в качестве как основного, так и дополнительного административного наказания. 3. За одно административное правонарушение может быть назначено основное либо основное и дополнительное административное наказание из наказаний, указанных в санкции применяемой статьи Особенной части настоящего Кодекса. Если санкция применяемой статьи предусматривает обязательное назначение основного и дополнительного административных наказаний, но при этом одно из них не может быть назначено лицу, в отношении которого ведется производство по делу об административном правонарушении, назначается только то из административных наказаний, которое может быть назначено указанному лицу.","r":"КоАП ст. 3.3"},{"d":"КоАП РО","t":"Статья 3.4. Предупреждение","x":"1. Предупреждение - мера административного наказания, выраженная в официальном порицании физического или юридического лица. Предупреждение выносится в письменной форме. 2. Предупреждение устанавливается за впервые совершенные административные правонарушения при отсутствии причинения вреда или возникновения угрозы причинения вреда жизни и здоровью людей, объектам животного и растительного мира, окружающей среде, безопасности государства, угрозы чрезвычайных ситуаций природного и техногенного характера, а также при отсутствии имущественного ущерба.","r":"КоАП ст. 3.4"},{"d":"КоАП РО","t":"Статья 3.5. Административный штраф","x":"1. Административный штраф является денежным взысканием, выражается в твердой денежной сумме и устанавливается для граждан в размере, не превышающем 100.000 рублей, для должностных лиц в размере, не превышающем 150.000 рублей, для юридических лиц не превышающем 1.000.000 рублей. 2. Размер административного штрафа не может быть менее пятисот рублей.","r":"КоАП ст. 3.5"},{"d":"КоАП РО","t":"Статья 3.6. Административный арест","x":"Административный арест заключается в содержании нарушителя в условиях изоляции от общества и устанавливается на срок до 24 суток. Административный арест назначается судьей, должностным лицом.","r":"КоАП ст. 3.6"},{"d":"КоАП РО","t":"Статья 4.1. Общие правила назначения административного наказания","x":"1. Административное наказание за совершение административного правонарушения назначается в пределах, установленных законом, предусматривающим ответственность за данное административное правонарушение, в соответствии с настоящим Кодексом. 2. При назначении административного наказания физическому лицу учитываются характер совершенного им административного правонарушения, личность виновного, его имущественное положение, обстоятельства, смягчающие административную ответственность, и обстоятельства, отягчающие административную ответственность. 3. Назначение административного наказания не освобождает лицо от исполнения обязанности, за неисполнение которой административное наказание было назначено. 4. Никто не может нести административную ответственность дважды за одно и то же административное правонарушение.","r":"КоАП ст. 4.1"},{"d":"КоАП РО","t":"Статья 4.2. Замена административного наказания устным предупреждением","x":"1. За впервые совершенное административное правонарушение, выявленное должностным лицом (органом), административное наказание, подлежащее применению, по решению указанных лиц может быть заменено на предупреждение, при отсутствии причинения вреда или возникновения угрозы причинения вреда жизни и здоровью людей, объектам животного и растительного мира, окружающей среде, объектам безопасности государства, угрозы чрезвычайных ситуаций природного и техногенного характера, а также при отсутствии имущественного ущерба. 2. В случае замены административного наказания на предупреждение дополнительное административное наказание, предусмотренное соответствующей статьей Особенной части настоящего Кодекса, не применяется.","r":"КоАП ст. 4.2"},{"d":"КоАП РО","t":"Статья 4.2.1. Освобождение от наказания в виде административного ареста в связи с внесением залога","x":"1. Лицо, которому за совершение административного правонарушения назначено наказание в виде административного ареста, может быть освобождено от отбывания наказания в связи с внесением залога. 2. Залог вносится либо лицом, привлеченным к административной ответственности лично, либо его представителем или законным представителем в учреждение органа государственной власти, где привлеченный отбывает наказание. 3. Залог за освобождение от наказания рассчитывается по следующему правилу: за каждые сутки административного ареста, неотбытые лицом, привлеченным к административной ответственности, залог составляет 4.000 рублей.","r":"КоАП ст. 4.2.1"},{"d":"КоАП РО","t":"Статья 4.3. Обстоятельства, смягчающие административную ответственность","x":"1. Обстоятельствами, смягчающими административную ответственность, признаются: а) раскаяние лица, совершившего административное правонарушение; б) добровольное прекращение противоправного поведения лицом, совершившим административное правонарушение; в) добровольное сообщение лицом, совершившим административное правонарушение, в орган, уполномоченный осуществлять производство по делу об административном правонарушении, о совершенном административном правонарушении; г) оказание лицом, совершившим административное правонарушение, содействия органу, уполномоченному осуществлять производство по делу об административном правонарушении; д) предотвращение лицом, совершившим административное правонарушение, вредных последствий административного правонарушения; е) добровольное возмещение лицом, совершившим административное правонарушение, причиненного ущерба или добровольное устранение причиненного вреда потерпевшему. 2. Суд, орган, должностное лицо, рассматривающие дело об административном правонарушении, могут признать смягчающими обстоятельства, не указанные в настоящем Кодексе об административных правонарушениях.","r":"КоАП ст. 4.3"},{"d":"КоАП РО","t":"Статья 4.4. Обстоятельства, отягчающие административную ответственность","x":"1. Обстоятельствами, отягчающими административную ответственность, признаются: а) продолжение противоправного поведения, несмотря на требование уполномоченных на то лиц прекратить его; б) повторное совершение однородного административного правонарушения, то есть совершение административного правонарушения в период, когда лицо считается подвергнутым административному наказанию; в) совершение административного правонарушения в составе группы лиц; г) совершение административного правонарушения в условиях чрезвычайного или военного положений, а также контр-террористической операции. 2. Обстоятельства, предусмотренные частью 1 настоящей статьи, не могут учитываться как отягчающие в случае, если указанные обстоятельства предусмотрены в качестве квалифицирующего признака административного правонарушения соответствующими нормами об административной ответственности за совершение административного правонарушения.","r":"КоАП ст. 4.4"},{"d":"КоАП РО","t":"Статья 4.5. Назначение административных наказаний за совершение нескольких административных правонарушений","x":"При совершении лицом двух и более административных правонарушений административное наказание назначается за каждое совершенное административное правонарушение.","r":"КоАП ст. 4.5"},{"d":"КоАП РО","t":"Статья 4.6. Давность привлечения к административной ответственности","x":"1. Срок давности привлечения к административной ответственности устанавливается в 15 месяцев и исчисляется со дня совершения административного правонарушения. 2. При ведущемся производстве по административному правонарушению срок давности привлечения к административной ответственности за совершенное административное правонарушение может быть продлен на основании постановления должностного лица, прокурора или суда.","r":"КоАП ст. 4.6"},{"d":"КоАП РО","t":"Статья 4.7. Возмещение имущественного ущерба и морального вреда, причиненных административным правонарушением","x":"1. Судья, рассматривая дело об административном правонарушении, вправе при отсутствии спора о возмещении имущественного ущерба одновременно с назначением административного наказания решить вопрос о возмещении имущественного ущерба. Споры о возмещении имущественного ущерба разрешаются судом в порядке гражданского судопроизводства. 2. По делу об административном правонарушении, рассматриваемому иными уполномоченными органом или должностным лицом, спор о возмещении имущественного ущерба разрешается судом в порядке гражданского судопроизводства. 3. Споры о возмещении морального вреда, причиненного административным правонарушением, рассматриваются судом в порядке гражданского судопроизводства. Раздел II. ОСОБЕННАЯ ЧАСТЬ","r":"КоАП ст. 4.7"},{"d":"КоАП РО","t":"Статья 5.1. Нарушение трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права","x":"1. Нарушение трудового законодательства и иных нормативных правовых актов, содержащих нормы трудового права, - влечет предупреждение или наложение административного штрафа на должностных лиц в размере от 25.000 до 75.000 рублей; на юридических лиц - от 50.000 до 200.000 рублей. 2. Совершение административного правонарушения, предусмотренного частью 1 настоящей статьи, лицом, ранее подвергнутым административному наказанию за аналогичное административное правонарушение, - влечет наложение административного штрафа на должностных лиц в размере от 50.000 до 120.000 рублей; на юридических лиц - от 100.000 до 250.000 рублей.","r":"КоАП ст. 5.1"},{"d":"КоАП РО","t":"Статья 5.2. Нарушение законодательства о собраниях, митингах, демонстрациях, шествиях и пикетировании","x":"Воспрепятствование организации или проведению собрания, митинга, демонстрации, шествия или пикетирования, проводимых в соответствии с законодательством РО, либо участию в них, а равно принуждение к участию в них - влечет наложение административного штрафа на граждан в размере от 30.000 до 50.000 рублей; на должностных лиц - от 50.000 до 150.000 рублей.","r":"КоАП ст. 5.2"},{"d":"КоАП РО","t":"Статья 5.3. Нарушение порядка рассмотрения обращений граждан","x":"Нарушение установленного законодательством РО порядка рассмотрения обращений граждан, объединений граждан, в том числе юридических лиц, должностными лицами государственных органов, государственных учреждений и иных организаций, на которые возложено осуществление публично значимых функций, - влечет наложение административного штрафа в размере от 10.000 до 50.000 рублей.","r":"КоАП ст. 5.3"},{"d":"КоАП РО","t":"Статья 5.4. Оскорбление","x":"1. [★★] Оскорбление, то есть унижение чести и достоинства другого лица, выраженное в неприличной или иной противоречащей общепринятым нормам морали и нравственности форме, - влечет наложение административного штрафа на граждан в размере от 10.000 до 25.000 рублей или административный арест на срок до 20 суток; на должностных лиц - от 30.000 до 50.000 рублей или административный арест на срок до 20 суток; на юридических лиц - от 25.000 до 100.000 рублей. 2. [★★] Оскорбление, содержащееся в публичном выступлении, публично демонстрирующемся произведении или средствах массовой информации либо совершенное публично с использованием информационно-телекоммуникационных сетей, включая сеть \"Интернет\", или в отношении нескольких лиц, в том числе индивидуально не определенных, - влечет наложение административного штрафа на граждан в размере от 12.000 до 28.000 рублей или административный арест на срок до 20 суток; на должностных лиц - от 50.000 до 100.000 рублей или административный арест на срок до 20 суток; на юридических лиц - от 85.000 до 130.000 рублей. 3. [★★] Оскорбление, совершенное лицом, замещающим государственную должность в связи с осуществлением своих полномочий (должностных обязанностей), - влечет наложение административного штрафа в размере от 90.000 до 130.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 5.4"},{"d":"КоАП РО","t":"Статья 5.5. Клевета","x":"Клевета, то есть распространение заведомо ложных сведений, порочащих честь и достоинство другого лица или подрывающих его репутацию, - влечет наложение административного штрафа на юридических лиц в размере от 100.000 до 200.000 рублей.","r":"КоАП ст. 5.5"},{"d":"КоАП РО","t":"Статья 6.1. Побои","x":"[★★] Нанесение побоев или совершение иных насильственных действий, причинивших физическую боль, если эти действия не содержат уголовно наказуемого деяния, - влечет наложение административного штрафа в размере от 20.000 до 50.000 рублей, либо административный арест на срок до 20 суток.","r":"КоАП ст. 6.1"},{"d":"КоАП РО","t":"Статья 6.2. Занятие проституцией","x":"[★★] Занятие проституцией - влечет наложение административного штрафа в размере от 1.000 до 10.000 рублей или административный арест на срок до 15 суток.","r":"КоАП ст. 6.2"},{"d":"КоАП РО","t":"Статья 6.3. Пропаганда нетрадиционных сексуальных отношений и (или) предпочтений, смены пола, отказа от деторождения","x":"[★★] Пропаганда нетрадиционных сексуальных отношений и (или) предпочтений, смены пола либо отказа от деторождения, выразившаяся в распространении информации и (или) совершении публичных действий, направленных на формирование нетрадиционных сексуальных установок, привлекательности нетрадиционных сексуальных отношений и (или) предпочтений, смены пола либо отказа от деторождения или искаженного представления о социальной равноценности традиционных и нетрадиционных сексуальных отношений и (или) предпочтений либо социальной равноценности рождения детей и отказа от деторождения, либо навязывание информации о нетрадиционных сексуальных отношениях и (или) предпочтениях, смене пола либо об отказе от деторождения, вызывающей интерес к таким отношениям и (или) предпочтениям, смене пола либо отказу от деторождения - влечет наложение административного штрафа на граждан в размере от 25.000 до 100.000 рублей или административный арест на срок до 20 суток; на должностных лиц - от 50.000 до 150.000 рублей.","r":"КоАП ст. 6.3"},{"d":"КоАП РО","t":"Статья 6.4. Курение в общественных местах","x":"Курение, то есть использование специальных устройств или предметов (сигарет, кальянов, вейпов и пр.) в общественных местах - влечет наложение административного штрафа в размере от 5.000 до 15.000 рублей.","r":"КоАП ст. 6.4"},{"d":"КоАП РО","t":"Статья 6.7. Воспрепятствование оказанию медицинской помощи","x":"Воспрепятствование в какой бы то ни было форме законной деятельности медицинского работника по оказанию медицинской помощи, если это действие не содержит признаков уголовно наказуемого деяния, - влечет наложение административного штрафа в размере от 10.000 до 30.000 рублей.","r":"КоАП ст. 6.7"},{"d":"КоАП РО","t":"Статья 7.1. Уничтожение или повреждение чужого имущества","x":"[★] Умышленное уничтожение или повреждение чужого имущества, если эти действия не повлекли причинение значительного ущерба, - влечет наложение административного штрафа в размере от 3.000 до 15.000 рублей или административный арест на срок до 10 суток.","r":"КоАП ст. 7.1"},{"d":"КоАП РО","t":"Статья 8.1. Управление транспортным средством, не зарегистрированным в установленном порядке","x":"Управление транспортным средством, не зарегистрированным в установленном порядке, - влечет наложение административного штрафа в размере от 3.000 до 7.000 рублей.","r":"КоАП ст. 8.1"},{"d":"КоАП РО","t":"Статья 8.2. Управление транспортным средством с нарушением правил установки на нем государственных регистрационных знаков","x":"1. Управление транспортным средством с нечитаемыми, нестандартными или установленными с нарушением требований государственного стандарта государственными регистрационными знаками, за исключением случаев, предусмотренных частью 2 настоящей статьи, - влечет предупреждение или наложение административного штрафа в размере до 5.000 рублей. 2. Управление транспортным средством без государственных регистрационных знаков, а равно управление транспортным средством без установленных на предусмотренных для этого местах государственных регистрационных знаков либо управление транспортным средством с государственными регистрационными знаками, видоизмененными или оборудованными с применением материалов, препятствующих идентификации государственных регистрационных знаков либо позволяющих их видоизменить или скрыть, - влечет наложение административного штрафа в размере от 5.000 до 18.000 рублей или лишение права управления транспортными средствами. 3. Управление транспортным средством с государственными регистрационными знаками, оборудованными с применением устройств, препятствующих идентификации государственных регистрационных знаков либо позволяющих их видоизменить или скрыть, - влечет лишение права управления транспортными средствами.","r":"КоАП ст. 8.2"},{"d":"КоАП РО","t":"Статья 8.3. Управление транспортным средством водителем, не имеющим при себе документов","x":"1. Управление транспортным средством водителем, не имеющим при себе регистрационных документов на транспортное средство - влечет предупреждение или наложение административного штрафа в размере до 3.000 рублей. 2. Управление транспортным средством водителем, не имеющим при себе документов на право управления им - влечет предупреждение или наложение административного штрафа в размере до 7.000 рублей. 3. Передача управления транспортным средством лицу, не имеющему при себе документов на право управления им, - влечет наложение административного штрафа в размере до 25.000 рублей.","r":"КоАП ст. 8.3"},{"d":"КоАП РО","t":"Статья 8.4. Нарушение правил применения ремней безопасности или мотошлемов","x":"Управление транспортным средством водителем, не пристегнутым ремнем безопасности, перевозка пассажиров, не пристегнутых ремнями безопасности, если конструкцией транспортного средства предусмотрены ремни безопасности, а равно управление мотоциклом или мопедом либо перевозка на мотоцикле пассажиров без мотошлемов или в незастегнутых мотошлемах - влечет предупреждение либо наложение административного штрафа в размере до 5.000 рублей.","r":"КоАП ст. 8.4"},{"d":"КоАП РО","t":"Статья 8.5. Управление транспортным средством водителем, не имеющим права управления транспортным средством","x":"1. Управление транспортным средством водителем, не имеющим права управления транспортным средством (за исключением учебной езды), - влечет наложение административного штрафа в размере от 15.000 до 25.000 рублей. [★★] 2. Управление транспортным средством водителем, лишенным права управления транспортными средствами, - влечет наложение административного штрафа в размере от 30.000 до 50.000 рублей, либо административный арест на срок до пятнадцати суток. 3. Передача управления транспортным средством лицу, заведомо не имеющему права управления транспортным средством (за исключением учебной езды) или лишенному такого права, - влечет наложение административного штрафа в размере 50.000 рублей.","r":"КоАП ст. 8.5"},{"d":"КоАП РО","t":"Статья 8.6. Превышение установленной скорости движения","x":"1. Превышение установленной скорости движения транспортного средства на величину более 15 км/ч - влечет наложение административного штрафа в размере до 10.000 рублей. 2. Превышение установленной скорости движения транспортного средства на величину более 40 км/ч - влечет наложение административного штрафа в размере до 25.000 рублей. 3. Превышение установленной скорости движения транспортного средства на величину более 60 км/ч - влечет наложение административного штрафа в размере до 35.000 рублей или лишение права управления транспортными средствами.","r":"КоАП ст. 8.6"},{"d":"КоАП РО","t":"Статья 8.7. Нарушение правил движения через железнодорожные пути","x":"Пересечение железнодорожного пути вне железнодорожного переезда, выезд на железнодорожный переезд при закрытом или закрывающемся шлагбауме либо остановка или стоянка на железнодорожном переезде либо проезд через нерегулируемый железнодорожный переезд, если к переезду в пределах видимости приближается поезд, - влечет наложение административного штрафа в размере 15.000 рублей.","r":"КоАП ст. 8.7"},{"d":"КоАП РО","t":"Статья 8.8. Проезд на запрещающий жест регулировщика","x":"Проезд на запрещающий жест регулировщика, - влечет наложение административного штрафа в размере 2.000 рублей.","r":"КоАП ст. 8.8"},{"d":"КоАП РО","t":"Статья 8.9. Нарушение правил проезда перекрестков","x":"Выезд на перекресток или пересечение проезжей части дороги в случае образовавшегося затора, который вынудил водителя остановиться, создав препятствие для движения транспортных средств в поперечном направлении, - влечет наложение административного штрафа в размере до 2.500 рублей.","r":"КоАП ст. 8.9"},{"d":"КоАП РО","t":"Статья 8.10. Нарушение правил расположения транспортного средства на проезжей части дороги, встречного разъезда или обгона","x":"1. Нарушение правил расположения транспортного средства на проезжей части дороги, встречного разъезда, а равно движение по обочинам или пересечение организованной транспортной или пешей колонны либо занятие места в ней - влечет наложение административного штрафа в размере до 3.500 рублей. 2. Движение по велосипедным или пешеходным дорожкам либо тротуарам - влечет наложение административного штрафа в размере до 4.750 рублей.","r":"КоАП ст. 8.10"},{"d":"КоАП РО","t":"Статья 8.11. Несоблюдение требований, предписанных дорожными знаками или разметкой проезжей части дороги","x":"1. Несоблюдение требований, предписанных дорожными знаками или разметкой проезжей части дороги - влечет предупреждение или наложение административного штрафа в размере до 2.500 рублей. 2. Движение во встречном направлении по дороге с односторонним движением - влечет наложение административного штрафа в размере до 3.000 рублей.","r":"КоАП ст. 8.11"},{"d":"КоАП РО","t":"Статья 8.12. Нарушение правил остановки или стоянки транспортных средств","x":"1. Нарушение правил остановки или стоянки транспортных средств - влечет предупреждение или наложение административного штрафа в размере до 5.000 рублей. 2. Нарушение правил остановки или стоянки транспортных средств в местах, отведенных для остановки, - влечет наложение административного штрафа в размере до 7.000 рублей.","r":"КоАП ст. 8.12"},{"d":"КоАП РО","t":"Статья 8.13. Нарушение правил пользования внешними световыми приборами, звуковыми сигналами, аварийной сигнализацией или знаком аварийной остановки","x":"Нарушение правил пользования внешними световыми приборами, звуковыми сигналами, аварийной сигнализацией или знаком аварийной остановки - влечет предупреждение или наложение административного штрафа в размере до 2.500 рублей.","r":"КоАП ст. 8.13"},{"d":"КоАП РО","t":"Статья 8.14. Нарушение Правил дорожного движения или правил эксплуатации транспортного средства, повлекшее причинение легкого или средней тяжести вреда здоровью потерпевшего","x":"1. Нарушение Правил дорожного движения или правил эксплуатации транспортного средства, повлекшее причинение легкого вреда здоровью потерпевшего, - влечет наложение административного штрафа в размере от 15.000 до 25.000 рублей или лишение права управления транспортными средствами. 2. Нарушение Правил дорожного движения или правил эксплуатации транспортного средства, повлекшее причинение средней тяжести вреда здоровью потерпевшего, - влечет наложение административного штрафа в размере от 20.000 до 37.000 рублей или лишение права управления транспортными средствами.","r":"КоАП ст. 8.14"},{"d":"КоАП РО","t":"Статья 8.15. Невыполнение требования об остановке транспортного средства","x":"[★★] Невыполнение законного требования сотрудника полиции или должностного лица федерального органа исполнительной власти, осуществляющего функции по контролю и надзору в сфере транспорта, об остановке транспортного средства, - влечет наложение административного штрафа в размере от 10.000 до 30.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 8.15"},{"d":"КоАП РО","t":"Статья 8.16. Нарушение Правил дорожного движения пешеходом или иным лицом, участвующим в процессе дорожного движения","x":"Нарушение пешеходом или пассажиром транспортного средства Правил дорожного движения - влечет предупреждение или наложение административного штрафа в размере до 3.000 рублей.","r":"КоАП ст. 8.16"},{"d":"КоАП РО","t":"Статья 8.17. Неуплата штрафов, выданных на автотранспортное средство.","x":"Запрещается передвижение, использование, стоянка транспортного средства, имеющего 10 и более активных (неоплаченных) штрафов - влечет эвакуацию транспортного средства на спецстоянку (штрафстоянку) и оплату повышенного административного штрафа по тарифам спецстоянки","r":"КоАП ст. 8.17"},{"d":"КоАП РО","t":"Статья 8.19. Нарушение установленных правил дорожного движения в области обязанностей пассажиров и водителей, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области обязанностей водителей и пассажиров, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 20.000 рублей.","r":"КоАП ст. 8.19"},{"d":"КоАП РО","t":"Статья 8.20. Нарушение установленных правил дорожного движения в области обязанностей пешеходов и велосипедистов, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области обязанностей пешеходов и велосипедистов, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 8.000 рублей.","r":"КоАП ст. 8.20"},{"d":"КоАП РО","t":"Статья 8.21. Нарушение установленных правил дорожного движения в области расположения ТС на проезжей части, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области расположения ТС на проезжей части, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 10.000 рублей, и/или эвакуацию транспортного средства.","r":"КоАП ст. 8.21"},{"d":"КоАП РО","t":"Статья 8.22. Нарушение установленных правил дорожного движения в области обгона и иных схожих маневров, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области обгона и иных схожих маневров, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 15.000 рублей, и/или лишение права на управление ТС.","r":"КоАП ст. 8.22"},{"d":"КоАП РО","t":"Статья 8.23. Нарушение установленных правил дорожного движения в области остановки и стоянки, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области остановки и стоянки, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 10.000 рублей, и/или эвакуацию транспортного средства.","r":"КоАП ст. 8.23"},{"d":"КоАП РО","t":"Статья 8.24. Нарушение установленных правил дорожного движения в области проезда перекрестков, если данное правонарушение не регулируется настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения в области проезда перекрестков, если данное правонарушение отдельно не регулируется настоящим кодексом, - влечет наложение административного штрафа в размере от 1.500 до 25.000 рублей.","r":"КоАП ст. 8.24"},{"d":"КоАП РО","t":"Статья 8.25. Иные нарушения правил дорожного движения, не установленные настоящим кодексом.","x":"Запрещается нарушение правил дорожного движения, отдельно не указанных в настоящем кодексе, - влечет наложение административного штрафа в размере от 1.500 до 20.000 рублей.","r":"КоАП ст. 8.25"},{"d":"КоАП РО","t":"Статья 9.1. Невыполнение законных требований депутата Федерального Собрания РО","x":"1. [★★] Невыполнение должностным лицом государственного органа, организации или общественного объединения законных требований депутата Федерального Собрания РО либо создание препятствий в осуществлении их деятельности - влечет наложение административного штрафа в размере от 35.000 до 55.000 рублей либо административный арест на срок до 15 суток. 2. Несоблюдение должностным лицом установленных сроков предоставления информации (документов, материалов, ответов на обращения) депутату Федерального Собрания РО - влечет наложение административного штрафа в размере от 30.000 до 70.000 рублей.","r":"КоАП ст. 9.1"},{"d":"КоАП РО","t":"Статья 9.2. Неисполнение распоряжения судьи","x":"1. [★★] Неисполнение законного распоряжения судьи о прекращении действий, нарушающих установленные в суде правила, - влечет наложение административного штрафа в размере от 10.000 до 25.000 рублей или административный арест на срок до пятнадцати суток. 2. Неисполнение законного распоряжения судебного пристава по обеспечению установленного порядка деятельности судов о прекращении действий, нарушающих установленные в суде правила, - влечет наложение административного штрафа в размере от 10.000 до 25.000 рублей.","r":"КоАП ст. 9.2"},{"d":"КоАП РО","t":"Статья 9.3. Непринятие мер по частному определению или постановлению суда, представлению судьи","x":"1. Оставление должностным лицом без рассмотрения частного определения или постановления суда, представления судьи либо непринятие мер по устранению указанных в определении, постановлении или представлении нарушений закона - влечет наложение административного штрафа в размере от 30.000 до 50.000 рублей. 2. Неисполнение или ненадлежащее рассмотрение должностным лицом частного определения или постановления суда, представления судьи - влечет наложение административного штрафа в размере от 35.000 до 55.000 рублей.","r":"КоАП ст. 9.3"},{"d":"КоАП РО","t":"Статья 9.4. Неуважение к Федеральному Собранию","x":"[★★] Неуважение к Федеральному Собранию РО, то есть нарушение установленного порядка проведения заседаний Федерального Собрания или оскорбление депутата Федерального Собрания или неисполнение законного распоряжения Председателя Федерального Собрания или иных должностных лиц, обеспечивающих безопасность заседания, если эти деяния не содержат признаков уголовно-наказуемого деяния, - влечет наложение административного штрафа в размере от 25.000 до 50.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 9.4"},{"d":"КоАП РО","t":"Статья 9.5. Неявка депутата на заседания Федерального Собрания","x":"1. Неявка депутата Федерального Собрания на пленарное или экстренное заседание Федерального Собрания, надлежащим образом уведомленного о таковом заседании, - влечет наложение административного штрафа в размере от 35.000 до 50.000 рублей. 2. Неявка всех заявленных депутатов от органа государственной власти или политической партии РО на экстренное или пленарное заседание Федерального Собрания РО, уведомленных надлежащим образом о таковом заседании - влечет наложение административного штрафа для юридических лиц в размере от 80.000 до 150.000 рублей.","r":"КоАП ст. 9.5"},{"d":"КоАП РО","t":"Статья 9.6. Умышленное совершение государственным служащим деяния, запрещенного нормами служебного поведения","x":"1. Оскорбительное, пренебрежительное или унижающее честь и достоинство гражданина обращение со стороны государственного служащего при исполнении им должностных обязанностей, а равно использование нецензурных слов, кличек, прозвищ или фамильярного обращения - влечет наложение административного штрафа в размере от 20.000 до 200.000 рублей. 2. Несоблюдение государственным служащим требований к внешнему виду, установленных нормативными правовыми актами РО - влечет наложение административного штрафа в размере от 10.000 до 100.000 рублей.","r":"КоАП ст. 9.6"},{"d":"КоАП РО","t":"Статья 10.1. Оскорбление представителя государственной власти","x":"[★★] Оскорбление лица, состоящего на государственной службе, в связи с исполнением им должностных обязанностей, - влечет наложение административного штрафа в размере от 10.000 до 25.000 рублей или административный арест на срок 15 суток.","r":"КоАП ст. 10.1"},{"d":"КоАП РО","t":"Статья 10.2. Отказ от уплаты административного штрафа","x":"[★★] Отказ от уплаты административного штрафа, то есть передача штрафного тикета обратно без уплаты штрафа или устный или письменный отказ лица от уплаты штрафа или игнорирование штрафного тикета, - влечет наложение административного штрафа в двукратном размере суммы неуплаченного административного штрафа, но не менее 3.000 рублей, либо административный арест на срок до 20 суток.","r":"КоАП ст. 10.2"},{"d":"КоАП РО","t":"Статья 10.3. Не рассмотрение или ненадлежащее рассмотрение акта прокурорского реагирования","x":"Не рассмотрение, а равно рассмотрение протеста прокурора, представления прокурора в нарушение установленного законом срока - влечет наложение административного штрафа в размере от 20.000 до 40.000 рублей.","r":"КоАП ст. 10.3"},{"d":"КоАП РО","t":"Статья 10.4. Заведомо ложный вызов специализированных служб","x":"Заведомо ложный вызов пожарной охраны, полиции, скорой медицинской помощи или иных специализированных служб - влечет наложение административного штрафа в размере от 3.000 до 8.000 рублей.","r":"КоАП ст. 10.4"},{"d":"КоАП РО","t":"Статья 10.5. Нарушение порядка деятельности иностранного агента","x":"1. Несообщение лицом, не включенным в реестр иностранных агентов, об осуществлении им деятельности в качестве иностранного агента - влечет наложение административного штрафа на граждан в размере от 30.000 до 50.000 рублей; на должностных лиц - в размере от 60.000 до 120.000 рублей. 2. То же деяние, совершенное юридическим лицом, - влечет наложение административного штрафа в размере от 40.000 до 110.000 рублей с административным приостановлением деятельности данного юридического лица на срок до трех месяцев. 3. Неисполнение иностранным агентом обязанности или ограничения, предусмотренного законодательством РО об иностранных агентах, если эти действия (бездействие) не содержат признаков уголовно-наказуемого деяния - влечет наложение административного штрафа на граждан в размере от 35.000 до 55.000 рублей; на должностных лиц - в размере от 60.000 до 120.000 рублей; на юридических лиц - от 100.000 до 200.000 рублей.","r":"КоАП ст. 10.5"},{"d":"КоАП РО","t":"Статья 10.6. Отказ от прохождения либо неудовлетворительное прохождение государственной проверки","x":"1. Отказ организации либо ее должностных лиц от прохождения предусмотренной законом государственной проверки, выражающийся в непредставлении необходимых документов, сведений и материалов, иные действия (бездействия), повлекшие нарушение установленной процедуры государственной проверки, - влечет наложение административного штрафа от 20.000 до 40.000 рублей; на юридических лиц - от 50.000 до 500.000 рублей. 2. Неудовлетворительное прохождение государственной проверки вследствие допущенных нарушений, препятствующих признанию ее результатов соответствующими установленным требованиям, - влечет наложение административного штрафа до 500.000 рублей юридическим лицам.","r":"КоАП ст. 10.6"},{"d":"КоАП РО","t":"Статья 10.7. Незаконный отказ в доступе должностному лицу органа исполнительной власти, осуществляющего федеральный государственный контроль (надзор) в сфере здравоохранения, к осмотру территорий, помещений организации, в отношении которой проводится государственная проверка","x":"Незаконный отказ в доступе, а равно незаконное воспрепятствование доступу должностного лица Федерального органа исполнительной власти, осуществляющего федеральный государственный контроль (надзор) в сфере здравоохранения, проводящего государственную проверку в соответствии с законодательством РО, к осмотру производственных, складских, служебных и иных помещений и территорий, находящихся в пользовании проверяемой организации - влечет наложение административного штрафа на должностных лиц в размере 25.000 рублей; на юридических лиц - от 50.000 до 100.000 рублей.","r":"КоАП ст. 10.7"},{"d":"КоАП РО","t":"Статья 11.1. Мелкое хулиганство","x":"[★★] Мелкое хулиганство, то есть нарушение общественного порядка, выражающее явное неуважение к обществу, сопровождающееся нецензурной бранью в общественных местах, оскорбительным приставанием к гражданам, а равно уничтожением или повреждением чужого имущества, - влечет наложение административного штрафа в размере от 5.000 до 20.000 рублей или административный арест на срок до пятнадцати суток.","r":"КоАП ст. 11.1"},{"d":"КоАП РО","t":"Статья 11.2. Нарушение установленного порядка организации либо проведения собрания, митинга, демонстрации, шествия или пикетирования","x":"1. Нарушение организатором публичного мероприятия установленного порядка организации либо проведения собрания, митинга, демонстрации, шествия или пикетирования, за исключением случаев, предусмотренных настоящей статьей, - влечет наложение административного штрафа в размере от 25.000 до 50.000 рублей. 2. Организация либо проведение публичного мероприятия без подачи в установленном порядке уведомления о проведении публичного мероприятия, - влечет наложение административного штрафа в размере от 30.000 до 70.000 рублей. 3. [★★] Нарушение участником публичного мероприятия установленного порядка проведения собрания, митинга, демонстрации, шествия или пикетирования - влечет наложение административного штрафа в размере от 20.000 до 35.000 рублей или административный арест на срок до 20 суток.","r":"КоАП ст. 11.2"},{"d":"КоАП РО","t":"Статья 11.3. Публичные действия, направленные на дискредитацию использования Вооруженных Сил РО","x":"1. Публичные действия, направленные на дискредитацию использования Вооруженных Сил РО в целях защиты интересов РО и ее граждан, поддержания международного мира и безопасности, в том числе публичные призывы к воспрепятствованию использования Вооруженных Сил РО в указанных целях, либо на дискредитацию исполнения государственными органами РО своих полномочий за пределами территории РО в указанных целях, а равно на дискредитацию оказания добровольческими формированиями, организациями или лицами содействия в выполнении задач, возложенных на Вооруженные Силы РО или войска национальной гвардии РО, если эти действия не содержат признаков уголовно наказуемого деяния, - влекут наложение административного штрафа в размере от 40.000 до 55.000 рублей; на юридических лиц - от 100.000 до 250.000 рублей. 2. Те же действия, сопровождающиеся призывами к проведению несанкционированных публичных мероприятий, а равно создающие угрозу причинения вреда жизни и (или) здоровью граждан, имуществу, угрозу массового нарушения общественного порядка и (или) общественной безопасности либо угрозу создания помех функционированию или прекращения функционирования объектов жизнеобеспечения, транспортной или социальной инфраструктуры, кредитных организаций, объектов энергетики, промышленности или связи, если эти действия не содержат признаков уголовно наказуемого деяния, - влекут наложение административного штрафа в размере от 50.000 до 70.000 рублей; на юридических лиц - от 200.000 до 300.000 рублей.","r":"КоАП ст. 11.3"},{"d":"КоАП РО","t":"Статья 11.4. Нарушение порядка, установленного в период действия чрезвычайного или военного положения","x":"1. [★★] Нарушение установленного режима комендантского часа, действующего в период чрезвычайного или военного положения, - влечет административный арест на срок до 20 суток или наложение административного штрафа в размере до 20.000 рублей. 2. [★★] Организация, проведение либо активное участие в публичном мероприятии (включая собрание, митинг, демонстрацию, шествие или пикетирование) в период действия чрезвычайного или военного положения - влечет административный арест на срок до 20 суток или наложение административного штрафа в размере до 35.000 рублей. 3. [★★] Отказ гражданина предъявить по требованию уполномоченного лица удостоверение личности в зоне действия чрезвычайного или военного положения - влечет административный арест на срок до 15 суток или наложение административного штрафа в размере до 15.000 рублей.","r":"КоАП ст. 11.4"},{"d":"КоАП РО","t":"Статья 11.5. Распитие в общественных местах алкогольных напитков","x":"[★] Распитие в общественных местах алкогольной продукции, а равно нахождение в общественном месте в состоянии алкогольного опьянения - влечет наложение административного штрафа в размере от 4.000 до 12.000 рублей или административный арест на срок до 10 суток. Примечание 1. Для целей настоящего Кодекса под общественным местом понимается любая территория или объект, предназначенные (используемые) для свободного доступа неопределенного круга лиц, включая (но не ограничиваясь): улицы, парки, скверы, пляжи, транспорт общего пользования, а также здания, строения, сооружения (в том числе административные, торговые, культурно-развлекательные, спортивные, медицинские и иные учреждения) и непосредственно прилегающие к ним территории.","r":"КоАП ст. 11.5"},{"d":"КоАП РО","t":"Статья 11.6. Нахождение в общественном месте в неприемлемом виде","x":"[★] Нахождение в общественном месте без любого из элементов верхней одежды, то есть с оголенным торсом и(или) низом, - влечет предупреждение или наложение административного штрафа в размере от 5.000 до 15.000 рублей или административный арест на срок 10 суток.","r":"КоАП ст. 11.6"},{"d":"КоАП РО","t":"Статья 11.7. Обнажение оружия в общественных местах","x":"[★★] Обнажение огнестрельного и (или) холодного вида оружия, специальных средств или спортивного инвентаря в общественном месте, лицом не состоящим на государственной службе в правоохранительных органах РО или не исполняющим на тот момент должностные обязанности, без обоснованной необходимости, - влечет предупреждение или наложение административного штрафа в размере от 10.000 до 20.000 рублей или административный арест на срок до 15 суток.","r":"КоАП ст. 11.7"},{"d":"КоАП РО","t":"Статья 11.8. Нарушение режима посещения закрытых территорий","x":"[★★★] Незаконное проникновение на закрытую, в соответствии с законодательством РО, территорию, равно как и нахождение на такой территории - влечет наложение административного штрафа на граждан в размере от 50.000 до 80.000 рублей либо административный арест на срок до 24 суток. Раздел III. Судьи, органы, должностные лица, уполномоченные рассматривать дела об административных правонарушениях","r":"КоАП ст. 11.8"},{"d":"КоАП РО","t":"Статья 12.1. Судьи и органы, уполномоченные рассматривать дела об административных правонарушениях","x":"Дела об административных правонарушениях, предусмотренных настоящим Кодексом, рассматриваются в пределах компетенции, установленной настоящим Кодексом: 1) судьями; 2) федеральными органами исполнительной власти, их структурными подразделениями, территориальными органами и структурными подразделениями территориальных органов, а также иными государственными органами в соответствии с задачами и функциями, возложенными на них федеральными законами либо нормативными правовыми актами Премьер Министра РО или Правительства РО; 3) органами прокуратуры РО, прокурорами; 4) председателем Федерального Собрания РО.","r":"КоАП ст. 12.1"},{"d":"КоАП РО","t":"Статья 12.2. Судьи","x":"Судьи уполномочены рассматривать дело о любом административном правонарушении, предусмотренном настоящим Кодексом.","r":"КоАП ст. 12.2"},{"d":"КоАП РО","t":"Статья 12.3. Органы внутренних дел (полиция)","x":"Органы внутренних дел (полиция) рассматривают дела об административных правонарушениях при непосредственном обнаружении должностными лицами органов внутренних дел (полиции) признаков административных правонарушений, за исключением правонарушений предусмотренных ст. 5.1, 5.3, 5.5, 9.1 - 9.6, 10.3, 10.5, 10.6, 10.7, 11.3 настоящего Кодекса.","r":"КоАП ст. 12.3"},{"d":"КоАП РО","t":"Статья 12.4. Органы прокуратуры (прокуроры)","x":"Органы прокуратуры РО (прокуроры) уполномочены рассматривать дело о любом административном правонарушении, предусмотренном настоящим Кодексом.","r":"КоАП ст. 12.4"},{"d":"КоАП РО","t":"Статья 12.5. Председатель Федерального Собрания РО","x":"Председатель Федерального Собрания (Государственной Думы) РО рассматривает дела об административных правонарушениях при непосредственном обнаружении им признаков административных правонарушений, предусмотренных ст. 9.1, 9.4, 9.5 настоящего Кодекса.","r":"КоАП ст. 12.5"},{"d":"КоАП РО","t":"Статья 12.6. Органы военной полиции Вооруженных Сил РО","x":"Органы военной полиции Вооруженных Сил РО рассматривают дела об административных правонарушениях при непосредственном обнаружении ими признаков административных правонарушений в отношении военнослужащих Вооруженных Сил РО. Раздел IV. Производство по делам об административных правонарушениях","r":"КоАП ст. 12.6"},{"d":"КоАП РО","t":"Статья 13.1. Задачи производства по делам об административных правонарушениях","x":"Задачами производства по делам об административных правонарушениях являются всестороннее, полное, объективное и своевременное выяснение обстоятельств каждого дела, разрешение его в соответствии с законом, обеспечение исполнения вынесенного постановления, а также выявление причин и условий, способствовавших совершению административных правонарушений.","r":"КоАП ст. 13.1"},{"d":"КоАП РО","t":"Статья 13.2. Доведение до сведения участников производства по делу об административном правонарушении информации о поступивших судье внепроцессуальных обращениях","x":"1. Не допускается внепроцессуальное обращение к судье, в производстве которого находится дело об административном правонарушении, либо к председателю суда, его заместителю, председателю судебного состава или председателю судебной коллегии по делам об административных правонарушениях, находящимся в производстве суда. 2. Информация о внепроцессуальных обращениях государственных органов, иных органов, организаций, должностных лиц или граждан, поступивших судье, в производстве которого находится дело об административном правонарушении, либо председателю суда, его заместителю, председателю судебного состава или председателю судебной коллегии по делам об административных правонарушениях, находящимся в производстве суда, подлежит преданию гласности и доведению до сведения участников производства по делу и не является основанием для проведения процессуальных действий или принятия процессуальных решений по делам об административных правонарушениях.","r":"КоАП ст. 13.2"},{"d":"КоАП РО","t":"Статья 13.3. Ходатайства","x":"1. Лица, участвующие в производстве по делу об административном правонарушении, имеют право заявлять ходатайства, подлежащие обязательному рассмотрению судьей, органом, должностным лицом, в производстве которых находится данное дело. 2. Ходатайство заявляется в письменной форме и подлежит немедленному рассмотрению. Решение об отказе в удовлетворении ходатайства выносится судьей, органом, должностным лицом, в производстве которых находится дело об административном правонарушении, в виде определения или решения на месте.","r":"КоАП ст. 13.3"},{"d":"КоАП РО","t":"Статья 13.4. Обстоятельства, исключающие производство по делу об административном правонарушении","x":"1. Производство по делу об административном правонарушении не может быть начато, а начатое производство подлежит прекращению при наличии хотя бы одного из следующих обстоятельств: 1) отсутствие события административного правонарушения; 2) отсутствие состава административного правонарушения; 3) действия лица в состоянии крайней необходимости; 4) издание акта амнистии, если такой акт устраняет применение административного наказания; 5) признание утратившими силу закона или его положения, устанавливающих административную ответственность за содеянное, за исключением случая одновременного вступления в силу положений закона, отменяющих административную ответственность за содеянное и устанавливающих за то же деяние уголовную ответственность; 6) истечение сроков давности привлечения к административной ответственности; 7) смерть физического лица, в отношении которого ведется производство по делу об административном правонарушении; 8) иные предусмотренные настоящим Кодексом обстоятельства, при наличии которых лицо, совершившее действия (бездействие), содержащие признаки состава административного правонарушения, освобождается от административной ответственности.","r":"КоАП ст. 13.4"},{"d":"КоАП РО","t":"Статья 13.5. Прокурорский надзор","x":"Генеральный прокурор РО и назначаемые им прокуроры осуществляют в пределах своей компетенции надзор за соблюдением Конституции РО и исполнением действующих на территории РО законов при производстве по делам об административных правонарушениях, за исключением дел, находящихся в производстве суда.","r":"КоАП ст. 13.5"},{"d":"КоАП РО","t":"Статья 13.6. Подача процессуальных документов участниками производства по делу об административном правонарушении","x":"Заявление, ходатайство, жалоба, протест и иные документы подаются участниками производства по делу об административном правонарушении в электронном виде, в том числе в форме электронного документа. Ходатайства могут быть заявлены в простой устной форме при рассмотрении дела об административном правонарушении на месте. В случае подачи заявления, ходатайства, жалобы, протеста и иных документов в электронном виде, в том числе в форме электронного документа, прилагаемые к ним документы должны быть представлены также в электронном виде, в том числе в форме электронного документа.","r":"КоАП ст. 13.6"},{"d":"КоАП РО","t":"Статья 13.7. Истребование материалов дела об административном правонарушении","x":"1. При подготовке к рассмотрению жалобы на постановление (решение) по делу об административном правонарушении судья выносит определение об истребовании материалов дела об административном правонарушении, если для рассмотрения жалобы необходимо получение указанных материалов. 2. В определении об истребовании материалов дела указываются наименование суда, сведения о деле, постановление (решение) по которому обжалуется, сведения о лице, в отношении которого вынесено постановление, статья настоящего Кодекса, предусматривающая административную ответственность за совершенное административное правонарушение, а также орган, должностное лицо или судья, в распоряжении которых находятся материалы дела. 3. Материалы дела об административном правонарушении направляются в суд, вынесший определение об их истребовании, не позднее суток со дня получения определения, если иной срок не установлен в самом определении. 4. Орган, должностное лицо или судья, в распоряжении которых находятся материалы дела об административном правонарушении, обязаны направить в суд материалы дела в полном объеме.","r":"КоАП ст. 13.7"},{"d":"КоАП РО","t":"Статья 14.1. Лицо, в отношении которого ведется производство по делу об административном правонарушении","x":"1. Лицо, в отношении которого ведется производство по делу об административном правонарушении, вправе знакомиться со всеми материалами дела, с аудио- и видеозаписями, делать выписки из материалов дела об административном правонарушении, давать объяснения, представлять доказательства, заявлять ходатайства и отводы, пользоваться юридической помощью защитника, а также иными процессуальными правами в соответствии с настоящим Кодексом. 2. Дело об административном правонарушении рассматривается с участием лица, в отношении которого ведется производство по делу об административном правонарушении. В отсутствие указанного лица дело может быть рассмотрено, если имеются данные о надлежащем извещении лица о месте и времени рассмотрения дела и если от лица не поступило ходатайство об отложении рассмотрения дела либо если такое ходатайство оставлено без удовлетворения. 3. Судья, орган, должностное лицо, рассматривающие дело об административном правонарушении, вправе признать обязательным присутствие при рассмотрении дела лица, в отношении которого ведется производство по делу об административном правонарушении. 4. Сотрудник, ведущий дело об административном правонарушении, обязан хранить доказательства оснований для возбуждения дела об административном правонарушении в течение 48 часов, запись должна быть цельная, со звуком, без элементов монтажа.","r":"КоАП ст. 14.1"},{"d":"КоАП РО","t":"Статья 14.2. Потерпевший","x":"1. Потерпевшим является физическое лицо или юридическое лицо, которым административным правонарушением причинен физический, имущественный или моральный вред. 2. Потерпевший вправе знакомиться со всеми материалами дела об административном правонарушении, с аудио- и видеозаписями, делать выписки из материалов дела об административном правонарушении, давать объяснения, представлять доказательства, заявлять ходатайства и отводы, пользоваться юридической помощью представителя, обжаловать постановление (решение) по данному делу, пользоваться иными процессуальными правами в соответствии с настоящим Кодексом. 3. Потерпевший может быть опрошен.","r":"КоАП ст. 14.2"},{"d":"КоАП РО","t":"Статья 14.3. Законные представители юридического лица","x":"1. Защиту прав и законных интересов юридического лица, в отношении которого ведется производство по делу об административном правонарушении, или юридического лица, являющегося потерпевшим, осуществляют его законные представители. 2. Законными представителями юридического лица в соответствии с настоящим Кодексом являются его руководитель, а также иное лицо, признанное в соответствии с законом или учредительными документами органом юридического лица. Полномочия законного представителя юридического лица подтверждаются документами, удостоверяющими его служебное положение. 3. Дело об административном правонарушении, совершенном юридическим лицом, рассматривается судьей с участием его законного представителя или защитника. В отсутствие указанных лиц дело может быть рассмотрено лишь в случаях, если имеются данные о надлежащем извещении лиц о месте и времени рассмотрения дела и если от них не поступило ходатайство об отложении рассмотрения дела либо если такое ходатайство оставлено без удовлетворения. 4. При рассмотрении дела об административном правонарушении, совершенном юридическим лицом, судья, орган, должностное лицо, в производстве которых находится дело об административном правонарушении, вправе признать обязательным присутствие законного представителя юридического лица.","r":"КоАП ст. 14.3"},{"d":"КоАП РО","t":"Статья 14.4. Защитник и представитель","x":"1. Для оказания юридической помощи лицу, в отношении которого ведется производство по делу об административном правонарушении, в производстве по делу об административном правонарушении может участвовать защитник, а для оказания юридической помощи потерпевшему - представитель. 2. В качестве защитника или представителя к участию в производстве по делу об административном правонарушении допускается адвокат или иное лицо. 3. Полномочия адвоката удостоверяются ордером. Полномочия иного лица, оказывающего юридическую помощь, удостоверяются доверенностью, оформленной в соответствии с законом. 4. Защитник и представитель, допущенные к участию в производстве по делу об административном правонарушении, вправе знакомиться со всеми материалами дела, с аудио- и видеозаписями, делать выписки из материалов дела об административном правонарушении, представлять доказательства, заявлять ходатайства и отводы, участвовать в рассмотрении дела, обжаловать применение мер обеспечения производства по делу, постановление (решение) по делу, пользоваться иными процессуальными правами в соответствии с настоящим Кодексом.","r":"КоАП ст. 14.4"},{"d":"КоАП РО","t":"Статья 14.5. Свидетель","x":"1. В качестве свидетеля по делу об административном правонарушении может быть вызвано лицо, которому могут быть известны обстоятельства дела, подлежащие установлению. 2. Свидетель обязан явиться по вызову судьи, органа, должностного лица, в производстве которых находится дело об административном правонарушении, и дать правдивые показания: сообщить все известное ему по делу, ответить на поставленные вопросы. 3. Свидетель вправе не свидетельствовать против себя самого, своего супруга. 4. Свидетель предупреждается об ответственности за дачу заведомо ложных показаний. 5. За отказ или за уклонение от исполнения обязанностей, предусмотренных частью 2 настоящей статьи, свидетель несет ответственность, предусмотренную законом.","r":"КоАП ст. 14.5"},{"d":"КоАП РО","t":"Статья 14.6. Прокурор","x":"1. Прокурор в пределах своих полномочий вправе: 1) возбуждать производство по делу об административном правонарушении; 2) участвовать в рассмотрении дела об административном правонарушении, представлять доказательства, заявлять ходатайства, давать заключения по вопросам, возникающим во время рассмотрения дела; 3) приносить протест на постановление (решение) по делу об административном правонарушении независимо от участия в деле, а также совершать иные предусмотренные федеральным законом действия. 2. Прокурор извещается о месте и времени рассмотрения дела об административном правонарушении, возбужденного по инициативе прокурора.","r":"КоАП ст. 14.6"},{"d":"КоАП РО","t":"Статья 15.1. Обстоятельства, подлежащие выяснению по делу об административном правонарушении","x":"По делу об административном правонарушении выяснению подлежат: 1) наличие события административного правонарушения; 2) лицо, совершившее противоправные действия (бездействие), за которые настоящим Кодексом или федеральным законом предусмотрена административная ответственность; 3) виновность лица в совершении административного правонарушения; 4) обстоятельства, смягчающие административную ответственность, и обстоятельства, отягчающие административную ответственность; 5) характер и размер ущерба, причиненного административным правонарушением; 6) обстоятельства, исключающие производство по делу об административном правонарушении; 7) иные обстоятельства, имеющие значение для правильного разрешения дела, а также причины и условия совершения административного правонарушения.","r":"КоАП ст. 15.1"},{"d":"КоАП РО","t":"Статья 15.2. Доказательства","x":"1. Доказательствами по делу об административном правонарушении являются любые фактические данные, на основании которых судья, орган, должностное лицо, в производстве которых находится дело, устанавливают наличие или отсутствие события административного правонарушения, виновность лица, привлекаемого к административной ответственности, а также иные обстоятельства, имеющие значение для правильного разрешения дела. 2. Эти данные устанавливаются объяснениями лица, в отношении которого ведется производство по делу об административном правонарушении, показаниями потерпевшего, свидетелей, иными документами, а также показаниями специальных технических средств, вещественными доказательствами. 3. Не допускается использование доказательств по делу об административном правонарушении, если указанные доказательства получены с нарушением закона.","r":"КоАП ст. 15.2"},{"d":"КоАП РО","t":"Статья 15.3. Объяснения лица, в отношении которого ведется производство по делу об административном правонарушении, показания потерпевшего и свидетелей","x":"1. Объяснения лица, в отношении которого ведется производство по делу об административном правонарушении, показания потерпевшего и свидетелей представляют собой сведения, имеющие отношение к делу и сообщенные указанными лицами в устной или письменной форме. 2. Объяснения лица, в отношении которого ведется производство по делу об административном правонарушении, показания потерпевшего и свидетелей отражаются в аудио (видео) протоколе, постановлении по делу об административном правонарушении.","r":"КоАП ст. 15.3"},{"d":"КоАП РО","t":"Статья 15.4. Вещественные доказательства","x":"1. Под вещественными доказательствами по делу об административном правонарушении понимаются орудия совершения или предметы административного правонарушения, в том числе орудия совершения или предметы административного правонарушения, сохранившие на себе его следы. 2. Вещественные доказательства в случае необходимости фотографируются или фиксируются иным установленным способом и приобщаются к делу об административном правонарушении. О наличии вещественных доказательств делается запись в протоколе об административном правонарушении или в ином протоколе, предусмотренном настоящим Кодексом.","r":"КоАП ст. 15.4"},{"d":"КоАП РО","t":"Статья 15.5. Документы","x":"1. Документы признаются доказательствами, если сведения, изложенные или удостоверенные в них организациями, их объединениями, должностными лицами и гражданами, имеют значение для производства по делу об административном правонарушении. 2. Документы могут содержать сведения, зафиксированные как в письменной, так и в иной форме. К документам относятся материалы фото- и киносъемки, звуко- и видеозаписи, информационных баз и банков данных и иные носители информации. 3. Судья, орган, должностное лицо, в производстве которых находится дело об административном правонарушении, обязаны принять необходимые меры по обеспечению сохранности документов до разрешения дела по существу, а также принять решение о них по окончании рассмотрения дела.","r":"КоАП ст. 15.5"},{"d":"КоАП РО","t":"Статья 15.6. Поручения и запросы по делу об административном правонарушении","x":"1. Для получения доказательств по делу об административном правонарушении должностное лицо, осуществляющее производство по делу об административном правонарушении, вправе направлять запросы в органы исполнительной власти и подведомственные ему учреждения, иные органы исполнительной власти либо поручения о совершении отдельных действий, предусмотренных настоящим Кодексом, должностному лицу указанного органа или учреждения. 2. Поручение либо запрос по делу об административном правонарушении подлежит исполнению не позднее чем в двухдневный срок со дня получения указанного поручения либо запроса.","r":"КоАП ст. 15.6"},{"d":"КоАП РО","t":"Статья 15.7. Истребование сведений","x":"Судья, орган, должностное лицо, в производстве которых находится дело об административном правонарушении, вправе вынести определение об истребовании сведений, необходимых для разрешения дела, в том числе сведений (информации), необходимых для расчета размера административного штрафа. Истребуемые сведения должны быть направлены в двухдневный срок со дня получения определения. При невозможности представления указанных сведений организация обязана в однодневный срок уведомить об этом в письменной форме судью, орган, должностное лицо, вынесших определение.","r":"КоАП ст. 15.7"},{"d":"КоАП РО","t":"Статья 15.8. Оценка доказательств","x":"Судья, члены коллегиального органа, должностное лицо, осуществляющие производство по делу об административном правонарушении, оценивают доказательства по своему внутреннему убеждению, основанному на всестороннем, полном и объективном исследовании всех обстоятельств дела в их совокупности. Никакие доказательства не могут иметь заранее установленную силу.","r":"КоАП ст. 15.8"},{"d":"КоАП РО","t":"Статья 16.1. Меры обеспечения производства по делу об административном правонарушении","x":"1. В целях пресечения административного правонарушения, установления личности нарушителя, составления протокола об административном правонарушении при невозможности его составления на месте выявления административного правонарушения, обеспечения своевременного и правильного рассмотрения дела об административном правонарушении и исполнения принятого по делу постановления уполномоченное лицо вправе в пределах своих полномочий применять следующие меры обеспечения производства по делу об административном правонарушении: 1) административное задержание; 2) личный досмотр, досмотр вещей, досмотр транспортного средства, находящихся при физическом лице; осмотр принадлежащих юридическому лицу помещений, территорий, находящихся там вещей и документов; 3) освидетельствование на состояние алкогольного опьянения; 4) медицинское освидетельствование на состояние алкогольного опьянения; 5) задержание транспортного средства; 6) привод; 7) отстранение от управления транспортным средством. 2. При применении мер обеспечения производства по делу об административном правонарушении, рассмотрении дела об административном правонарушении, производстве предусмотренных настоящим Кодексом процессуальных действий, а равно судья, или по его поручению секретарь судебного заседания, должностное лицо, представитель коллегиального органа, рассматривающие дело, обязаны вести полную непрерывную видеозапись фактических обстоятельств происходящего и иных сведений, имеющих значение для производства по делу и любых других процессуальных действий. Видеозапись осуществляется техническими средствами, обеспечивающими…","r":"КоАП ст. 16.1"},{"d":"КоАП РО","t":"Статья 16.2. Административное задержание","x":"1. Административное задержание - кратковременное ограничение свободы физического лица, применяемое в целях пресечения административного правонарушения, установления личности правонарушителя, составления протокола об административном правонарушении, назначения административного наказания либо обеспечения исполнения постановления по делу об административном правонарушении, если иное не установлено настоящим Кодексом. 2. Применением административного задержания признается также кратковременное ограничение свободы физического лица, выраженное в обязательном требовании следовать за должностным лицом, оставаться в определенном месте либо не покидать место совершения административного правонарушения на время производства необходимых процессуальных действий, предусмотренных настоящим Кодексом. 3. Административное задержание вправе осуществлять должностные лица органов внутренних дел (полиции), органов Федеральной Службы Безопасности РО, органов военной полиции Вооруженных Сил РО.","r":"КоАП ст. 16.2"},{"d":"КоАП РО","t":"Статья 16.2.1. Порядок административного задержания подозреваемого","x":"1. Задержание лица производится в следующей последовательности: а) применить специальные средства с целью ограничить свободу лица; б) предъявить свое служебное удостоверение или иной идентификационный знак, подтверждающий принадлежность к органам государственной власти; в) на усмотрение сотрудника, проводящего задержание, провести обыск; г) разъяснить основания задержания и права, установленные частью 2 статьи 16.2.1 настоящего Кодекса; д) доставить подозреваемого в территориальный орган власти, отдел внутренних дел или иное место для дознания или следствия; е) провести идентификацию личности задержанного и проверку на принадлежность задержанного к государственным органам; ж) реализовать права задержанного (на ожидание ответа адвоката отводится 3 минуты, на его приезд - 7. Задержанный вправе выбрать между государственным и частным защитником. На звонок и разговор по телефону отводится 2 минуты); з) в случае, если задержанный является государственным служащим, уведомить уполномоченные органы о задержании согласно ст. 16.2.2 настоящего Кодекса; з) произвести следственные действия, если в этом есть необходимость. 2. В рамках административного задержания лицо имеет право хранить молчание и не свидетельствовать против себя и своего супруга, знакомиться с материалами дела, пользоваться юридической помощью защитника (адвоката), право запросить бесплатного защитника, осуществлять телефонный звонок и разговор длительностью до 2 минут, заявлять ходатайства и отводы.","r":"КоАП ст. 16.2.1"},{"d":"КоАП РО","t":"Статья 16.2.2. Особый порядок административного задержания","x":"1. В случае, если задержанное лицо состоит на государственной службе РО и (или) является должностным лицом органа государственной власти, государственного органа, после доставления задержанного лица в место рассмотрения дела незамедлительно вызывается прокурор и вышестоящее должностное лицо (руководитель) задержанного лица. 2. На время ожидания ответа указанных лиц процессуальный срок, установленный ч. 1 ст. 16.2.2 настоящего Кодекса, приостанавливается, но не более чем на 10 минут. 3. При прибытии прокурора должностное лицо, осуществляющее административное задержание, передает прокурору все материалы дела об административном правонарушении. Прокурор заслушивает объяснения сторон по делу, знакомится с материалами дела, после чего дает оценку правомерности задержания, устанавливает наличие или отсутствие состава административного правонарушения в действиях (бездействии) задержанного лица и выносит одно из следующих решений: 1) о назначении административного наказания, определяя вид и размер наказания; 2) об освобождении лица, подвергнутого административному задержанию. 4. В случае невозможности прибытия прокурора в 10-минутный срок с момента его вызова задержанное лицо подлежит освобождению, а все имеющиеся материалы дела об административном правонарушении - передаче в прокуратуру РО.","r":"КоАП ст. 16.2.2"},{"d":"КоАП РО","t":"Статья 16.3. Личный досмотр, досмотр вещей, досмотр транспортного средства, находящихся при физическом лице, осмотр принадлежащих юридическому лицу помещений, территорий, находящихся там вещей и документов","x":"Личный досмотр, досмотр вещей, находящихся при физическом лице, то есть обследование вещей, проводимое без нарушения их конструктивной целостности, осмотр принадлежащих юридическому лицу или индивидуальному предпринимателю используемых для осуществления предпринимательской деятельности помещений, территорий и находящихся там вещей и документов производится должностными лицами, производящими производство по делу об административном правонарушении, за совершение которого предусмотрено наказание в виде административного ареста.","r":"КоАП ст. 16.3"},{"d":"КоАП РО","t":"Статья 16.4. Отстранение от управления транспортным средством, освидетельствование на состояние алкогольного опьянения и медицинское освидетельствование на состояние опьянения","x":"1. Лицо, которое управляет транспортным средством соответствующего вида и в отношении которого имеются достаточные основания полагать, что это лицо находится в состоянии опьянения, подлежит отстранению от управления транспортным средством до устранения причины отстранения. 2. Отстранение от управления транспортным средством соответствующего вида, освидетельствование на состояние алкогольного опьянения, направление на медицинское освидетельствование на состояние опьянения осуществляются должностными лицами, которым предоставлено право государственного надзора и контроля за безопасностью движения и эксплуатации транспортного средства соответствующего вида, с применением видеозаписи. 3. Критерии, при наличии которых имеются достаточные основания полагать, что лицо находится в состоянии опьянения и подлежит направлению на медицинское освидетельствование, и порядок проведения медицинского освидетельствования на состояние опьянения устанавливаются федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере здравоохранения.","r":"КоАП ст. 16.4"},{"d":"КоАП РО","t":"Статья 16.5. Задержание транспортного средства","x":"1. В целях пресечения нарушений правил дорожного движения, в том числе нарушений, предусмотренных в части несоблюдения требований, предписанных дорожными знаками или разметкой, запрещающими остановку или стоянку транспортных средств, правил эксплуатации, использования транспортного средства и управления транспортным средством соответствующего вида, применяется задержание (эвакуация) транспортного средства, то есть исключение транспортного средства из процесса перевозки людей и грузов путем перемещения его при помощи другого транспортного средства и помещения на свободную парковку общего пользования. 2. Задержание транспортного средства прекращается непосредственно на месте задержания транспортного средства в присутствии лица, которое может управлять данным транспортным средством, если причина задержания транспортного средства устранена до начала движения транспортного средства и (или) уплачен административный штраф.","r":"КоАП ст. 16.5"},{"d":"КоАП РО","t":"Статья 16.6. Привод","x":"1. В случаях неявки лица на рассмотрение дела об административном правонарушении, при условии что его явка признана судьей, органом, должностным лицом обязательной, применяется привод физического лица либо законного представителя юридического лица, в отношении которых ведется производство по делу об административном правонарушении, привлекаемого к административной ответственности, а также свидетеля. 2. Привод осуществляется органом внутренних дел (полицией), органом федеральной службы безопасности на основании определения указанного органа, иного органа, должностного лица, рассматривающих дело об административном правонарушении, в порядке, установленном федеральным органом исполнительной власти в области внутренних дел.","r":"КоАП ст. 16.6"},{"d":"КоАП РО","t":"Статья 17.1. Возбуждение дела об административном правонарушении","x":"1. Поводами к возбуждению дела об административном правонарушении являются: 1) непосредственное обнаружение должностными лицами, уполномоченными составлять протоколы об административных правонарушениях, достаточных данных, указывающих на наличие события административного правонарушения; 2) поступившие из правоохранительных органов, а также из других государственных органов, от общественных объединений материалы, содержащие данные, указывающие на наличие события административного правонарушения; 3) сообщения и заявления физических и юридических лиц, а также сообщения в средствах массовой информации, содержащие данные, указывающие на наличие события административного правонарушения; 4) фиксация административного правонарушения в области дорожного движения работающими в автоматическом режиме специальными техническими средствами, имеющими функции фото- и киносъемки, видеозаписи, или средствами фото- и киносъемки, видеозаписи. 2. Указанные в части 1 настоящей статьи материалы, сообщения, заявления подлежат рассмотрению должностными лицами, уполномоченными составлять протоколы об административных правонарушениях. 3. Дело об административном правонарушении может быть возбуждено должностным лицом, уполномоченным составлять протоколы об административных правонарушениях, только при наличии хотя бы одного из поводов, предусмотренных частью 1 настоящей статьи, и достаточных данных, указывающих на наличие события административного правонарушения. 4. Дело об административном правонарушении считается возбужденным с момента: 1) применения мер обеспечения производства по делу об…","r":"КоАП ст. 17.1"},{"d":"КоАП РО","t":"Статья 17.2. Протокол об административном правонарушении","x":"1. О совершении административного правонарушения составляется протокол, за исключением случаев, предусмотренных статьями 17.6, 18.6 настоящего Кодекса. 2. В протоколе об административном правонарушении указываются дата и место его составления, должность, имя и фамилия лица, составившего протокол, сведения о лице, в отношении которого возбуждено дело об административном правонарушении, фамилии, имена, адреса места жительства свидетелей и потерпевших, если имеются свидетели и потерпевшие, место, время совершения и событие административного правонарушения, статья настоящего Кодекса или Федерального закона, предусматривающая административную ответственность за данное административное правонарушение, объяснение физического лица или законного представителя юридического лица (при наличии), в отношении которых возбуждено дело, иные сведения, необходимые для разрешения дела. 3. При составлении протокола об административном правонарушении физическому лицу или законному представителю юридического лица, в отношении которых возбуждено дело об административном правонарушении, а также иным участникам производства по делу разъясняются их права и обязанности, предусмотренные настоящим Кодексом. 4. Физическому лицу или законному представителю юридического лица, в отношении которых возбуждено дело об административном правонарушении, по их ходатайству должна быть предоставлена возможность ознакомления с протоколом об административном правонарушении.","r":"КоАП ст. 17.2"},{"d":"КоАП РО","t":"Статья 17.3. Должностные лица, уполномоченные составлять протоколы об административных правонарушениях","x":"1. Протоколы об административных правонарушениях, предусмотренных настоящим Кодексом, составляются должностными лицами органов, уполномоченных рассматривать дела об административных правонарушениях в соответствии с главой 12 настоящего Кодекса, в пределах компетенции соответствующего органа. 2. Помимо случаев, предусмотренных частью 1 настоящей статьи, протоколы об административных правонарушениях вправе составлять должностные лица федеральных органов исполнительной власти, их структурных подразделений и территориальных органов, должностные лица иных государственных органов в соответствии с задачами и функциями, возложенными на них федеральными законами либо нормативными правовыми актами Премьер Министра РО или Правительства РО: 1) Федеральный орган исполнительной власти, осуществляющий федеральный государственный контроль (надзор) в сфере юстиции, об административных правонарушениях, предусмотренных ст. 5.1, 5.3, 6.4, 9.1, 9.2, 9.3, 9.4, 9.5, 10.1, 10.2, 10.4, 10.7, 10.8, 11.2, 11.3, 11.9 настоящего Кодекса; 2) Федеральный орган исполнительной власти, осуществляющий федеральный государственный контроль (надзор) в сфере здравоохранения, об административных правонарушениях, предусмотренных ст. ст. 6.2, 6.5, 6.7, 10.9 настоящего Кодекса.","r":"КоАП ст. 17.3"},{"d":"КоАП РО","t":"Статья 17.4. Возбуждение дел об административных правонарушениях прокурором","x":"1. При осуществлении надзора за соблюдением Конституции РО и исполнением законов, действующих на территории РО, прокурор вправе возбудить дело о любом административном правонарушении, ответственность за которое предусмотрена настоящим Кодексом или Федеральным законом. 2. О возбуждении дела об административном правонарушении прокурором выносится постановление, которое должно содержать сведения, предусмотренные статьей 17.2 настоящего Кодекса. Указанное постановление выносится в сроки, установленные статьей 17.5 настоящего Кодекса.","r":"КоАП ст. 17.4"},{"d":"КоАП РО","t":"Статья 17.5. Сроки составления протокола об административном правонарушении","x":"1. Протокол об административном правонарушении составляется немедленно после выявления совершения административного правонарушения, за исключением случаев, предусмотренных частями 2 и 3 настоящей статьи, ст. 17.6 настоящего Кодекса. 2. В случае, если требуется дополнительное выяснение обстоятельств дела либо данных о физическом лице или сведений о юридическом лице, в отношении которых возбуждается дело об административном правонарушении, протокол об административном правонарушении составляется в течение суток с момента выявления административного правонарушения. 3. В случае проведения административного расследования протокол об административном правонарушении составляется по окончании расследования в сроки, предусмотренные законодательством.","r":"КоАП ст. 17.5"},{"d":"КоАП РО","t":"Статья 17.6. Назначение административного наказания без составления протокола","x":"В случае, если непосредственно после совершения физическим лицом административного правонарушения уполномоченным на то должностным лицом назначается административное наказание в виде предупреждения, административного штрафа или административного ареста, протокол об административном правонарушении не составляется, а выносится решение по делу об административном правонарушении в порядке ст. 18.6 настоящего Кодекса.","r":"КоАП ст. 17.6"},{"d":"КоАП РО","t":"Статья 17.7. Административное расследование","x":"1. При необходимости проведения административного расследования осуществляются экспертиза и иные процессуальные действия, требующие значительных временных затрат. Под административным расследованием понимается комплекс требующих значительных временных затрат процессуальных действий, направленных на выяснение всех обстоятельств административного правонарушения, их фиксирование, юридическую квалификацию и процессуальное оформление. Проведение административного расследования должно состоять из реальных действий, направленных на получение необходимых сведений, в том числе путем проведения экспертизы, установления потерпевших, свидетелей, допроса лиц, проживающих в другой местности. 2. Решение о возбуждении дела об административном правонарушении и проведении административного расследования принимается должностным лицом, уполномоченным в соответствии со статьей 17.3 настоящего Кодекса составлять протокол об административном правонарушении, в виде определения, а прокурором - в виде постановления немедленно после выявления факта совершения административного правонарушения. 3. В определении о возбуждении дела об административном правонарушении и проведении административного расследования указываются дата и место составления определения, должность, фамилия и инициалы лица, составившего определение, повод для возбуждения дела об административном правонарушении, данные, указывающие на наличие события административного правонарушения, статья настоящего Кодекса либо Федерального закона, предусматривающая административную ответственность за данное административное правонарушение. При…","r":"КоАП ст. 17.7"},{"d":"КоАП РО","t":"Статья 17.8. Направление протокола (постановления прокурора) об административном правонарушении для рассмотрения дела об административном правонарушении","x":"1. Протокол (постановление прокурора) об административном правонарушении и другие материалы дела об административном правонарушении направляются судье, в орган, должностному лицу, уполномоченным рассматривать дело об административном правонарушении, незамедлительно с момента составления протокола (вынесения постановления) об административном правонарушении. 2. В случае, если протокол об административном правонарушении составлен неправомочным лицом, а также в иных случаях, предусмотренных настоящим Кодексом, недостатки протокола и других материалов дела об административном правонарушении устраняются в срок не более суток со дня их поступления (получения) от судьи, органа, должностного лица, рассматривающих дело об административном правонарушении. Материалы дела об административном правонарушении с внесенными в них изменениями и дополнениями возвращаются указанным судье, органу, должностному лицу в течение суток со дня устранения соответствующих недостатков.","r":"КоАП ст. 17.8"},{"d":"КоАП РО","t":"Статья 18.1. Подготовка к рассмотрению дела об административном правонарушении","x":"Судья, орган, должностное лицо при подготовке к рассмотрению дела об административном правонарушении выясняют следующие вопросы: 1) относится ли к их компетенции рассмотрение данного дела; 2) имеются ли обстоятельства, исключающие возможность рассмотрения данного дела судьей, членом коллегиального органа, должностным лицом; 3) правильно ли составлены протокол об административном правонарушении и другие протоколы, предусмотренные настоящим Кодексом, а также правильно ли оформлены иные материалы дела; 4) имеются ли обстоятельства, исключающие производство по делу; 5) достаточно ли имеющихся по делу материалов для его рассмотрения по существу; 6) имеются ли ходатайства и отводы.","r":"КоАП ст. 18.1"},{"d":"КоАП РО","t":"Статья 18.2. Отвод судьи, члена коллегиального органа, должностного лица","x":"1. Судья, член коллегиального органа, должностное лицо, на рассмотрение которых передано дело об административном правонарушении, не могут рассматривать данное дело в случае, если это лицо: 1) является родственником лица, в отношении которого ведется производство по делу об административном правонарушении, потерпевшего, законного представителя физического или юридического лица, защитника или представителя; 2) лично, прямо или косвенно заинтересовано в разрешении дела. 2. При наличии обстоятельств, предусмотренных частью 1 настоящей статьи, судья, член коллегиального органа, должностное лицо обязаны заявить самоотвод. Заявление о самоотводе подается председателю соответствующего суда, руководителю коллегиального органа, вышестоящему должностному лицу. 3. При наличии обстоятельств, предусмотренных частью 1 настоящей статьи, лицо, в отношении которого ведется производство по делу об административном правонарушении, потерпевший, законный представитель физического или юридического лица, защитник, представитель, прокурор вправе заявить отвод судье, члену коллегиального органа, должностному лицу, который разрешается этим же лицом.","r":"КоАП ст. 18.2"},{"d":"КоАП РО","t":"Статья 18.3. Назначение дела об административном правонарушении к рассмотрению","x":"1. Судья, орган, должностное лицо, производящее производство по делу об административном правонарушении, установив в порядке письменного производства, что дело достаточно подготовлено для его рассмотрения по существу, выносит определение о назначении дела к рассмотрению, в котором указывает: дату и место вынесения определения; должностное лицо, вынесшее определение; место рассмотрения дела об административном правонарушении; дату и время рассмотрения дела об административном правонарушении; лица, вызванные на рассмотрение дела об административном правонарушении. 2. Определение о назначении дела об административном правонарушении к рассмотрению выносится не позднее чем за 20 часов до времени рассмотрения дела, о чем лица, вызванные на рассмотрение дела, уведомляются не позднее чем за 12 часов до времени рассмотрения дела.","r":"КоАП ст. 18.3"},{"d":"КоАП РО","t":"Статья 18.4. Рассмотрение дела об административном правонарушении","x":"1. Дело об административном правонарушении рассматривается в следующем порядке: 1) объявляется, кто рассматривает дело, какое дело подлежит рассмотрению, кто и на основании какого закона привлекается к административной ответственности; 2) устанавливается факт явки лиц, вызванных на рассмотрение дела; 3) проверяются полномочия законных представителей физического или юридического лица, защитника и представителя; 4) выясняется, извещены ли участники производства по делу в установленном порядке, выясняются причины неявки участников производства по делу и принимается решение о рассмотрении дела в отсутствие указанных лиц либо об отложении рассмотрения дела; 5) разъясняются лицам, участвующим в рассмотрении дела, их права и обязанности; 6) рассматриваются заявленные отводы и ходатайства; 7) стороны по делу озвучивают вступительное слово; 8) опрашиваются свидетели, потерпевшие по делу, лицо, в отношении которого ведется производство по делу; 9) стороны по делу выступают в прениях.","r":"КоАП ст. 18.4"},{"d":"КоАП РО","t":"Статья 18.5. Решение по делу об административном правонарушении","x":"1. По результатам рассмотрения дела об административном правонарушении судья, орган, должностное лицо выносит одно из следующих решений: постановление по делу об административном правонарушении, которое должно содержать: а) должность, фамилию, имя судьи, должностного лица, наименование и состав коллегиального органа, вынесших постановление, их адрес; б) дату и место рассмотрения дела; в) сведения о лице, в отношении которого рассмотрено дело; г) обстоятельства, установленные при рассмотрении дела; д) статью настоящего Кодекса или Федерального закона, предусматривающую административную ответственность за совершение административного правонарушения, либо основания прекращения производства по делу; е) мотивированное решение по делу; ё) срок и порядок обжалования постановления; постановление о прекращении производства по делу об административном правонарушении в случае: а) наличия хотя бы одного из основаций, предусмотренных ч. 1 ст. 13.4 настоящего Кодекса; б) объявления устного замечания в соответствии со статьей 2.5 настоящего Кодекса. 2. Если при решении вопроса о назначении судьей административного наказания за административное правонарушение одновременно решается вопрос о возмещении имущественного ущерба, то в постановлении по делу об административном правонарушении указываются размер ущерба, подлежащего возмещению, сроки и порядок его возмещения. 3. Постановление по делу об административном правонарушении, вынесенное коллегиальным органом, принимается простым большинством голосов членов коллегиального органа, присутствующих на заседании. 4. Постановление по делу об…","r":"КоАП ст. 18.5"},{"d":"КоАП РО","t":"Статья 18.6. Особый порядок рассмотрения дела об административном правонарушении","x":"1. В случае, предусмотренном статьей 17.6 настоящего Кодекса, должностное лицо на месте либо в помещении органа государственной власти, если лицо, в отношении которого ведется производство по делу об административном правонарушении, задержано в порядке ст. ст. 16.2, 16.2.1 настоящего Кодекса, заслушивает объяснения сторон, после чего в устной форме выносит одно из следующих решений: 1) о признании лица, в отношении которого ведется производство по делу об административном правонарушении, виновным в совершении административного правонарушения и назначении ему наказания; 2) о прекращении дела об административном правонарушении и объявлении устного замечания на основании ст. 2.5 настоящего Кодекса; 3) о прекращении дела об административном правонарушении по одному или нескольким основаниям, предусмотренным ч. 1 ст. 13.4 настоящего Кодекса. 2. В случае, предусмотренном статьей 17.6 настоящего Кодекса, если лицо, в отношении которого ведется производство по делу об административном правонарушении, задержано и состоит на государственной службе РО и (или) является должностным лицом органа государственной власти, государственного органа, то дело об административном правонарушении рассматривается в порядке ст. 16.2.2 настоящего Кодекса.","r":"КоАП ст. 18.6"},{"d":"КоАП РО","t":"Статья 19.1. Право на обжалование постановления или решения по делу об административном правонарушении","x":"1. Постановление или решение по делу об административном правонарушении может быть обжаловано лицами, указанными в статьях 14.1 - 14.6 настоящего Кодекса: 1) вынесенное судьей - в вышестоящий суд; 2) вынесенное коллегиальным органом - в городской (окружной) суд по месту нахождения коллегиального органа; 3) вынесенное должностным лицом - в вышестоящий орган, вышестоящему должностному лицу, в прокуратуру либо в суд по месту рассмотрения дела. 2. Постановление или решение по делу об административном правонарушении, вынесенное судьей, может быть также обжаловано в вышестоящий суд органом, должностным лицом, которое составило протокол об административном правонарушении настоящего Кодекса. 3. В случае, если жалоба на постановление или решение по делу об административном правонарушении поступила в суд и в вышестоящий орган, вышестоящему должностному лицу, жалобу рассматривает суд. По результатам рассмотрения жалобы выносится решение. 4. Определение об отказе в возбуждении дела об административном правонарушении обжалуется в соответствии с правилами, установленными настоящей главой.","r":"КоАП ст. 19.1"},{"d":"КоАП РО","t":"Статья 19.2. Порядок подачи жалобы на постановление по делу об административном правонарушении","x":"1. Жалоба на решение по делу об административном правонарушении подается непосредственно в соответствующий суд, вышестоящий орган, вышестоящему должностному лицу в течение 48 часов с момента вынесения решения. 2. В случае, если рассмотрение жалобы не относится к компетенции судьи, должностного лица, которым обжаловано постановление по делу об административном правонарушении, жалоба направляется на рассмотрение по подведомственности в течение суток. 3. Жалоба на постановление по делу об административном правонарушении государственной пошлиной не облагается.","r":"КоАП ст. 19.2"},{"d":"КоАП РО","t":"Статья 19.3. Решение по жалобе на постановление по делу об административном правонарушении","x":"По результатам рассмотрения жалобы на постановление по делу об административном правонарушении выносится одно из следующих решений: 1) об оставлении постановления без изменения, а жалобы без удовлетворения; 2) об изменении постановления, если при этом не усиливается административное наказание или иным образом не ухудшается положение лица, в отношении которого вынесено постановление; 3) об отмене постановления и о прекращении производства по делу при наличии оснований, предусмотренных п. 2 ч. 1 ст. 18.5 настоящего Кодекса, а также при недоказанности обстоятельств, на основании которых было вынесено постановление; 4) об отмене постановления и о возвращении дела на новое рассмотрение судье, в орган, должностному лицу, правомочным рассмотреть дело, в случаях существенного нарушения процессуальных требований, предусмотренных настоящим Кодексом, если это не позволило всесторонне, полно и объективно рассмотреть дело, а также в связи с необходимостью применения закона об административном правонарушении, влекущем назначение более строгого административного наказания, если потерпевшим по делу подана жалоба на мягкость примененного административного наказания; 5) об отмене постановления и о направлении дела на рассмотрение по подведомственности, если при рассмотрении жалобы установлено, что постановление было вынесено неправомочными судьей, органом, должностным лицом.","r":"КоАП ст. 19.3"},{"d":"КоАП РО","t":"Статья 19.4. Пересмотр решения, вынесенного по жалобе на постановление по делу об административном правонарушении","x":"1. Постановление по делу об административном правонарушении, вынесенное должностным лицом, и (или) решение вышестоящего должностного лица по жалобе на это постановление могут быть обжалованы в суд по месту рассмотрения жалобы, а затем в вышестоящий суд. 2. Постановление по делу об административном правонарушении, вынесенное коллегиальным органом, и (или) решение судьи по жалобе на это постановление могут быть обжалованы в вышестоящий суд. 3. Подача последующих жалоб на постановление по делу об административном правонарушении и (или) решения по жалобе на это постановление, их рассмотрение и разрешение осуществляются в порядке и в сроки, установленные статьями 19.2 - 19.3 настоящего Кодекса. 4. Решение суда по жалобе на вынесенное должностным лицом постановление по делу об административном правонарушении может быть обжаловано помимо участника производства органом, должностным лицом, которое вынесло такое постановление.","r":"КоАП ст. 19.4"},{"d":"КоАП РО","t":"Статья 19.5. Решение по жалобе на решение по жалобе на постановление по делу об административном правонарушении","x":"По результатам рассмотрения жалобы на решение по жалобе на постановление по делу об административном правонарушении выносится одно из следующих решений: 1) об оставлении постановления и решения без изменения, а жалобы без удовлетворения; 2) об изменении постановления или решения, если при этом не усиливается административное наказание или иным образом не ухудшается положение лица, в отношении которого вынесено постановление; 3) об отмене решения и направлении жалобы на постановление по делу на новое рассмотрение уполномоченному на это лицу; 4) об отмене решения и постановления и направлении дела об административном правонарушении на рассмотрение уполномоченному на это лицу. Одобрен Государственной Думой 21 августа 2026 года Подписан Премьер-Министром РО 21 августа 2026 года","r":"КоАП ст. 19.5"},{"d":"Лекция «Постовая служба»","t":"Общее","x":"# Лекция: Постовая служба Автор: Инст.ОМОН | В.Спасская | 27564 (Майор). Даты: 29.08 – 04.09.2026. Схема постов (Google Docs): https://docs.google.com/document/d/19sdovoOBFjQMLX88zS3jm_zHjUxrcbWXFVT9O7cO-qk/edit?tab=t.0 > Постовая служба — одна из ключевых задач военнослужащего: защита территории от несанкционированного проникновения и поддержание порядка на посту.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"1. Шаблоны докладов в `/f` — главное для отчёта","x":"Формат единый, меняется только средняя часть: /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - заступил на пост - состояние стабильное - доклад окончил. /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - состояние стабильное - доклад окончил. /f Докладывает [Звание] Росгвардии [Имя Фамилия] - время [ЧЧ:ММ] - [КПП№N Алабино / Вышка \"Название\"] - пост сдал - состояние стабильное - доклад окончил.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"Эталонный пример (из лекции)","x":"/f Докладывает Полковник Росгвардии Василиса Спасская - время 16:00 - КПП№1 Алабино - заступил на пост - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:15 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:30 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 16:45 - КПП№1 Алабино - состояние стабильное - доклад окончил. /f Докладывает Полковник Росгвардии Василиса Спасская - время 17:00 - КПП№1 Алабино - пост сдал - состояние стабильное - доклад окончил. ⚠️ Чат — /f (IC, рация), не /fb. Доклад каждые 15 минут.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"2. Расстановка постов (полигон Алабино)","x":"Пост — Расстановка — Кол-во КПП №1 Алабино — Два военнослужащих слева и справа от ворот, один за воротами — 3 КПП №2 Алабино — Два военнослужащих слева и справа от шлагбаума, один за шлагбаумом — 3 Наблюдательная вышка Алабино — Два военнослужащих — 2 Вышка «Оружейки» — Один военнослужащий — 1 Вышка «Огневой рубеж» — Один военнослужащий — 1 Вышка «Лагерь» — Один военнослужащий — 1 При заступлении в рации указывается конкретный пост (КПП или вышка).","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"3. Основные задачи караульного","x":"1. Охрана КПП — не допустить проникновение лиц без соответствующих разрешений. 2. Регулярные доклады — о ситуации на посту каждые 15 минут. 3. Доклад при заступлении — в рацию /f, с указанием КПП/вышки. 4. Экипировка — заступать только в полной: бронежилет, оружие, патроны, сухпайки. 5. Знание командного состава — знать в лицо высокопоставленных чинов армии. 6. Проверка документов — у всех прибывающих: паспорт, служебное удостоверение, жетон, бейджик. 7. Вежливое общение — тактично, независимо от ситуации. 8. Взаимодействие с гос. структурами (ФСБ, ГИБДД, Больница, Правительство): - узнать цель прибытия; - запросить служебные удостоверения; - сообщить по рации о прибытии и ожидать указаний.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"4. Действия при проникновении","x":"1. Немедленно сообщить по рации — это позволяет оперативно организовать оборону. 2. Усилить бдительность — быть готовым к возможной атаке на пост. 3. При отсутствии прямой угрозы — задержать, выяснить обстоятельства, вывести за территорию.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"Категорически запрещено при проникновении","x":"- Покидать пост для нейтрализации нарушителей. - Игнорировать проникновение. - Паниковать и нарушать порядок на посту. - Самостоятельно вызывать поддержку других силовых структур (ФСБ, МВД). - Самостоятельно транспортировать задержанных в правоохранительные органы — это задача Военной Полиции.","r":"Лекция «Постовая служба»"},{"d":"Лекция «Постовая служба»","t":"5. Караульному запрещено","x":"1. Отдавать, продавать табельное оружие, боеприпасы, форму и спец. принадлежности. 2. Покидать пост без причины или разрешения, а также не доложив об этом по рации. Пропускать через КПП посторонних лиц без разрешения старшего состава. *Исключение:* лица с доступом к ЗОТ — после проверки документов. 3. Спать на посту. 4. Вступать в контакт с гражданскими на КПП. *Исключение:* проверка документов, удостоверяющих личность, и цели визита. 5. Заступать в караул без полного боекомплекта и обмундирования. 6. Вести себя неподобающим образом: хамить гражданским и военнослужащим, сидеть или лежать на посту, включать музыку, танцевать, выполнять физ. упражнения. 7. Пользоваться мобильными средствами связи. 8. Открывать огонь по гражданским без видимой причины; доставать оружие без угрозы для жизни.","r":"Лекция «Постовая служба»"},{"d":"Лекция по субординации","t":"Общее","x":"# Лекция: Субординация Автор: Инст.ОМОН | В.Спасская | 27564 (Майор). Дата: 29.08.2026.","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Понятие","x":"Субординация — строго установленная система подчинения по званию и должности, а также правила общения и поведения между военнослужащими. В Армии субординация: - обеспечивает чёткое выполнение приказов; - исключает хаос и самоуправство; - поддерживает уважение к званиям и командованию; - повышает эффективность подразделения.","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Иерархия","x":"Каждый военнослужащий обязан: - знать своё звание; - знать, кому он подчиняется. > Принцип: приказ старшего по званию или должности обязателен к выполнению, если он не нарушает устав и правила сервера.","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Речевые формулы — выучить дословно","x":"Ситуация — Ответ Согласие — «Так точно» Несогласие — «Никак нет» Получен приказ — «Есть» Хотите обратиться — «[Звание] [Фамилия], разрешите обратиться» Не знаете ответа — «Не могу знать» Обращение к старшим по званию — с использованием звания, в уважительной форме. С уважением обращаться нужно ко всем военнослужащим, независимо от их должности.","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Выполнение приказов","x":"Приказ — официальное распоряжение руководителя / командира / старшего по званию, обязательное для исполнения подчинёнными. Приказ: - выполняется быстро, точно, без личной инициативы; - не обсуждается публично; - может быть уточнён, если неясен.","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Запрещено","x":"- игнорировать приказ; - спорить с командиром; - самовольно менять задачу (проявлять инициативу); - выполнять приказы не от своего командира без разрешения.","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Дисциплинарная ответственность","x":"За нарушения правил внутреннего распорядка, внутреннего устава, НПА, а также уголовного, этического и трудового кодексов применяются взыскания: 1. устное предупреждение; 2. выговор (устный или строгий); 3. переаттестация; 4. понижение в звании; 5. увольнение из Армии (в тяжёлых случаях или при многочисленных нарушениях).","r":"Лекция по субординации"},{"d":"Лекция по субординации","t":"Примеры нарушений","x":"Нарушение — Статья — Взыскание Вступать в неуставные отношения, спор или конфликт со старшим по званию — Ст. 23 ДУ — Предупреждение или выговор Игнорировать приказы старшего состава — ВУ ст. 1.3 (Беспрекословное выполнение приказов), ст. 5.4 (Сущность воинской дисциплины) — —","r":"Лекция по субординации"},{"d":"Лекция «Строевая подготовка»","t":"Термины","x":"Термин — Определение Строй — Установленное Уставом размещение военнослужащих, подразделений и воинских частей для их совместных действий в пешем порядке и на машинах Шеренга — Строй, в котором военнослужащие размещены один возле другого на одной линии на установленных интервалах Колонна — Строй, в котором военнослужащие расположены в затылок друг другу, а подразделения (машины) — одно за другим на дистанциях, установленных Уставом или командиром","r":"Лекция «Строевая подготовка»"},{"d":"Лекция «Строевая подготовка»","t":"Военнослужащим запрещено","x":"- Прогуливать либо опаздывать на построение без веской причины. - Самовольно покидать строй, а также вставать в уже сформированный строй без разрешения. → При опоздании: «[Звание] [Фамилия], разрешите встать в строй». - Выталкивать других военнослужащих из строя. - Совершать любые движения без команды (переодевать бронежилет, доставать оружие, доставать телефон и т.п.). - Разговаривать и издавать звуки без разрешения старших в строю. - Есть, пить, курить и совершать прочие повседневные действия вне построений. - Спать во время построения.","r":"Лекция «Строевая подготовка»"},{"d":"Лекция «Строевая подготовка»","t":"Вечернее построение","x":"- Проводится в дни, указанные генералитетом в новостях армии. О построении сообщается в общую рацию. - Каждое подразделение докладывает о проделанной за день работе. - До личного состава доводится информация. - Нарушать дисциплину в строю запрещено (телефон, разговоры, сон, самовольный выход, непристойные движения). - Перед тем как встать в строй — снять бронежилет и убрать оружие из-за спины.","r":"Лекция «Строевая подготовка»"},{"d":"Лекция «Строевая подготовка»","t":"Доклад старшего в подразделении начальнику","x":"[Начальник] Ответственный офицер, рота ведомственной охраны. [Старший] Я! [Начальник] Выйдите из строя, подойдите ко мне! [Старший] Есть! *Старший выходит из строя, по кратчайшей траектории подходит к начальнику, с последним шагом выполняет воинское приветствие. Начальник выполняет воинское приветствие.* [Старший] Товарищ [Звание], [Ваше звание/должность] по вашему приказанию прибыл! [Начальник] [Звание] [Фамилия Имя], доложить о проделанной работе за день! [Старший] Есть! Рота ведомственной охраны в составе [Кол-во] человек, для проведения вечерней поверки построена, лиц незаконно отсутствующих не выявлено. За [Число] [Месяц] Рота Ведомственной Охраны работала в штатном режиме, [что было проделано за день от вашего подразделения]. Жалоб и заявлений среди военнослужащих не выявлено. [Ваша должность/ранг] роты ведомственной охраны, [Фамилия Имя]. [Начальник] Вольно, стать в строй! *Начальник опускает руку.* [Старший] Есть! *Старший поворачивается к своему подразделению.* [Старший] Вольно! *С первым шагом опускает руку и возвращается на место в строю.*","r":"Лекция «Строевая подготовка»"},{"d":"Принятие присяги","t":"Общее","x":"# Принятие присяги Когда: ежедневно 12:00 и 20:00 на плацу, а также в любое время по договорённости. О начале построения на присягу старший офицер докладывает в новости. Требование для повышения ранг 2 → 3. По ст. 1.11 Устава ВС присяга обязательна для каждого прибывшего в часть; отказ или грубое нарушение — основание для увольнения. > Присяга для ФСВНГ проводится отдельно от ВС РФ — будьте внимательны.","r":"Принятие присяги"},{"d":"Принятие присяги","t":"Как проходит присяга","x":"Инструктор собирает построение на плацу. Из строя поочерёдно вызывается один человек. Форма одежды: принимающий — «Парадный китель с брюками», дающий присягу — «Парадный мундир с брюками». Выбирается в меню F2 → Комплекты одежды → Фракционные.","r":"Принятие присяги"},{"d":"Принятие присяги","t":"Вызов из строя","x":"Инструктор: Курсант (Фамилия) Курсант: Я Инструктор: Для принятия торжественной присяги ко мне! Курсант: Есть Курсант выходит из строя, подходит к офицеру по кратчайшей траектории и с последним шагом выполняет воинское приветствие — отдаёт честь. Только после этого докладывает: Товарищ Старший сержант, курсант (Фамилия) для принятия военной присяги прибыл! > Честь отдать обязательно. Доклад без воинского приветствия — нарушение порядка доклада и обращения к старшему, ст. 8 ДУ.","r":"Принятие присяги"},{"d":"Принятие присяги","t":"Передача текста","x":"Инструктор: /me протянул папку с текстом присяги в руки новобранцу Курсант: /me взял папку с текстом присяги в руки","r":"Принятие присяги"},{"d":"Принятие присяги","t":"Принятие","x":"Инструктор: Военную присягу принять! Курсант: Есть Курсант поворачивается лицом к строю и произносит текст присяги — уже держа папку в руках: Я, (Фамилия Имя), торжественно присягаю на верность своему Отечеству — Российской Федерации. Клянусь свято соблюдать Конституцию Российской Федерации, строго выполнять требования воинских уставов, приказы командиров и начальников. Клянусь достойно исполнять воинский долг, мужественно защищать свободу, независимость и конституционный строй России, народ и Отечество. Курсант докладывает о принятии: Товарищ Старший сержант, курсант (Фамилия) военную присягу принял!","r":"Принятие присяги"},{"d":"Принятие присяги","t":"Завершение","x":"Инструктор: /do Присяга успешно принята новобранцем — Имя Фамилия. Поздравляю с принятием присяги, встать в строй Курсант: Есть Курсант возвращается в строй, вызывается следующий.","r":"Принятие присяги"},{"d":"Принятие присяги","t":"На что смотрят при проверке отчёта","x":"- Присяга отыгрывается, не пишется текстом. Письменная форма — только по веской причине, заранее согласованной с руководством. - Перед тем как встать в строй — снять бронежилет и убрать оружие из-за спины. - На плацу нельзя: телефон, разговоры, приём пищи, курение, неформальный вид — ст. 21 ДУ. Курение — ещё и ст. 12.1. - Имя и фамилия в полной форме: Алексей, а не Лёха.","r":"Принятие присяги"},{"d":"Система повышения","t":"Общее","x":"# Система повышения курсантов ФСВНГ Путь от 1 ранга до военного билета. Актуальная редакция на 17.09.2026.","r":"Система повышения"},{"d":"Система повышения","t":"Ранг 1 → 2","x":"Пять требований. Выезд за территорию ВЧ — только в сопровождении сотрудников Кадровой службы ФСВНГ, самостоятельный выезд запрещён. # — Требование — Что нужно сделать 1 — Удостоверение — Получить в здании правительства 2 — Лекция по внутренним НПА — Прослушать. Инструктор проводит её разово, сразу по всем шести документам 3 — Лекция-экскурсия по ВЧ — Прослушать 4 — Государственная спец. связь — Присоединиться и получить роль, инструкция ниже 5 — Занятие по физподготовке — 2 скриншота: начало и конец тренировки","r":"Система повышения"},{"d":"Система повышения","t":"Шесть документов лекции по НПА","x":"1. Лекция «Постовая служба» 2. Лекция по субординации 3. Лекция «Строевая подготовка» 4. Дресс-код ФСВНГ 5. Дисциплинарный устав 6. Устав ВС РФ и ФСВНГ Экзамен на этом этапе не сдаётся — он перенесён на этап 2 → 3 и сдаётся один раз по всему материалу целиком, а не по каждому блоку.","r":"Система повышения"},{"d":"Система повышения","t":"Подключение к спец. связи","x":"Четыре шага. Результат — скриншот профиля с ролью Тверской и ником по форме. 1. Присоединиться к спец. связи «Государственные фракции РО»: https://discord.gg/5kTutqS8K 2. Нажать «Получить роль». Получение роли гос. служащего пока недоступно — получаете только Тверской: https://discord.com/channels/1538879177917210668/1538884293592354900/1543186737965309994 3. После этого появится сообщение о получении роли 4. Отредактировать свой ник по форме: Армия | Имя Фамилия | Статик","r":"Система повышения"},{"d":"Система повышения","t":"Что идёт в отчёт","x":"- Скриншот профиля с ролью Тверской - Ник строго по форме Армия | Имя Фамилия | Статик","r":"Система повышения"},{"d":"Система повышения","t":"Ранг 2 → 3","x":"# — Требование — Доказательства 1 — Принятие присяги — 1 скриншот. Отыгровка по процедуре 2 — Стрельбище — 2 скриншота: начало и завершение занятия 3 — Тренировочная площадка — 2 скриншота: начало и конец полосы препятствий 4 — Караул на КПП №1 или КПП №2 Алабино — 1 час — 5 скриншотов каждые 15 минут с докладом в /f 5 — Экзамен по внутренним НПА ФСВНГ — 1 скриншот результата. Один экзамен сразу по всем шести документам","r":"Система повышения"},{"d":"Система повышения","t":"Тайминг караула","x":"Заступили в 16:00 → скриншоты в 16:00, 16:15, 16:30, 16:45, 17:00. Первый — заступление на пост, последний — сдача поста.","r":"Система повышения"},{"d":"Система повышения","t":"После 3 ранга","x":"Выбор подразделения — самостоятельный: ОМОН, РВО, ОСБ или Кадровая служба ФСВНГ.","r":"Система повышения"},{"d":"Система повышения","t":"Порядок подачи","x":"Шаг 1. Отчёт на повышение — подаётся через Google-форму: https://docs.google.com/forms/d/e/1FAIpQLSfbwGdN5GDH8ZOyQWyjBuToUWGr-g03veAsFkhylA7lY7-Dsw/viewform Шаг 2. Запрос на повышение — только после одобрения отчёта, в канал запроса, со ссылкой на одобренный отчёт.","r":"Система повышения"},{"d":"Система повышения","t":"Форма запроса","x":"@Ваш тэг 1. Имя Фамилия Статик 2. Текущий ранг - ранг на который повышаетесь 3. Ссылка на одобренный отчет на повышение @[👮] Инструктор КС ФСВНГ","r":"Система повышения"},{"d":"Система повышения","t":"Пример","x":"@!Комиссар | В. Гуров | 13053 1. Владислав Гуров 13053 2. 2-3 ранг 3. [ссылка на одобренный отчёт] @[👮] Инструктор КС ФСВНГ Заявка не по форме не рассматривается. Последней строкой всегда @[👮] Инструктор КС ФСВНГ.","r":"Система повышения"},{"d":"Система повышения","t":"Военный билет","x":"Подаётся по достижении 6 ранга в #запрос-военных-билетов. После подачи найти старший состав ФСВНГ и попросить выдать билет.","r":"Система повышения"},{"d":"Система повышения","t":"Доказательства","x":"Принимаются фото и видео только с этих сервисов: YouTube, Rutube, Google Drive, Yandex Disk, imgur, Yapx, Prnt, ibb. Фиксация должна исчерпывающе подтверждать выполнение требования. Правила приёма скриншотов уточняются у Кадровой службы.","r":"Система повышения"},{"d":"Частые ошибки в отчётах","t":"Общее","x":"# Частые ошибки при оформлении отчётов Источник: сообщение Нач.КС от 08.09.2026. За эти нарушения отчёт отклоняется.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"1. Отсутствие бодикамеры","x":"- Проект RP → бодикамера обязательна. - На скриншотах должна быть плашка бодикамеры с красным индикатором. - Бодикамера носится везде, кроме построения на плацу. Настройка: F2 → Настройки → Назначение клавиш → Бодикамера → назначить удобную клавишу.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"2. Путаница чатов `/f` и `/fb`","x":"Чат — Тип — Назначение /f — IC (in-character) — Общение по рации в рамках RP. Доклады с караула — сюда /fb — OOC (out-of-character) — Вне роли: реальная жизнь, Discord и т.п.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"3. Редактирование скриншотов — запрещено","x":"Нельзя: - делать частичный скриншот; - обрезать скриншоты; - использовать Photoshop и другие редакторы; - каким-либо образом изменять исходный скриншот. Обнаруженное редактирование = попытка ввести руководство в заблуждение → выговор. > Практический вывод: снимать полный экран целиком, отдавать файл как есть.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"4. Неправильный скриншот Discord","x":"- Нужен скриншот Discord своей фракции, а не общего Discord гос. фракций (State). - На скриншоте обязательно видны роли вашего аккаунта на сервере.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"5. Присяга в письменной форме","x":"- Все действия отыгрываются, проект RP. - Письменная форма — только по веской причине, о которой заранее сообщено руководству.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"6. Некорректные имя и фамилия","x":"Имя и фамилия — в нормальной форме. ❌ Недопустимо — ✅ Правильно Лёха — Алексей Тошик — Антон Данька — Даниил / Данил До исправления ФИО отчёты могут отклоняться.","r":"Частые ошибки в отчётах"},{"d":"Частые ошибки в отчётах","t":"7. Заполнение отчёта не по форме","x":"Перед подачей проверить: - [ ] все ли пункты заполнены; - [ ] соблюдена ли последовательность пунктов; - [ ] не изменена ли структура формы; - [ ] соответствуют ли приложенные доказательства указанным пунктам. Перепутанные пункты или изменённая последовательность → отклонение.","r":"Частые ошибки в отчётах"},{"d":"Требования к доказательствам","t":"Допустимые хостинги","x":"Фото/видео фиксация принимается только с: Тип — Сервисы Видео — YouTube, Rutube Облако — Google Drive, Yandex Disk Картинки — imgur, Yapx, Prnt, ibb > Фиксация должна иметь исчерпывающие доказательства, подтверждающие то или иное деяние. Правила приёма скриншотов — канал «Требования к скриншотам для отчётов».","r":"Требования к доказательствам"},{"d":"Требования к доказательствам","t":"Чек-лист перед загрузкой каждого скриншота","x":"- [ ] Полный экран, без обрезки и редактирования - [ ] Видна плашка бодикамеры с красным индикатором — камера включена везде, кроме построения на плацу - [ ] Виден игровой ник по форме Армия| Имя Фамилия | Статик - [ ] Виден таймер/время, если действие привязано ко времени (караул) - [ ] Доклад написан в /f, а не в /fb - [ ] Ссылка открывается без авторизации (доступ по ссылке для Google/Yandex Disk)","r":"Требования к доказательствам"}];
